 x:{lang:"python", code:'from collections import deque\n\ndef shortest_path(graph, start, goal):\n    q, seen = deque([(start, [start])]), {start}\n    while q:\n        node, path = q.popleft()\n        if node == goal: return path\n        for nb in graph[node]:\n            if nb not in seen:\n                seen.add(nb)\n                q.append((nb, path + [nb]))\n    return None'},
