    "o": [
      "$\\mathcal{L} = \\|v_t - v_c\\|_2^2$",
      "$\\mathcal{L}_{\\text{SGNS}} = \\log \\sigma(v_c'^T v_t) + \\sum_{i=1}^k \\mathbb{E}_{w_i \\sim P_n(w)} \\left[ \\log \\sigma(-v_{w_i}'^T v_t) \\right]$",
      "$\\mathcal{L} = -\\log \\text{softmax}(v_c'^T v_t)$",
      "$\\mathcal{L} = v_c^T v_t$"
    ],
